PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?investor ?investorName ?segment ?liquidityScore ?bankingAllocation ?underfundedGoalCount
WHERE {
    ?investor a wm:Investor ;
              wm:investorId ?investorId ;
              wm:investorName ?investorName ;
              wm:segment ?segment .
    FILTER (?segment = "Large Cap")

    ?health a wm:PortfolioHealth ;
            wm:healthOfInvestor ?investor ;
            wm:liquidityScore ?liquidityScoreRaw .
    BIND(xsd:decimal(?liquidityScoreRaw) AS ?liquidityScore)
    FILTER (?liquidityScore < 50)

    ?allocation a wm:SectorAllocation ;
                wm:allocationOfInvestor ?investor ;
                wm:sector "Banking" ;
                wm:allocationPct ?allocationPctRaw .
    BIND(xsd:decimal(?allocationPctRaw) AS ?bankingAllocation)
    FILTER (?bankingAllocation > 0)

    {
        SELECT ?investor (COUNT(DISTINCT ?goal) AS ?underfundedGoalCount)
        WHERE {
            ?goal a wm:InvestmentGoal ;
                  wm:belongsToInvestor ?investor ;
                  wm:progressPct ?progressPctRaw .
            BIND(xsd:decimal(?progressPctRaw) AS ?progressPct)
            FILTER (?progressPct < 100)
        }
        GROUP BY ?investor
        HAVING (?underfundedGoalCount >= 1)
    }
}
ORDER BY ?investorName

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasSegment/wm:label "Mid Cap" ;
            wm:hasPortfolioHealth/wm:liquidityScore ?liquidityScore ;
            wm:hasInvestmentGoal ?goal .

  ?goal wm:progressPct ?progressPct .

  ?investor wm:hasSectorAllocation ?allocation .
  ?allocation wm:hasSector/wm:label "Automobile" ;
              wm:allocationPct ?autoAlloc .

  FILTER (xsd:decimal(?liquidityScore) < 50)
  FILTER (xsd:decimal(?autoAlloc) > 0)
  FILTER (xsd:decimal(?progressPct) < 100)
}

