PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?timeHorizonLabel
       (ROUND(AVG(?totalInvestment), 2) AS ?avgTotalSectorInvestment)
       (ROUND(AVG(?avgReturnPerInvestor), 2) AS ?avgHoldingReturn)
       (ROUND(AVG(?riskScoreVal), 2) AS ?avgRiskScore)
       (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  {
    # Pre-aggregate sector allocation per investor
    SELECT ?investor (SUM(xsd:decimal(?sectorAllocTotal)) AS ?totalInvestment)
    WHERE {
      ?sectorAlloc a wm:SectorAllocation ;
                   wm:allocationOfInvestor ?investor ;
                   wm:totalInvestment ?sectorAllocTotal .
    }
    GROUP BY ?investor
  }
  {
    # Pre-aggregate holdings return per investor
    SELECT ?investor (AVG(xsd:decimal(?holdingReturn)) AS ?avgReturnPerInvestor)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:returnsPct ?holdingReturn .
      FILTER(?holdingReturn != "" && xsd:decimal(?holdingReturn) IS NOT NULL)
    }
    GROUP BY ?investor
  }
  {
    # Get risk score per investor
    SELECT ?investor (xsd:decimal(?score) AS ?riskScoreVal)
    WHERE {
      ?health a wm:PortfolioHealth ;
              wm:healthOfInvestor ?investor ;
              wm:riskScore ?score .
    }
  }
  ?investor a wm:Investor ;
            wm:hasTimeHorizon ?timeHorizon .
  ?timeHorizon rdfs:label ?timeHorizonLabel .
}
GROUP BY ?timeHorizonLabel
ORDER BY ?timeHorizonLabel

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?segment
       (ROUND(AVG(?holdings_count), 2) AS ?avg_holdings_per_investor)
       (ROUND(AVG(?rebalancing_count), 2) AS ?avg_rebalancing_actions_per_investor)
       (ROUND(AVG(?risk_score), 2) AS ?avg_risk_score)
WHERE {
  {
    SELECT ?investor ?segment (COUNT(DISTINCT ?holding) AS ?holdings_count)
    WHERE {
      ?investor a wm:Investor ;
                 wm:segment ?segment .
      OPTIONAL {
        ?holding a wm:PortfolioHolding ;
                 wm:heldByInvestor ?investor .
      }
    }
    GROUP BY ?investor ?segment
  }
  {
    SELECT ?investor (COUNT(DISTINCT ?rebalancing) AS ?rebalancing_count)
    WHERE {
      ?investor a wm:Investor .
      OPTIONAL {
        ?rebalancing a wm:RebalancingAction ;
                     wm:rebalancingActionOfInvestor ?investor .
      }
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (MAX(xsd:decimal(?score)) AS ?risk_score)
    WHERE {
      ?investor a wm:Investor .
      OPTIONAL {
        ?health a wm:PortfolioHealth ;
                wm:healthOfInvestor ?investor ;
                wm:riskScore ?score .
      }
    }
    GROUP BY ?investor
  }
}
GROUP BY ?segment
ORDER BY ?segment

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
