PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?segment
       (ROUND(AVG(?totalInvestment), 2) AS ?avg_total_sector_investment)
       (ROUND(AVG(?avg_holding_return), 2) AS ?avg_holding_return_per_investor)
       (ROUND(AVG(?riskScore), 2) AS ?avg_risk_score)
WHERE {
  {
    SELECT ?investor ?segment
           (SUM(xsd:decimal(?allocationTotalInvestment)) AS ?totalInvestment)
    WHERE {
      ?investor a wm:Investor ;
                wm:segment ?segment .
      ?allocation a wm:SectorAllocation ;
                  wm:allocationOfInvestor ?investor ;
                  wm:totalInvestment ?allocationTotalInvestment .
    }
    GROUP BY ?investor ?segment
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?returnsPct)) AS ?avg_holding_return)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue ;
               wm:returnsPct ?returnsPct .
      FILTER (?cost > 0 && ?currentValue >= 0)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (xsd:decimal(?score) AS ?riskScore)
    WHERE {
      ?health a wm:PortfolioHealth ;
              wm:healthOfInvestor ?investor ;
              wm:riskScore ?score .
    }
  }
}
GROUP BY ?segment
ORDER BY ?segment

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?categoryLabel
       (ROUND(AVG(?holdingsCount), 2) AS ?avgHoldingsPerInvestor)
       (ROUND(AVG(?rebalancingCount), 2) AS ?avgRebalancingActionsPerInvestor)
       (ROUND(AVG(?riskScore), 2) AS ?avgRiskScore)
WHERE {
  {
    SELECT ?investor ?categoryLabel
           (COUNT(DISTINCT ?holding) AS ?holdingsCount)
    WHERE {
      ?investor a wm:Investor ;
                wm:hasCategory/wm:label ?categoryLabel .
      OPTIONAL {
        ?investor wm:hasHolding ?holding .
      }
    }
    GROUP BY ?investor ?categoryLabel
  }
  {
    SELECT ?investor
           (COUNT(DISTINCT ?rebalancingAction) AS ?rebalancingCount)
    WHERE {
      ?investor a wm:Investor .
      OPTIONAL {
        ?investor wm:hasRebalancingAction ?rebalancingAction .
      }
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor
           (MAX(xsd:decimal(?riskScoreVal)) AS ?riskScore)
    WHERE {
      ?investor a wm:Investor .
      OPTIONAL {
        ?investor wm:hasPortfolioHealth ?health .
        ?health wm:riskScore ?riskScoreVal .
      }
    }
    GROUP BY ?investor
  }
}
GROUP BY ?categoryLabel
ORDER BY ?categoryLabel

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?category (COUNT(DISTINCT ?investor) AS ?distinctInvestorCount)
WHERE {
  ?investor a wm:Investor ;
            wm:hasCategory/wm:rdfs:label ?category ;
            wm:hasPortfolioHealth/wm:riskScore ?riskScore .

  FILTER(xsd:decimal(?riskScore) > 25)

  ?holding a wm:PortfolioHolding ;
           wm:heldByInvestor ?investor ;
           wm:hasInvestmentType/wm:rdfs:label "Equity" .

  ?cashFlow a wm:CashFlow ;
            wm:cashFlowOfInvestor ?investor ;
            wm:hasCashFlowType/wm:rdfs:label "SIP" .
}
GROUP BY ?category
ORDER BY ?category

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?segment (ROUND(AVG(?netCashFlow), 2) AS ?avg_net_cash_flow)
       (ROUND(AVG(?avgProgressPct), 2) AS ?avg_goal_progress)
       (ROUND(AVG(?riskScore), 2) AS ?avg_risk_score)
       (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cashFlowAmount .
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?avgProgressPct)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?investor
  }
  ?investor a wm:Investor ;
            wm:hasSegment/wm:label ?segment ;
            wm:hasPortfolioHealth/wm:riskScore ?riskScore .
}
GROUP BY ?segment
ORDER BY ?segment

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance 
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow) 
       (ROUND(AVG(?signedAmount), 2) AS ?avgSignedCashFlowAmount) 
       (ROUND(AVG(?cashFlowCount), 2) AS ?avgCashFlowCount) 
       (COUNT(DISTINCT ?investorId) AS ?investorCount)
WHERE {
  {
    SELECT ?investorId ?riskTolerance (SUM(?amount) AS ?netCashFlow) (COUNT(?cashFlowId) AS ?cashFlowCount)
    WHERE {
      ?investor a wm:Investor ;
                 wm:investorId ?investorId ;
                 wm:hasRiskTolerance ?riskToleranceIRI .
      ?riskToleranceIRI rdfs:label ?riskTolerance .

      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:cashFlowId ?cashFlowId ;
                wm:amount ?amountStr .
      BIND(xsd:decimal(?amountStr) AS ?amount)
    }
    GROUP BY ?investorId ?riskTolerance
  }
  BIND(ABS(?netCashFlow) AS ?signedAmount)
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?totalInvestment), 2) AS ?avgTotalSectorInvestment)
       (ROUND(AVG(?allocationPct), 2) AS ?avgAllocationPercentage)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskToleranceObj .
  ?riskToleranceObj rdfs:label ?riskTolerance .

  ?sectorAlloc a wm:SectorAllocation ;
               wm:allocationOfInvestor ?investor ;
               wm:totalInvestment ?totalInvestment ;
               wm:allocationPct ?allocationPct .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskToleranceLabel (ROUND(AVG(?allocationShift), 2) AS ?avgScenarioShift) (ROUND(AVG(?scenarioCount), 2) AS ?avgScenarioCount)
WHERE {
  {
    SELECT ?investor ?riskToleranceLabel (SUM(xsd:decimal(?newAllocation) - xsd:decimal(?currentAllocation)) AS ?allocationShift) (COUNT(?scenario) AS ?scenarioCount)
    WHERE {
      ?investor a wm:Investor ;
                 wm:hasRiskTolerance ?riskTolerance ;
                 wm:investorId ?investorId .
      ?riskTolerance rdfs:label ?riskToleranceLabel .
      OPTIONAL {
        ?scenario a wm:ScenarioRebalancing ;
                  wm:scenarioRebalancingOfInvestor ?investor ;
                  wm:currentAllocationPct ?currentAllocation ;
                  wm:newAllocationPct ?newAllocation .
      }
    }
    GROUP BY ?investor ?riskToleranceLabel
  }
}
GROUP BY ?riskToleranceLabel
ORDER BY ?riskToleranceLabel

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?categoryLabel
       (ROUND(AVG(?totalInvestment), 2) AS ?avgTotalSectorInvestment)
       (ROUND(AVG(?avgHoldingReturn), 2) AS ?avgHoldingReturn)
       (ROUND(AVG(?riskScore), 2) AS ?avgRiskScore)
WHERE {
  {
    SELECT ?investor ?categoryLabel
           (SUM(xsd:decimal(?sectorAllocTotal)) AS ?totalInvestment)
    WHERE {
      ?investor a wm:Investor ;
                wm:hasCategory/wm:label ?categoryLabel .
      ?sectorAlloc a wm:SectorAllocation ;
                   wm:allocationOfInvestor ?investor ;
                   wm:totalInvestment ?sectorAllocTotal .
    }
    GROUP BY ?investor ?categoryLabel
  }
  {
    SELECT ?investor
           (AVG(xsd:decimal(?returnsPct)) AS ?avgHoldingReturn)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:returnsPct ?returnsPct ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue .
      FILTER(xsd:decimal(?cost) > 0 && xsd:decimal(?currentValue) >= 0)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor
           (xsd:decimal(?score) AS ?riskScore)
    WHERE {
      ?health a wm:PortfolioHealth ;
              wm:healthOfInvestor ?investor ;
              wm:riskScore ?score .
    }
  }
}
GROUP BY ?categoryLabel
ORDER BY ?categoryLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?riskTolerance
       (ROUND(AVG(?totalValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?avgReturn), 2) AS ?avgHoldingReturn)
       (ROUND(AVG(?totalGain), 2) AS ?avgHoldingGain)
       (ROUND(AVG(?totalDividends), 2) AS ?avgDividends)
       (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  {
    SELECT ?investor (SUM(?cost) AS ?totalCost) (SUM(?currentValue) AS ?totalValue)
                     (AVG(?returnsPct) AS ?avgReturn) (SUM(?dividends) AS ?totalDividends)
                     (SUM(?gain) AS ?totalGain)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue ;
               wm:returnsPct ?returnsPct ;
               wm:dividends ?dividends .
      FILTER(?cost > 0 && ?currentValue >= 0)
      BIND((?currentValue - ?cost) AS ?gain)
    }
    GROUP BY ?investor
  }
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskToleranceNode .
  ?riskToleranceNode rdfs:label ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?category (ROUND(AVG(?netCashFlow), 2) AS ?avg_net_cash_flow_per_investor)
       (ROUND(AVG(?avgGoalProgress), 2) AS ?avg_goal_progress_per_investor)
       (ROUND(AVG(?riskScore), 2) AS ?avg_risk_score_per_investor)
       (COUNT(DISTINCT ?investorId) AS ?n_investors)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cashFlowAmount .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avgGoalProgress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPct .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (xsd:decimal(?riskScoreVal) AS ?riskScore)
    WHERE {
      ?health a wm:PortfolioHealth ;
              wm:healthOfInvestor ?investor ;
              wm:riskScore ?riskScoreVal .
      ?investor wm:investorId ?investorId .
    }
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasCategory/wm:label ?category .
}
GROUP BY ?category
ORDER BY ?category

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?progressPct), 2) AS ?avgGoalProgress)
       (ROUND(AVG(?shortfall), 2) AS ?avgGoalShortfall)
       (ROUND(AVG(?avgAnnualReturnPct), 2) AS ?avgAnnualReturn)
       (ROUND(AVG(?avgVolatilityPct), 2) AS ?avgGoalVolatility)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance/wm:rdfs:label ?riskTolerance .

  OPTIONAL {
    ?goal a wm:InvestmentGoal ;
          wm:belongsToInvestor ?investor ;
          wm:progressPct ?progressPct ;
          wm:shortfall ?shortfall ;
          wm:avgAnnualReturnPct ?avgAnnualReturnPct ;
          wm:avgVolatilityPct ?avgVolatilityPct .
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(xsd:decimal(?riskScore)), 2) AS ?avgRiskScore)
       (ROUND(AVG(xsd:decimal(?liquidityScore)), 2) AS ?avgLiquidityScore)
       (ROUND(AVG(xsd:decimal(?diversificationScore)), 2) AS ?avgDiversificationScore)
       (ROUND(AVG(xsd:decimal(?goalMatchPct)), 2) AS ?avgGoalMatchPct)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance/wm:rdfs:label ?riskTolerance ;
            wm:investorId ?investorId .

  ?health a wm:PortfolioHealth ;
          wm:healthOfInvestor ?investor ;
          wm:riskScore ?riskScore ;
          wm:liquidityScore ?liquidityScore ;
          wm:diversificationScore ?diversificationScore ;
          wm:goalMatchPct ?goalMatchPct .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?timeHorizonLabel
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?signedAmount), 2) AS ?avgSignedCashFlowAmount)
       (ROUND(AVG(?cashFlowCount), 2) AS ?avgCashFlowCount)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasTimeHorizon ?timeHorizon ;
            wm:investorId ?investorId .
  ?timeHorizon rdfs:label ?timeHorizonLabel .

  {
    SELECT ?investorId
           (SUM(?adjustedAmount) AS ?netCashFlow)
           (SUM(ABS(?adjustedAmount)) AS ?signedAmount)
           (COUNT(?cashFlow) AS ?cashFlowCount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amountStr ;
                wm:type ?type .
      BIND(xsd:decimal(?amountStr) AS ?amount)
      BIND(IF(?type = "SIP" || ?type = "Lump Sum" || ?type = "Deposit", -?amount, ?amount) AS ?adjustedAmount)
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?timeHorizonLabel
ORDER BY ?timeHorizonLabel

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?timeHorizonLabel
       (ROUND(AVG(?totalValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?avgReturn), 2) AS ?avgHoldingReturn)
       (ROUND(AVG(?totalGain), 2) AS ?avgHoldingGain)
       (ROUND(AVG(?totalDividends), 2) AS ?avgDividends)
       (COUNT(DISTINCT ?investorId) AS ?investorCount)
WHERE {
  {
    SELECT ?investorId ?timeHorizonLabel
           (SUM(?_currentValue) AS ?totalValue)
           (AVG(?_returnsPct) AS ?avgReturn)
           (SUM(?_gain) AS ?totalGain)
           (SUM(?_dividends) AS ?totalDividends)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasTimeHorizon/wm:label ?timeHorizonLabel .

      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:cost ?_cost ;
               wm:currentValue ?_currentValue ;
               wm:returnsPct ?_returnsPct ;
               wm:dividends ?_dividends .

      FILTER(?_cost > 0 && ?_currentValue >= 0)

      BIND((?_currentValue - ?_cost) AS ?_gain)
    }
    GROUP BY ?investorId ?timeHorizonLabel
  }
}
GROUP BY ?timeHorizonLabel
ORDER BY ?timeHorizonLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?timeHorizonLabel 
       (ROUND(AVG(?allocationShift), 2) AS ?avgScenarioShift)
       (COUNT(DISTINCT ?investor) AS ?investorCount)
       (ROUND(AVG(?scenarioCount), 2) AS ?avgScenarioCount)
WHERE {
  ?investor a wm:Investor ;
            wm:hasTimeHorizon ?timeHorizon .
  ?timeHorizon rdfs:label ?timeHorizonLabel .

  OPTIONAL {
    ?scenario a wm:ScenarioRebalancing ;
              wm:scenarioRebalancingOfInvestor ?investor ;
              wm:currentAllocationPct ?currentAlloc ;
              wm:newAllocationPct ?newAlloc .
    BIND((?newAlloc - ?currentAlloc) AS ?allocationShift)
  }

  {
    SELECT ?investor (COUNT(?scenario) AS ?scenarioCount)
    WHERE {
      OPTIONAL {
        ?scenario a wm:ScenarioRebalancing ;
                  wm:scenarioRebalancingOfInvestor ?investor .
      }
    }
    GROUP BY ?investor
  }
}
GROUP BY ?timeHorizonLabel
ORDER BY ?timeHorizonLabel

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?rebalanceAmount), 2) AS ?avgRebalanceAmount)
       (ROUND(AVG(?rebalanceShift), 2) AS ?avgRebalanceShift)
       (ROUND(AVG(?rebalanceCount), 2) AS ?avgRebalanceCount)
WHERE {
  {
    SELECT ?investor ?riskTolerance
           (SUM(COALESCE(xsd:decimal(?amount), 0)) AS ?rebalanceAmount)
           (SUM(COALESCE(xsd:decimal(?targetAllocationPct), 0) - COALESCE(xsd:decimal(?currentAllocationPct), 0)) AS ?rebalanceShift)
           (COUNT(?rebalanceId) AS ?rebalanceCount)
    WHERE {
      ?investor a wm:Investor ;
                wm:hasRiskTolerance/wm:label ?riskTolerance .
      OPTIONAL {
        ?rebalancing a wm:RebalancingAction ;
                     wm:rebalancingActionOfInvestor ?investor ;
                     wm:amount ?amount ;
                     wm:targetAllocationPct ?targetAllocationPct ;
                     wm:currentAllocationPct ?currentAllocationPct ;
                     wm:rebalanceId ?rebalanceId .
      }
    }
    GROUP BY ?investor ?riskTolerance
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?investorName ?totalHoldingValue
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?currentValue)) AS ?totalHoldingValue)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?currentValue .
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .
}
ORDER BY DESC(?totalHoldingValue)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?timeHorizonLabel
       (ROUND(AVG(?progressPct), 2) AS ?avgGoalProgress)
       (ROUND(AVG(?shortfall), 2) AS ?avgGoalShortfall)
       (ROUND(AVG(?avgAnnualReturnPct), 2) AS ?avgAnnualReturn)
       (ROUND(AVG(?stdDevAnnualReturnPct), 2) AS ?avgGoalVolatility)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasTimeHorizon ?timeHorizon ;
            wm:investorId ?investorId .
  ?timeHorizon rdfs:label ?timeHorizonLabel .

  OPTIONAL {
    ?goal a wm:InvestmentGoal ;
          wm:belongsToInvestor ?investor ;
          wm:progressPct ?progressPct ;
          wm:shortfall ?shortfall ;
          wm:avgAnnualReturnPct ?avgAnnualReturnPct ;
          wm:stdDevAnnualReturnPct ?stdDevAnnualReturnPct .
  }
}
GROUP BY ?timeHorizonLabel
ORDER BY ?timeHorizonLabel

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?timeHorizonLabel (ROUND(AVG(?totalInvestment), 2) AS ?avgTotalInvestment) (ROUND(AVG(?allocationPct), 2) AS ?avgAllocationPct)
WHERE {
  ?investor a wm:Investor ;
            wm:hasTimeHorizon ?timeHorizon .
  ?timeHorizon rdfs:label ?timeHorizonLabel .

  ?sectorAllocation a wm:SectorAllocation ;
                    wm:allocationOfInvestor ?investor ;
                    wm:totalInvestment ?totalInvestment ;
                    wm:allocationPct ?allocationPct .
}
GROUP BY ?timeHorizonLabel
ORDER BY ?timeHorizonLabel

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?investorName (SUM(xsd:decimal(?totalInvestment)) AS ?totalSectorInvestment)
WHERE {
  ?sectorAlloc a wm:SectorAllocation ;
               wm:allocationOfInvestor ?investor ;
               wm:totalInvestment ?totalInvestment .
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .
}
GROUP BY ?investorId ?investorName
ORDER BY DESC(?totalSectorInvestment)
LIMIT 10

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?timeHorizonLabel
       (ROUND(AVG(?riskScore), 2) AS ?avgRiskScore)
       (ROUND(AVG(?liquidityScore), 2) AS ?avgLiquidityScore)
       (ROUND(AVG(?diversificationScore), 2) AS ?avgDiversificationScore)
       (ROUND(AVG(?goalMatchPct), 2) AS ?avgGoalMatchPct)
       (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  ?investor a wm:Investor ;
            wm:hasTimeHorizon ?timeHorizon .
  ?timeHorizon rdfs:label ?timeHorizonLabel .

  ?health a wm:PortfolioHealth ;
          wm:healthOfInvestor ?investor ;
          wm:riskScore ?riskScore ;
          wm:liquidityScore ?liquidityScore ;
          wm:diversificationScore ?diversificationScore ;
          wm:goalMatchPct ?goalMatchPct .
}
GROUP BY ?timeHorizonLabel
ORDER BY ?timeHorizonLabel

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?riskScore
WHERE {
  ?investor wm:investorId ?investorId ;
            wm:hasPortfolioHealth ?health .
  ?health wm:riskScore ?riskScore .
}
ORDER BY DESC(?riskScore) ASC(?investorId)
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?totalNetCashFlow)
WHERE {
  ?cashFlow a wm:CashFlow ;
            wm:investorId ?investorId ;
            wm:amount ?amount .
}
GROUP BY ?investorId
ORDER BY DESC(?totalNetCashFlow)
LIMIT 10

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?timeHorizonLabel
       (ROUND(AVG(?rebalanceAmount), 2) AS ?avgRebalanceAmount)
       (ROUND(AVG(?rebalanceShift), 2) AS ?avgRebalanceShift)
       (ROUND(AVG(?rebalanceCount), 2) AS ?avgRebalanceCount)
WHERE {
  {
    SELECT ?investor ?timeHorizonLabel
           (COALESCE(SUM(xsd:decimal(?actionAmount)), 0) AS ?rebalanceAmount)
           (COALESCE(SUM(xsd:decimal(?targetAlloc) - xsd:decimal(?currentAlloc)), 0) AS ?rebalanceShift)
           (COUNT(?rebalanceAction) AS ?rebalanceCount)
    WHERE {
      ?investor a wm:Investor ;
                 wm:hasTimeHorizon ?timeHorizon .
      ?timeHorizon rdfs:label ?timeHorizonLabel .

      OPTIONAL {
        ?rebalanceAction a wm:RebalancingAction ;
                         wm:rebalancingActionOfInvestor ?investor ;
                         wm:amount ?actionAmount ;
                         wm:targetAllocationPct ?targetAlloc ;
                         wm:currentAllocationPct ?currentAlloc .
      }
    }
    GROUP BY ?investor ?timeHorizonLabel
  }
}
GROUP BY ?timeHorizonLabel
ORDER BY ?timeHorizonLabel

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?avgProgressPct
WHERE {
  {
    SELECT ?investorId (ROUND(AVG(xsd:decimal(?progressPct)), 2) AS ?avgProgressPct)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPct .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
}
ORDER BY DESC(?avgProgressPct)
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?totalRebalanceAmount)
WHERE {
  ?rebalancingAction a wm:RebalancingAction ;
                     wm:investorId ?investorId ;
                     wm:amount ?amount .
}
GROUP BY ?investorId
ORDER BY DESC(?totalRebalanceAmount)
LIMIT 20

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?segment
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?signedAmount), 2) AS ?avgSignedCashFlowAmount)
       (ROUND(AVG(?cashFlowCount), 2) AS ?avgCashFlowCount)
WHERE {
  {
    SELECT ?investor ?segment
           (SUM(?adjustedAmount) AS ?netCashFlow)
           (SUM(ABS(?adjustedAmount)) AS ?signedAmount)
           (COUNT(?cashFlow) AS ?cashFlowCount)
    WHERE {
      ?investor a wm:Investor ;
                wm:segment ?segment .
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amountStr ;
                wm:type ?type .
      BIND(xsd:decimal(?amountStr) AS ?amount)
      BIND(IF(?type IN ("SIP", "Lump Sum", "Deposit"), -?amount, ?amount) AS ?adjustedAmount)
    }
    GROUP BY ?investor ?segment
  }
}
GROUP BY ?segment
ORDER BY ?segment

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?investorName (SUM(xsd:decimal(?currentValue)) AS ?totalHoldingValue)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .
  ?holding a wm:PortfolioHolding ;
           wm:heldByInvestor ?investor ;
           wm:currentValue ?currentValue .
}
GROUP BY ?investorId ?investorName
ORDER BY DESC(?totalHoldingValue)
LIMIT 20

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?totalRebalanceAmount)
WHERE {
  ?ra a wm:RebalancingAction ;
      wm:investorId ?investorId ;
      wm:amount ?amount .
}
GROUP BY ?investorId
ORDER BY DESC(?totalRebalanceAmount)
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?totalNetCashFlow)
WHERE {
  ?cashFlow a wm:CashFlow ;
            wm:investorId ?investorId ;
            wm:amount ?amount .
}
GROUP BY ?investorId
ORDER BY DESC(?totalNetCashFlow)
LIMIT 20

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?signedCashFlowAmount), 2) AS ?avgSignedCashFlowAmount)
       (ROUND(AVG(?totalHoldingValue), 2) AS ?avgTotalHoldingValue)
       (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cashFlowAmountStr .
      BIND(xsd:decimal(?cashFlowAmountStr) AS ?cashFlowAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(ABS(xsd:decimal(?cashFlowAmount))) AS ?signedCashFlowAmount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cashFlowAmountStr .
      BIND(xsd:decimal(?cashFlowAmountStr) AS ?cashFlowAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?currentValue)) AS ?totalHoldingValue)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?currentValueStr .
      BIND(xsd:decimal(?currentValueStr) AS ?currentValue)
    }
    GROUP BY ?investor
  }
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskToleranceObj .
  ?riskToleranceObj rdfs:label ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?signedCashFlowAmount), 2) AS ?avgSignedCashFlowAmount)
       (ROUND(AVG(?scenarioShift), 2) AS ?avgScenarioShift)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  {
    SELECT ?investor (SUM(?cashFlowAmount) AS ?netCashFlow)
    WHERE {
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amountStr .
      BIND(xsd:decimal(?amountStr) AS ?cashFlowAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(?cashFlowAmount) AS ?signedCashFlowAmount)
    WHERE {
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amountStr .
      BIND(xsd:decimal(?amountStr) AS ?cashFlowAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(?shift) AS ?scenarioShift)
    WHERE {
      ?scenarioRebalancing wm:scenarioRebalancingOfInvestor ?investor ;
                           wm:currentAllocationPct ?currentStr ;
                           wm:newAllocationPct ?newStr .
      BIND(xsd:decimal(?currentStr) AS ?current)
      BIND(xsd:decimal(?newStr) AS ?new)
      BIND(?new - ?current AS ?shift)
    }
    GROUP BY ?investor
  }
  ?investor wm:hasRiskTolerance ?riskToleranceNode .
  ?riskToleranceNode rdfs:label ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?signedAmount), 2) AS ?avgSignedCashFlowAmount)
       (ROUND(AVG(?riskScore), 2) AS ?avgRiskScore)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cfAmountStr .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?cfAmount)) AS ?signedAmount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cfAmountStr .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investor
  }
  ?investor a wm:Investor ;
            wm:hasRiskTolerance/wm:riskTolerance ?riskTolerance ;
            wm:hasPortfolioHealth/wm:riskScore ?riskScoreStr .
  BIND(xsd:decimal(?riskScoreStr) AS ?riskScore)
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?signedCashFlowAmount), 2) AS ?avgSignedCashFlowAmount)
       (ROUND(AVG(?totalSectorInvestment), 2) AS ?avgTotalSectorInvestment)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cashFlowAmountStr .
      BIND(xsd:decimal(?cashFlowAmountStr) AS ?cashFlowAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(ABS(xsd:decimal(?cashFlowAmount))) AS ?signedCashFlowAmount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cashFlowAmountStr .
      BIND(xsd:decimal(?cashFlowAmountStr) AS ?cashFlowAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?totalInvestment)) AS ?totalSectorInvestment)
    WHERE {
      ?sectorAlloc a wm:SectorAllocation ;
                   wm:allocationOfInvestor ?investor ;
                   wm:totalInvestment ?totalInvestmentStr .
      BIND(xsd:decimal(?totalInvestmentStr) AS ?totalInvestment)
    }
    GROUP BY ?investor
  }
  ?investor a wm:Investor ;
            wm:hasRiskTolerance/wm:riskTolerance ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?totalValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?holdingReturn), 2) AS ?avgHoldingReturn)
       (ROUND(AVG(?scenarioShift), 2) AS ?avgScenarioShift)
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?phCurrentValue)) AS ?totalValue)
    WHERE {
      ?investor a wm:Investor ;
                 wm:investorId ?invId .
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?phCurrentValue .
      FILTER(xsd:decimal(?phCurrentValue) >= 0)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?phReturnsPct)) AS ?holdingReturn)
    WHERE {
      ?investor a wm:Investor ;
                 wm:investorId ?invId .
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:cost ?cost ;
               wm:currentValue ?curVal ;
               wm:returnsPct ?phReturnsPct .
      FILTER(xsd:decimal(?cost) > 0 && xsd:decimal(?curVal) >= 0)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?scenarioShift)
    WHERE {
      ?investor a wm:Investor ;
                 wm:investorId ?invId .
      ?scenario a wm:ScenarioRebalancing ;
                wm:scenarioRebalancingOfInvestor ?investor ;
                wm:currentAllocationPct ?currAlloc ;
                wm:newAllocationPct ?newAlloc .
    }
    GROUP BY ?investor
  }
  ?investor wm:hasRiskTolerance/wm:label ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?totalHoldingValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?holdingReturn), 2) AS ?avgHoldingReturn)
       (ROUND(AVG(?totalSectorInvestment), 2) AS ?avgTotalSectorInvestment)
WHERE {
  {
    SELECT ?investor ?riskTolerance
           (SUM(COALESCE(?currentValue, 0)) AS ?totalHoldingValue)
    WHERE {
      ?investor a wm:Investor ;
                wm:hasRiskTolerance/wm:riskTolerance ?riskTolerance .
      OPTIONAL {
        ?holding wm:heldByInvestor ?investor ;
                 wm:currentValue ?currentValue .
      }
    }
    GROUP BY ?investor ?riskTolerance
  }
  {
    SELECT ?investor
           (AVG(?returnsPct) AS ?holdingReturn)
    WHERE {
      ?holding wm:heldByInvestor ?investor ;
               wm:returnsPct ?returnsPct ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue .
      FILTER(?cost > 0)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor
           (SUM(COALESCE(?totalInvestment, 0)) AS ?totalSectorInvestment)
    WHERE {
      OPTIONAL {
        ?sectorAlloc wm:allocationOfInvestor ?investor ;
                     wm:totalInvestment ?totalInvestment .
      }
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskToleranceLabel
       (ROUND(AVG(?totalHoldingValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?holdingReturn), 2) AS ?avgHoldingReturn)
       (ROUND(AVG(?rebalanceAmount), 2) AS ?avgRebalanceAmount)
WHERE {
  {
    SELECT ?investor ?riskToleranceLabel
           (SUM(?_currentValue) AS ?totalHoldingValue)
    WHERE {
      ?investor a wm:Investor ;
                wm:hasRiskTolerance ?riskTolerance .
      ?riskTolerance rdfs:label ?riskToleranceLabel .
      ?investor wm:hasHolding ?holding .
      ?holding wm:currentValue ?_currentValue .
      FILTER(xsd:decimal(?_currentValue) >= 0)
    }
    GROUP BY ?investor ?riskToleranceLabel
  }
  OPTIONAL {
    {
      SELECT ?investor (AVG(?_returnsPct) AS ?holdingReturn)
      WHERE {
        ?investor wm:hasHolding ?holding .
        ?holding wm:returnsPct ?_returnsPct ;
                 wm:cost ?_cost ;
                 wm:currentValue ?_currentValue .
        FILTER(xsd:decimal(?_cost) > 0)
        FILTER(xsd:decimal(?_currentValue) >= 0)
      }
      GROUP BY ?investor
    }
  }
  OPTIONAL {
    {
      SELECT ?investor (SUM(xsd:decimal(?_amount)) AS ?rebalanceAmount)
      WHERE {
        ?investor wm:hasRebalancingAction ?rebalancing .
        ?rebalancing wm:amount ?_amount .
      }
      GROUP BY ?investor
    }
  }
}
GROUP BY ?riskToleranceLabel
ORDER BY ?riskToleranceLabel

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?totalValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?holdingReturn), 2) AS ?avgHoldingReturn)
       (ROUND(AVG(?riskScore), 2) AS ?avgRiskScore)
       (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?currentValue)) AS ?totalValue)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?currentValue .
      FILTER(xsd:decimal(?currentValue) >= 0)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?returnsPct)) AS ?holdingReturn)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:returnsPct ?returnsPct ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue .
      FILTER(xsd:decimal(?cost) > 0 && xsd:decimal(?currentValue) >= 0)
    }
    GROUP BY ?investor
  }
  ?investor a wm:Investor ;
            wm:hasRiskTolerance/wm:rdfs:label ?riskTolerance ;
            wm:hasPortfolioHealth/wm:riskScore ?riskScore .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(xsd:decimal(?amount)), 2) AS ?avgRebalanceAmount)
       (ROUND(AVG(xsd:decimal(?targetAllocationPct) - xsd:decimal(?currentAllocationPct)), 2) AS ?avgRebalanceShift)
       (ROUND(AVG(xsd:decimal(?totalInvestment)), 2) AS ?avgTotalSectorInvestment)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskToleranceObj ;
            wm:hasRebalancingAction ?rebalancingAction ;
            wm:hasSectorAllocation ?sectorAllocation .

  ?riskToleranceObj rdfs:label ?riskTolerance .

  ?rebalancingAction wm:amount ?amount ;
                     wm:targetAllocationPct ?targetAllocationPct ;
                     wm:currentAllocationPct ?currentAllocationPct .

  ?sectorAllocation wm:totalInvestment ?totalInvestment .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(xsd:decimal(?rebalanceAmount)), 2) AS ?avgRebalanceAmount)
       (ROUND(AVG(xsd:decimal(?targetAllocationPct) - xsd:decimal(?currentAllocationPct)), 2) AS ?avgRebalanceShift)
       (ROUND(AVG(xsd:decimal(?riskScore)), 2) AS ?avgRiskScore)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance/wm:riskTolerance ?riskTolerance ;
            wm:investorId ?investorId .

  ?rebalancing a wm:RebalancingAction ;
               wm:rebalancingActionOfInvestor ?investor ;
               wm:amount ?rebalanceAmount ;
               wm:targetAllocationPct ?targetAllocationPct ;
               wm:currentAllocationPct ?currentAllocationPct .

  ?health a wm:PortfolioHealth ;
          wm:healthOfInvestor ?investor ;
          wm:riskScore ?riskScore .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?signedCashFlowAmount), 2) AS ?avgSignedCashFlowAmount)
       (ROUND(AVG(?rebalanceAmount), 2) AS ?avgRebalanceAmount)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskToleranceIRI .
  ?riskToleranceIRI rdfs:label ?riskTolerance .

  OPTIONAL {
    {
      SELECT ?investor (SUM(?signedAmount) AS ?netCashFlow)
      WHERE {
        ?cashFlow a wm:CashFlow ;
                  wm:cashFlowOfInvestor ?investor ;
                  wm:amount ?amountStr .
        BIND(xsd:decimal(?amountStr) AS ?amount)
        BIND(
          IF(?cashFlowType = wm:Deposit || ?cashFlowType = wm:SIP || ?cashFlowType = wm:LumpSum,
             -?amount,
             ?amount
          ) AS ?signedAmount
        )
        ?cashFlow wm:hasCashFlowType ?cashFlowTypeIRI .
        ?cashFlowTypeIRI rdfs:label ?cashFlowType .
      }
      GROUP BY ?investor
    }
  }

  OPTIONAL {
    {
      SELECT ?investor (AVG(?signedAmount) AS ?signedCashFlowAmount)
      WHERE {
        ?cashFlow a wm:CashFlow ;
                  wm:cashFlowOfInvestor ?investor ;
                  wm:amount ?amountStr .
        BIND(xsd:decimal(?amountStr) AS ?amount)
        BIND(
          IF(?cashFlowType = wm:Deposit || ?cashFlowType = wm:SIP || ?cashFlowType = wm:LumpSum,
             -?amount,
             ?amount
          ) AS ?signedAmount
        )
        ?cashFlow wm:hasCashFlowType ?cashFlowTypeIRI .
        ?cashFlowTypeIRI rdfs:label ?cashFlowType .
      }
      GROUP BY ?investor
    }
  }

  OPTIONAL {
    {
      SELECT ?investor (AVG(?rebalanceAmountValue) AS ?rebalanceAmount)
      WHERE {
        ?rebalancing a wm:RebalancingAction ;
                     wm:rebalancingActionOfInvestor ?investor ;
                     wm:amount ?amountStr .
        BIND(ABS(xsd:decimal(?amountStr)) AS ?rebalanceAmountValue)
      }
      GROUP BY ?investor
    }
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?totalHoldingValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?holdingReturn), 2) AS ?avgHoldingReturn)
       (ROUND(AVG(?goalProgress), 2) AS ?avgGoalProgress)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?currentValue)) AS ?totalHoldingValue)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?currentValue .
      FILTER(xsd:decimal(?currentValue) >= 0)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?returnsPct)) AS ?holdingReturn)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue ;
               wm:returnsPct ?returnsPct .
      FILTER(xsd:decimal(?cost) > 0)
      FILTER(xsd:decimal(?currentValue) >= 0)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?goalProgress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?investor
  }
  ?investor a wm:Investor ;
            wm:hasRiskTolerance/wm:riskTolerance ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?totalInvestment), 2) AS ?avgTotalSectorInvestment)
       (ROUND(AVG(?allocationPct), 2) AS ?avgAllocationPercentage)
       (ROUND(AVG(?progressPct), 2) AS ?avgGoalProgress)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  {
    SELECT ?investor ?riskTolerance
           (SUM(xsd:decimal(?sectorTotal)) AS ?totalInvestment)
    WHERE {
      ?investor a wm:Investor ;
                wm:hasRiskTolerance/wm:riskTolerance ?riskTolerance .
      ?allocation a wm:SectorAllocation ;
                  wm:allocationOfInvestor ?investor ;
                  wm:totalInvestment ?sectorTotal .
    }
    GROUP BY ?investor ?riskTolerance
  }
  OPTIONAL {
    ?allocation a wm:SectorAllocation ;
                wm:allocationOfInvestor ?investor ;
                wm:allocationPct ?allocationPct .
  }
  OPTIONAL {
    ?goal a wm:InvestmentGoal ;
          wm:belongsToInvestor ?investor ;
          wm:progressPct ?progressPct .
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?rebalanceAmount), 2) AS ?avgRebalanceAmount)
       (ROUND(AVG(?rebalanceShift), 2) AS ?avgRebalanceShift)
       (ROUND(AVG(?scenarioShift), 2) AS ?avgScenarioShift)
WHERE {
  {
    SELECT ?investor ?riskTolerance
           (SUM(xsd:decimal(?raAmount)) AS ?rebalanceAmount)
           (AVG(xsd:decimal(?raTarget) - xsd:decimal(?raCurrent)) AS ?rebalanceShift)
    WHERE {
      ?investor a wm:Investor ;
                 wm:hasRiskTolerance/wm:riskTolerance ?riskTolerance .
      OPTIONAL {
        ?ra a wm:RebalancingAction ;
            wm:rebalancingActionOfInvestor ?investor ;
            wm:amount ?raAmount ;
            wm:targetAllocationPct ?raTarget ;
            wm:currentAllocationPct ?raCurrent .
      }
    }
    GROUP BY ?investor ?riskTolerance
  }
  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?srNew) - xsd:decimal(?srCurrent)) AS ?scenarioShift)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:scenarioRebalancingOfInvestor ?investor ;
          wm:newAllocationPct ?srNew ;
          wm:currentAllocationPct ?srCurrent .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?signedCashFlowAmount), 2) AS ?avgSignedCashFlowAmount)
       (ROUND(AVG(?goalProgress), 2) AS ?avgGoalProgress)
       (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  {
    SELECT ?investor ?riskTolerance (SUM(?adjustedAmount) AS ?netCashFlow)
    WHERE {
      ?investor a wm:Investor ;
                wm:hasRiskTolerance/wm:riskTolerance ?riskTolerance .
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amountStr .
      BIND(xsd:decimal(?amountStr) AS ?amount)
      BIND(IF(?cashFlow/wm:hasCashFlowType/wm:type = 'SIP' ||
              ?cashFlow/wm:hasCashFlowType/wm:type = 'Lump Sum' ||
              ?cashFlow/wm:hasCashFlowType/wm:type = 'Deposit',
              -?amount, ?amount) AS ?adjustedAmount)
    }
    GROUP BY ?investor ?riskTolerance
  }
  {
    SELECT ?investor (AVG(?progressPct) AS ?goalProgress)
    WHERE {
      ?goal wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPctStr .
      BIND(xsd:decimal(?progressPctStr) AS ?progressPct)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(?signedAmount) AS ?signedCashFlowAmount)
    WHERE {
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amountStr .
      BIND(xsd:decimal(?amountStr) AS ?amount)
      BIND(IF(?cashFlow/wm:hasCashFlowType/wm:type = 'SIP' ||
              ?cashFlow/wm:hasCashFlowType/wm:type = 'Lump Sum' ||
              ?cashFlow/wm:hasCashFlowType/wm:type = 'Deposit',
              -?amount, ?amount) AS ?signedAmount)
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?rebalanceAmount), 2) AS ?avgRebalanceAmount)
       (ROUND(AVG(?rebalanceShift), 2) AS ?avgRebalanceShift)
       (ROUND(AVG(?goalProgress), 2) AS ?avgGoalProgress)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  {
    SELECT ?investor ?riskTolerance
           (AVG(?amount) AS ?rebalanceAmount)
           (AVG(?targetMinusCurrent) AS ?rebalanceShift)
    WHERE {
      ?investor a wm:Investor ;
                wm:hasRiskTolerance/wm:riskTolerance ?riskTolerance .
      ?rebalancing a wm:RebalancingAction ;
                   wm:rebalancingActionOfInvestor ?investor ;
                   wm:amount ?amount ;
                   wm:targetAllocationPct ?target ;
                   wm:currentAllocationPct ?current .
      BIND((?target - ?current) AS ?targetMinusCurrent)
    }
    GROUP BY ?investor ?riskTolerance
  }
  OPTIONAL {
    {
      SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?goalProgress)
      WHERE {
        ?goal a wm:InvestmentGoal ;
              wm:belongsToInvestor ?investor ;
              wm:progressPct ?progressPct .
      }
      GROUP BY ?investor
    }
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?allocationShift), 2) AS ?avgScenarioShift)
       (ROUND(AVG(?scenarioCount), 2) AS ?avgScenarioCount)
       (ROUND(AVG(?goalProgress), 2) AS ?avgGoalProgress)
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?newAllocationPct) - xsd:decimal(?currentAllocationPct)) AS ?allocationShift)
                      (COUNT(?scenarioRebalanceId) AS ?scenarioCount)
    WHERE {
      ?investor a wm:Investor ;
                 wm:investorId ?investorId .
      OPTIONAL {
        ?scenario a wm:ScenarioRebalancing ;
                  wm:scenarioRebalancingOfInvestor ?investor ;
                  wm:currentAllocationPct ?currentAllocationPct ;
                  wm:newAllocationPct ?newAllocationPct ;
                  wm:scenarioRebalanceId ?scenarioRebalanceId .
      }
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?goalProgress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?investor
  }
  ?investor wm:hasRiskTolerance ?riskToleranceObj .
  ?riskToleranceObj rdfs:label ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?totalInvestment), 2) AS ?avgTotalSectorInvestment)
       (ROUND(AVG(?allocationPct), 2) AS ?avgAllocationPercentage)
       (ROUND(AVG(?scenarioShift), 2) AS ?avgScenarioShift)
WHERE {
  {
    SELECT ?investor ?riskTolerance
           (SUM(xsd:decimal(?sectorAllocTotal)) AS ?totalInvestment)
    WHERE {
      ?investor a wm:Investor ;
                wm:hasRiskTolerance/wm:riskTolerance ?riskTolerance .
      ?sectorAlloc a wm:SectorAllocation ;
                   wm:allocationOfInvestor ?investor ;
                   wm:totalInvestment ?sectorAllocTotal .
    }
    GROUP BY ?investor ?riskTolerance
  }
  OPTIONAL {
    ?sectorAlloc a wm:SectorAllocation ;
                 wm:allocationOfInvestor ?investor ;
                 wm:allocationPct ?allocationPct .
  }
  OPTIONAL {
    ?scenarioRebal a wm:ScenarioRebalancing ;
                   wm:scenarioRebalancingOfInvestor ?investor ;
                   wm:currentAllocationPct ?currentAlloc ;
                   wm:newAllocationPct ?newAlloc .
    BIND(xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc) AS ?scenarioShift)
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?riskTolerance
       (ROUND(AVG(?totalInvestment), 2) AS ?avgTotalSectorInvestment)
       (ROUND(AVG(?allocationPct), 2) AS ?avgAllocationPercentage)
       (ROUND(AVG(?riskScore), 2) AS ?avgRiskScore)
       (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskToleranceNode .
  ?riskToleranceNode rdfs:label ?riskTolerance .

  {
    SELECT ?investor (SUM(xsd:decimal(?sectorTotalInvestment)) AS ?totalInvestment)
    WHERE {
      ?sectorAlloc a wm:SectorAllocation ;
                   wm:allocationOfInvestor ?investor ;
                   wm:totalInvestment ?sectorTotalInvestment .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (AVG(xsd:decimal(?sectorAllocPct)) AS ?allocationPct)
    WHERE {
      ?sectorAlloc a wm:SectorAllocation ;
                   wm:allocationOfInvestor ?investor ;
                   wm:allocationPct ?sectorAllocPct .
    }
    GROUP BY ?investor
  }

  ?portfolioHealth a wm:PortfolioHealth ;
                    wm:healthOfInvestor ?investor ;
                    wm:riskScore ?riskScore .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           ((SUM(?cashFlowAmount) + SUM(?holdingGain)) AS ?compositeScore)
    WHERE {
      # Get investor
      ?investor a wm:Investor ;
                wm:investorId ?investorId .

      # Get net cash flow (sum of all cash flow amounts)
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cashFlowAmount .

      # Get total holding gain (currentValue - cost) for holdings with recorded cost and current value
      ?holding wm:heldByInvestor ?investor ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue .
      FILTER(?cost > 0 && ?currentValue >= 0)
      BIND((?currentValue - ?cost) AS ?holdingGain)
    }
    GROUP BY ?investorId
    HAVING (COUNT(?cashFlow) > 0 && COUNT(?holding) > 0)
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?timeHorizonLabel 
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow) 
       (ROUND(AVG(?signedCashFlowAmount), 2) AS ?avgSignedCashFlowAmount) 
       (ROUND(AVG(?totalHoldingValue), 2) AS ?avgTotalHoldingValue)
WHERE {
  {
    SELECT ?investor ?timeHorizonLabel 
           (SUM(?signedAmount) AS ?netCashFlow) 
           (SUM(?signedAmount) AS ?signedCashFlowAmount) 
           (SUM(?holdingValue) AS ?totalHoldingValue)
    WHERE {
      ?investor a wm:Investor ;
                wm:hasTimeHorizon ?timeHorizon .
      ?timeHorizon rdfs:label ?timeHorizonLabel .

      OPTIONAL {
        ?cashFlow wm:cashFlowOfInvestor ?investor ;
                  wm:amount ?amountStr ;
                  wm:type ?type .
        BIND(xsd:decimal(?amountStr) AS ?amount)
        BIND(IF(?type = "SIP" || ?type = "Lump Sum" || ?type = "Deposit", -?amount, ?amount) AS ?signedAmount)
      }

      OPTIONAL {
        ?holding wm:heldByInvestor ?investor ;
                 wm:currentValue ?valueStr .
        BIND(xsd:decimal(?valueStr) AS ?holdingValue)
      }
    }
    GROUP BY ?investor ?timeHorizonLabel
  }
}
GROUP BY ?timeHorizonLabel
ORDER BY ?timeHorizonLabel

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?investorName ?compositeScore
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cfAmountStr .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?shortfall)) AS ?avgGoalShortfall)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:shortfall ?shortfallStr .
      BIND(xsd:decimal(?shortfallStr) AS ?shortfall)
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .
  BIND((?netCashFlow - ?avgGoalShortfall) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      FILTER EXISTS { ?investor wm:hasCashFlow ?cf . }
      FILTER EXISTS { ?investor wm:hasRebalancingAction ?ra . }
      FILTER EXISTS { ?investor wm:hasPortfolioHealth ?ph . }
      FILTER EXISTS { ?investor wm:hasSectorAllocation ?sa . }
      FILTER EXISTS { ?investor wm:hasInvestmentGoal ?ig . }
      FILTER EXISTS { ?investor wm:hasHolding ?h . }
    }
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasCashFlow ?cfNode .
      ?cfNode wm:amount ?cfAmountStr .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(ABS(xsd:decimal(?raAmount))) AS ?totalRebalanceAmount)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasRebalancingAction ?raNode .
      ?raNode wm:amount ?raAmountStr .
      BIND(xsd:decimal(?raAmountStr) AS ?raAmount)
    }
    GROUP BY ?investorId
  }
  BIND((?netCashFlow + ?totalRebalanceAmount) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId (SUM(?holdingGain) AS ?totalHoldingGain)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue .
      FILTER(?cost > 0)
      BIND((?currentValue - ?cost) AS ?holdingGain)
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(?rebalanceAmount) AS ?totalRebalanceAmount)
    WHERE {
      ?rebalancing a wm:RebalancingAction ;
                   wm:investorId ?investorId ;
                   wm:amount ?rebalanceAmount .
    }
    GROUP BY ?investorId
  }
  BIND((?totalHoldingGain + ?totalRebalanceAmount) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      FILTER EXISTS { ?investor wm:hasCashFlow ?cashFlow . }
      FILTER EXISTS { ?investor wm:hasSectorAllocation ?sectorAllocation . }
      FILTER EXISTS { ?investor wm:hasPortfolioHealth ?portfolioHealth . }
      FILTER EXISTS { ?investor wm:hasRebalancingAction ?rebalancingAction . }
      FILTER EXISTS { ?investor wm:hasScenarioRebalancing ?scenarioRebalancing . }
    }
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:investorId ?investorId ;
                wm:amount ?cashFlowAmount .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?sectorTotalInvestment)) AS ?totalSectorInvestment)
    WHERE {
      ?sectorAlloc a wm:SectorAllocation ;
                   wm:allocationOfInvestor ?investor ;
                   wm:investorId ?investorId ;
                   wm:totalInvestment ?sectorTotalInvestment .
    }
    GROUP BY ?investorId
  }

  BIND((?netCashFlow + ?totalSectorInvestment) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * ((?normNetCashFlow + ?normTotalShift) / 2) AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
        WHERE {
          ?cf a wm:CashFlow .
          ?cf wm:investorId ?investorId .
          ?cf wm:amount ?cfAmount .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?totalShift)
        WHERE {
          ?sr a wm:ScenarioRebalancing .
          ?sr wm:investorId ?investorId .
          ?sr wm:newAllocationPct ?newAlloc .
          ?sr wm:currentAllocationPct ?currAlloc .
        }
        GROUP BY ?investorId
      }
      LET (?minNetCashFlow := MIN(?netCashFlow) OVER ())
      LET (?maxNetCashFlow := MAX(?netCashFlow) OVER ())
      LET (?minTotalShift := MIN(?totalShift) OVER ())
      LET (?maxTotalShift := MAX(?totalShift) OVER ())
      LET (?normNetCashFlow := ((?netCashFlow - ?minNetCashFlow) / (?maxNetCashFlow - ?minNetCashFlow)))
      LET (?normTotalShift := ((?totalShift - ?minTotalShift) / (?maxTotalShift - ?minTotalShift)))
    }
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(xsd:decimal(?riskScore)), 2) AS ?avg_risk_score)
       (ROUND(AVG(xsd:decimal(?liquidityScore)), 2) AS ?avg_liquidity_score)
       (ROUND(AVG(xsd:decimal(?progressPct)), 2) AS ?avg_goal_progress)
       (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance/wm:riskTolerance ?riskTolerance ;
            wm:hasPortfolioHealth ?health .
  ?health wm:riskScore ?riskScore ;
          wm:liquidityScore ?liquidityScore .

  OPTIONAL {
    ?goal wm:belongsToInvestor ?investor ;
          wm:progressPct ?progressPct .
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?allocationShift), 2) AS ?avgScenarioShift)
       (ROUND(AVG(?scenarioCount), 2) AS ?avgScenarioCount)
       (ROUND(AVG(?riskScore), 2) AS ?avgRiskScore)
WHERE {
  {
    SELECT ?investor ?riskTolerance
           (SUM(?newMinusCurrent) AS ?allocationShift)
           (COUNT(?scenario) AS ?scenarioCount)
    WHERE {
      ?investor wm:hasRiskTolerance/wm:riskTolerance ?riskTolerance .
      OPTIONAL {
        ?scenario wm:scenarioRebalancingOfInvestor ?investor ;
                  wm:currentAllocationPct ?currentAlloc ;
                  wm:newAllocationPct ?newAlloc .
        BIND((xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc)) AS ?newMinusCurrent)
      }
    }
    GROUP BY ?investor ?riskTolerance
  }
  OPTIONAL {
    ?health wm:healthOfInvestor ?investor ;
            wm:riskScore ?riskScore .
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
          (100 * ((?normNetCashFlow + ?normRiskScore) / 2) AS ?compositeScore)
    WHERE {
      # Net cash flow per investor
      {
        SELECT ?investorId (SUM(?cashAmount) AS ?netCashFlow)
        WHERE {
          ?cashFlow a wm:CashFlow ;
                    wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?amountStr .
          ?investor wm:investorId ?investorId .
          BIND(xsd:decimal(?amountStr) AS ?cashAmount)
        }
        GROUP BY ?investorId
      }
      # Risk score per investor
      {
        SELECT ?investorId (AVG(xsd:decimal(?riskScoreStr)) AS ?riskScore)
        WHERE {
          ?health a wm:PortfolioHealth ;
                  wm:healthOfInvestor ?investor ;
                  wm:riskScore ?riskScoreStr .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      # Min-max normalization
      {
        SELECT (MIN(?netCashFlow) AS ?minCash)
               (MAX(?netCashFlow) AS ?maxCash)
               (MIN(?riskScore) AS ?minRisk)
               (MAX(?riskScore) AS ?maxRisk)
        WHERE {
          {
            SELECT ?investorId (SUM(xsd:decimal(?amountStr)) AS ?netCashFlow)
            WHERE {
              ?cashFlow a wm:CashFlow ;
                        wm:cashFlowOfInvestor ?investor ;
                        wm:amount ?amountStr .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId (AVG(xsd:decimal(?riskScoreStr)) AS ?riskScore)
            WHERE {
              ?health a wm:PortfolioHealth ;
                      wm:healthOfInvestor ?investor ;
                      wm:riskScore ?riskScoreStr .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
        }
      }
      BIND((?netCashFlow - ?minCash) / (?maxCash - ?minCash) AS ?normNetCashFlow)
      BIND((?riskScore - ?minRisk) / (?maxRisk - ?minRisk) AS ?normRiskScore)
    }
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?rebalanceAmount)) AS ?totalRebalanceAmount)
    WHERE {
      ?rebalancing a wm:RebalancingAction ;
                   wm:rebalancingActionOfInvestor ?investor ;
                   wm:amount ?rebalanceAmount .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?sectorInvestment)) AS ?totalSectorInvestment)
    WHERE {
      ?sectorAlloc a wm:SectorAllocation ;
                   wm:allocationOfInvestor ?investor ;
                   wm:totalInvestment ?sectorInvestment .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  BIND ((?totalRebalanceAmount + ?totalSectorInvestment) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           ((SUM(?holdingGain)) - (AVG(?goalShortfall)) AS ?compositeScore)
    WHERE {
      # Investors with at least one holding that has both cost and current value
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasHolding ?holding .
      ?holding a wm:PortfolioHolding ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue .
      FILTER(?cost > 0 && ?currentValue >= 0)
      BIND((?currentValue - ?cost) AS ?holdingGain)

      # Investors with at least one goal that has a shortfall
      ?investor wm:hasInvestmentGoal ?goal .
      ?goal a wm:InvestmentGoal ;
            wm:shortfall ?goalShortfall .
    }
    GROUP BY ?investorId
    HAVING (COUNT(?holding) > 0 && COUNT(?goal) > 0)
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?signedCashFlowAmount), 2) AS ?avgSignedCashFlowAmount)
       (ROUND(AVG(?totalHoldingValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?rebalanceAmount), 2) AS ?avgRebalanceAmount)
WHERE {
  {
    SELECT ?investor ?riskTolerance (SUM(?cashFlowAmount) AS ?netCashFlow)
    WHERE {
      ?investor a wm:Investor ;
                 wm:hasRiskTolerance/wm:rdfs:label ?riskTolerance ;
                 wm:investorId ?investorId .
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cashFlowAmount .
    }
    GROUP BY ?investor ?riskTolerance
  }
  {
    SELECT ?investor (AVG(ABS(?cashFlowAmount)) AS ?signedCashFlowAmount)
    WHERE {
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cashFlowAmount .
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(?currentValue) AS ?totalHoldingValue)
    WHERE {
      ?holding wm:heldByInvestor ?investor ;
               wm:currentValue ?currentValue .
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(ABS(?rebalanceAmt)) AS ?rebalanceAmount)
    WHERE {
      ?rebalancing wm:rebalancingActionOfInvestor ?investor ;
                   wm:amount ?rebalanceAmt .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?signedCashFlow), 2) AS ?avgSignedCashFlowAmount)
       (ROUND(AVG(?totalHoldingValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?scenarioShift), 2) AS ?avgScenarioShift)
WHERE {
  {
    SELECT ?investor ?riskTolerance
           (SUM(?cashFlowAmount) AS ?netCashFlow)
           (AVG(?cashFlowAmount) AS ?signedCashFlow)
    WHERE {
      ?investor a wm:Investor ;
                wm:hasRiskTolerance ?riskToleranceIRI .
      ?riskToleranceIRI rdfs:label ?riskTolerance .

      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amountStr .
      BIND(xsd:decimal(?amountStr) AS ?cashFlowAmount)
    }
    GROUP BY ?investor ?riskTolerance
  }

  {
    SELECT ?investor
           (SUM(?currentValue) AS ?totalHoldingValue)
    WHERE {
      ?investor a wm:Investor .

      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?valueStr .
      BIND(xsd:decimal(?valueStr) AS ?currentValue)
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor
           (AVG(?shift) AS ?scenarioShift)
    WHERE {
      ?investor a wm:Investor .

      ?scenarioRebalancing a wm:ScenarioRebalancing ;
                           wm:scenarioRebalancingOfInvestor ?investor ;
                           wm:currentAllocationPct ?currentStr ;
                           wm:newAllocationPct ?newStr .
      BIND(xsd:decimal(?newStr) - xsd:decimal(?currentStr) AS ?shift)
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?cost)) AS ?totalCost) (SUM(xsd:decimal(?currentValue)) AS ?totalValue)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue .
      ?investor wm:investorId ?investorId .
      FILTER(xsd:decimal(?cost) > 0 && xsd:decimal(?currentValue) >= 0)
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (xsd:decimal(?riskScore) AS ?riskScoreRaw)
    WHERE {
      ?health a wm:PortfolioHealth ;
              wm:healthOfInvestor ?investor ;
              wm:riskScore ?riskScore .
      ?investor wm:investorId ?investorId .
    }
  }
  {
    SELECT (MAX(?totalGain) AS ?maxGain) (MIN(?totalGain) AS ?minGain) (MAX(?riskScoreRaw) AS ?maxRisk) (MIN(?riskScoreRaw) AS ?minRisk)
    WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?cost)) AS ?totalCost) (SUM(xsd:decimal(?currentValue)) AS ?totalValue)
        WHERE {
          ?holding a wm:PortfolioHolding ;
                   wm:heldByInvestor ?investor ;
                   wm:cost ?cost ;
                   wm:currentValue ?currentValue .
          ?investor wm:investorId ?investorId .
          FILTER(xsd:decimal(?cost) > 0 && xsd:decimal(?currentValue) >= 0)
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId (xsd:decimal(?riskScore) AS ?riskScoreRaw)
        WHERE {
          ?health a wm:PortfolioHealth ;
                  wm:healthOfInvestor ?investor ;
                  wm:riskScore ?riskScore .
          ?investor wm:investorId ?investorId .
        }
      }
      BIND((?totalValue - ?totalCost) AS ?totalGain)
    }
  }
  BIND((?totalValue - ?totalCost) AS ?totalGain)
  BIND((?totalGain - ?minGain) / (?maxGain - ?minGain) AS ?normGain)
  BIND((?riskScoreRaw - ?minRisk) / (?maxRisk - ?minRisk) AS ?normRisk)
  BIND(100 * ((?normGain + ?normRisk) / 2) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
          (SUM(xsd:decimal(?rebalanceAmount)) AS ?totalRebalanceAmount)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:rebalancingActionOfInvestor ?investor ;
          wm:amount ?rebalanceAmount .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
          (SUM(ABS(xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc))) AS ?totalAllocationShift)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:scenarioRebalancingOfInvestor ?investor ;
          wm:newAllocationPct ?newAlloc ;
          wm:currentAllocationPct ?currentAlloc .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT (MIN(?totalRebalanceAmount) AS ?minRebalance)
          (MAX(?totalRebalanceAmount) AS ?maxRebalance)
          (MIN(?totalAllocationShift) AS ?minShift)
          (MAX(?totalAllocationShift) AS ?maxShift)
    WHERE {
      {
        SELECT ?investorId
              (SUM(xsd:decimal(?rebalanceAmount)) AS ?totalRebalanceAmount)
        WHERE {
          ?ra a wm:RebalancingAction ;
              wm:rebalancingActionOfInvestor ?investor ;
              wm:amount ?rebalanceAmount .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
              (SUM(ABS(xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc))) AS ?totalAllocationShift)
        WHERE {
          ?sr a wm:ScenarioRebalancing ;
              wm:scenarioRebalancingOfInvestor ?investor ;
              wm:newAllocationPct ?newAlloc ;
              wm:currentAllocationPct ?currentAlloc .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
    }
  }
  BIND((?totalRebalanceAmount - ?minRebalance) / (?maxRebalance - ?minRebalance) AS ?normRebalance)
  BIND((?totalAllocationShift - ?minShift) / (?maxShift - ?minShift) AS ?normShift)
  BIND(100.0 * ((?normRebalance + ?normShift) / 2) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?cashFlowAmount), 2) AS ?avgCashFlowAmount)
       (ROUND(AVG(?totalHoldingValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?riskScore), 2) AS ?avgRiskScore)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cfAmountStr .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(ABS(xsd:decimal(?cfAmount))) AS ?cashFlowAmount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cfAmountStr .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?holdingValue)) AS ?totalHoldingValue)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?valueStr .
      BIND(xsd:decimal(?valueStr) AS ?holdingValue)
    }
    GROUP BY ?investor
  }
  ?investor a wm:Investor ;
            wm:hasRiskTolerance/wm:rdfs:label ?riskTolerance .
  ?health a wm:PortfolioHealth ;
          wm:healthOfInvestor ?investor ;
          wm:riskScore ?riskScoreStr .
  BIND(xsd:decimal(?riskScoreStr) AS ?riskScore)
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?signedCashFlowAmount), 2) AS ?avgSignedCashFlowAmount)
       (ROUND(AVG(?totalHoldingValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?totalSectorInvestment), 2) AS ?avgTotalSectorInvestment)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
    {
        SELECT ?investor ?riskTolerance
               (SUM(COALESCE(?cashFlowAmount, 0)) AS ?netCashFlow)
               (SUM(ABS(COALESCE(?cashFlowAmount, 0))) AS ?signedCashFlowAmount)
        WHERE {
            ?investor a wm:Investor ;
                      wm:hasRiskTolerance/wm:riskTolerance ?riskTolerance ;
                      wm:investorId ?investorId .
            OPTIONAL {
                ?cashFlow a wm:CashFlow ;
                          wm:cashFlowOfInvestor ?investor ;
                          wm:amount ?cashFlowAmountStr .
                BIND(xsd:decimal(?cashFlowAmountStr) AS ?cashFlowAmount)
            }
        }
        GROUP BY ?investor ?riskTolerance
    }
    {
        SELECT ?investor
               (SUM(xsd:decimal(?currentValueStr)) AS ?totalHoldingValue)
        WHERE {
            ?investor a wm:Investor .
            ?holding a wm:PortfolioHolding ;
                     wm:heldByInvestor ?investor ;
                     wm:currentValue ?currentValueStr .
        }
        GROUP BY ?investor
    }
    {
        SELECT ?investor
               (SUM(xsd:decimal(?totalInvestmentStr)) AS ?totalSectorInvestment)
        WHERE {
            ?investor a wm:Investor .
            ?sectorAlloc a wm:SectorAllocation ;
                         wm:allocationOfInvestor ?investor ;
                         wm:totalInvestment ?totalInvestmentStr .
        }
        GROUP BY ?investor
    }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId 
           (SUM(?holdingGain) + SUM(?sectorInvestment) AS ?compositeScore)
    WHERE {
      # Investors with every component recorded
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasHolding ?holding ;
                wm:hasSectorAllocation ?sectorAllocation ;
                wm:hasPortfolioHealth ?portfolioHealth ;
                wm:hasInvestmentGoal ?investmentGoal ;
                wm:hasCashFlow ?cashFlow ;
                wm:hasRebalancingAction ?rebalancingAction .

      # Total holding gain (only holdings with recorded cost and current value)
      ?holding wm:cost ?cost ;
               wm:currentValue ?currentValue .
      FILTER(?cost > 0 && ?currentValue >= 0)
      BIND((?currentValue - ?cost) AS ?holdingGain)

      # Total sector investment
      ?sectorAllocation wm:totalInvestment ?sectorInvestment .
    }
    GROUP BY ?investorId
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId ?compositeScore
    WHERE {
      # Subquery for total holding gain per investor
      {
        SELECT ?investorId (SUM(?gain) AS ?totalGain)
        WHERE {
          ?holding a wm:PortfolioHolding ;
                  wm:heldByInvestor ?investor ;
                  wm:cost ?cost ;
                  wm:currentValue ?currentValue .
          ?investor wm:investorId ?investorId .
          FILTER(?cost > 0 && ?currentValue >= 0)
          BIND((?currentValue - ?cost) AS ?gain)
        }
        GROUP BY ?investorId
      }

      # Subquery for total scenario allocation shift per investor
      {
        SELECT ?investorId (SUM(?allocationShift) AS ?totalShift)
        WHERE {
          ?scenario a wm:ScenarioRebalancing ;
                    wm:scenarioRebalancingOfInvestor ?investor ;
                    wm:currentAllocationPct ?currentAlloc ;
                    wm:newAllocationPct ?newAlloc .
          ?investor wm:investorId ?investorId .
          BIND(ABS(?newAlloc - ?currentAlloc) AS ?allocationShift)
        }
        GROUP BY ?investorId
      }

      # Min-max normalization for both components
      {
        SELECT (MIN(?totalGain) AS ?minGain) (MAX(?totalGain) AS ?maxGain)
               (MIN(?totalShift) AS ?minShift) (MAX(?totalShift) AS ?maxShift)
        WHERE {
          {
            SELECT ?investorId (SUM(?gain) AS ?totalGain)
            WHERE {
              ?holding a wm:PortfolioHolding ;
                      wm:heldByInvestor ?investor ;
                      wm:cost ?cost ;
                      wm:currentValue ?currentValue .
              ?investor wm:investorId ?investorId .
              FILTER(?cost > 0 && ?currentValue >= 0)
              BIND((?currentValue - ?cost) AS ?gain)
            }
            GROUP BY ?investorId
          }

          {
            SELECT ?investorId (SUM(?allocationShift) AS ?totalShift)
            WHERE {
              ?scenario a wm:ScenarioRebalancing ;
                        wm:scenarioRebalancingOfInvestor ?investor ;
                        wm:currentAllocationPct ?currentAlloc ;
                        wm:newAllocationPct ?newAlloc .
              ?investor wm:investorId ?investorId .
              BIND(ABS(?newAlloc - ?currentAlloc) AS ?allocationShift)
            }
            GROUP BY ?investorId
          }
        }
      }

      # Calculate normalized components and composite score
      BIND((?totalGain - ?minGain) / (?maxGain - ?minGain) AS ?normGain)
      BIND((?totalShift - ?minShift) / (?maxShift - ?minShift) AS ?normShift)
      BIND(100 * ((?normGain + ?normShift) / 2) AS ?compositeScore)
    }
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?cashFlowAmount), 2) AS ?avgCashFlowAmount)
       (ROUND(AVG(?totalHoldingValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?goalProgress), 2) AS ?avgGoalProgress)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                 wm:amount ?cfAmountStr .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(ABS(xsd:decimal(?cfAmount))) AS ?cashFlowAmount)
    WHERE {
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                 wm:amount ?cfAmountStr .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?holdingValue)) AS ?totalHoldingValue)
    WHERE {
      ?holding wm:heldByInvestor ?investor ;
               wm:currentValue ?valueStr .
      BIND(xsd:decimal(?valueStr) AS ?holdingValue)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?progress)) AS ?goalProgress)
    WHERE {
      ?goal wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressStr .
      BIND(xsd:decimal(?progressStr) AS ?progress)
    }
    GROUP BY ?investor
  }

  ?investor wm:hasRiskTolerance ?riskToleranceObj .
  ?riskToleranceObj rdfs:label ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?cashFlowAmount), 2) AS ?avgCashFlowAmount)
       (ROUND(AVG(?totalRebalanceAmount), 2) AS ?avgTotalRebalanceAmount)
       (ROUND(AVG(?totalSectorInvestment), 2) AS ?avgTotalSectorInvestment)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  {
    SELECT ?investor ?riskTolerance
           (SUM(?cashFlowAmt) AS ?netCashFlow)
           (AVG(?cashFlowAmt) AS ?cashFlowAmount)
    WHERE {
      ?investor a wm:Investor ;
                wm:hasRiskTolerance ?riskToleranceIRI .
      ?riskToleranceIRI rdfs:label ?riskTolerance .

      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cashFlowAmtStr .
      BIND(xsd:decimal(?cashFlowAmtStr) AS ?cashFlowAmt)
    }
    GROUP BY ?investor ?riskTolerance
  }
  OPTIONAL {
    {
      SELECT ?investor (SUM(?rebalanceAmt) AS ?totalRebalanceAmount)
      WHERE {
        ?rebalancing a wm:RebalancingAction ;
                     wm:rebalancingActionOfInvestor ?investor ;
                     wm:amount ?rebalanceAmtStr .
        BIND(xsd:decimal(?rebalanceAmtStr) AS ?rebalanceAmt)
      }
      GROUP BY ?investor
    }
  }
  OPTIONAL {
    {
      SELECT ?investor (SUM(?sectorInvestment) AS ?totalSectorInvestment)
      WHERE {
        ?sectorAlloc a wm:SectorAllocation ;
                     wm:allocationOfInvestor ?investor ;
                     wm:totalInvestment ?sectorInvStr .
        BIND(xsd:decimal(?sectorInvStr) AS ?sectorInvestment)
      }
      GROUP BY ?investor
    }
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?cashFlowAmount), 2) AS ?avgCashFlowAmount)
       (ROUND(AVG(?totalRebalanceAmount), 2) AS ?avgTotalRebalanceAmount)
       (ROUND(AVG(?scenarioAllocationShift), 2) AS ?avgScenarioAllocationShift)
       (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  {
    SELECT ?investor ?riskTolerance
           (SUM(IF(?cashFlowTypeLabel = "Deposit" || ?cashFlowTypeLabel = "SIP" || ?cashFlowTypeLabel = "Lump Sum", -?amount, ?amount)) AS ?netCashFlow)
           (AVG(?amount) AS ?cashFlowAmount)
    WHERE {
      ?investor a wm:Investor ;
                 wm:hasRiskTolerance ?riskToleranceNode ;
                 wm:hasCashFlow ?cashFlow .
      ?riskToleranceNode rdfs:label ?riskTolerance .
      ?cashFlow wm:amount ?amount ;
                wm:hasCashFlowType ?cashFlowTypeNode .
      ?cashFlowTypeNode rdfs:label ?cashFlowTypeLabel .
    }
    GROUP BY ?investor ?riskTolerance
  }
  OPTIONAL {
    {
      SELECT ?investor (SUM(ABS(?rebalanceAmount)) AS ?totalRebalanceAmount)
      WHERE {
        ?investor wm:hasRebalancingAction ?rebalancingAction .
        ?rebalancingAction wm:amount ?rebalanceAmount .
      }
      GROUP BY ?investor
    }
  }
  OPTIONAL {
    {
      SELECT ?investor (AVG(?newAllocation - ?currentAllocation) AS ?scenarioAllocationShift)
      WHERE {
        ?investor wm:hasScenarioRebalancing ?scenarioRebalancing .
        ?scenarioRebalancing wm:currentAllocationPct ?currentAllocation ;
                             wm:newAllocationPct ?newAllocation .
      }
      GROUP BY ?investor
    }
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

