PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?cashFlowAmount), 2) AS ?avgCashFlowAmount)
       (ROUND(AVG(?totalSectorInvestment), 2) AS ?avgTotalSectorInvestment)
       (ROUND(AVG(?riskScore), 2) AS ?avgRiskScore)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cfAmountStr .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(ABS(xsd:decimal(?cfAmount))) AS ?cashFlowAmount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cfAmountStr .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?totalInvestment)) AS ?totalSectorInvestment)
    WHERE {
      ?sectorAlloc a wm:SectorAllocation ;
                   wm:allocationOfInvestor ?investor ;
                   wm:totalInvestment ?totalInvestmentStr .
      BIND(xsd:decimal(?totalInvestmentStr) AS ?totalInvestment)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (xsd:decimal(?rs) AS ?riskScore)
    WHERE {
      ?portfolioHealth a wm:PortfolioHealth ;
                       wm:healthOfInvestor ?investor ;
                       wm:riskScore ?rs .
    }
  }
  ?investor a wm:Investor ;
            wm:hasRiskTolerance/wm:rdfs:label ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?cashFlowAmount), 2) AS ?avgCashFlowAmount)
       (ROUND(AVG(?totalRebalanceAmount), 2) AS ?avgTotalRebalanceAmount)
       (ROUND(AVG(?riskScore), 2) AS ?avgRiskScore)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  # Get investor risk tolerance
  ?investor a wm:Investor ;
            wm:hasRiskTolerance/wm:rdfs:label ?riskTolerance ;
            wm:investorId ?investorId .

  # Compute net cash flow per investor (sum of amounts, respecting sign)
  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor/wm:investorId ?investorId ;
                wm:amount ?cfAmountStr .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investorId
  }

  # Compute average cash flow amount per investor (absolute average)
  {
    SELECT ?investorId (AVG(ABS(xsd:decimal(?cfAmount))) AS ?cashFlowAmount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor/wm:investorId ?investorId ;
                wm:amount ?cfAmountStr .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investorId
  }

  # Compute total rebalance amount per investor (sum of absolute amounts)
  {
    SELECT ?investorId (SUM(ABS(xsd:decimal(?rbAmount))) AS ?totalRebalanceAmount)
    WHERE {
      ?rebalancing a wm:RebalancingAction ;
                   wm:rebalancingActionOfInvestor/wm:investorId ?investorId ;
                   wm:amount ?rbAmountStr .
      BIND(xsd:decimal(?rbAmountStr) AS ?rbAmount)
    }
    GROUP BY ?investorId
  }

  # Get risk score per investor
  {
    SELECT ?investorId (AVG(xsd:decimal(?riskScoreStr)) AS ?riskScore)
    WHERE {
      ?health a wm:PortfolioHealth ;
              wm:healthOfInvestor/wm:investorId ?investorId ;
              wm:riskScore ?riskScoreStr .
    }
    GROUP BY ?investorId
  }

  # Join all per-investor aggregates
  BIND(IRI(CONCAT("https://wealth.example.org/ontology/Investor_", ?investorId)) AS ?investor)
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?cashFlowAmount), 2) AS ?avgCashFlowAmount)
       (ROUND(AVG(?totalSectorInvestment), 2) AS ?avgTotalSectorInvestment)
       (ROUND(AVG(?allocationShift), 2) AS ?avgScenarioAllocationShift)
WHERE {
  {
    SELECT ?investor ?riskTolerance (SUM(xsd:decimal(?cashFlowAmountSigned)) AS ?netCashFlow)
    WHERE {
      ?investor a wm:Investor ;
                 wm:hasRiskTolerance/wm:riskTolerance ?riskTolerance .
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cashFlowAmountRaw ;
                wm:type ?cashFlowType .
      BIND(xsd:decimal(?cashFlowAmountRaw) AS ?cashFlowAmount)
      BIND(IF(?cashFlowType IN ("SIP", "Lump Sum", "Deposit"), -?cashFlowAmount, ?cashFlowAmount) AS ?cashFlowAmountSigned)
    }
    GROUP BY ?investor ?riskTolerance
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?cashFlowAmount)) AS ?cashFlowAmount)
    WHERE {
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cashFlowAmountRaw .
      BIND(xsd:decimal(?cashFlowAmountRaw) AS ?cashFlowAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?totalInvestment)) AS ?totalSectorInvestment)
    WHERE {
      ?sectorAlloc wm:allocationOfInvestor ?investor ;
                   wm:totalInvestment ?totalInvestmentRaw .
      BIND(xsd:decimal(?totalInvestmentRaw) AS ?totalInvestment)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc)) AS ?allocationShift)
    WHERE {
      ?scenarioRebal wm:scenarioRebalancingOfInvestor ?investor ;
                     wm:currentAllocationPct ?currentAlloc ;
                     wm:newAllocationPct ?newAlloc .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?cashFlowAmount), 2) AS ?avgCashFlowAmount)
       (ROUND(AVG(?allocationShift), 2) AS ?avgAllocationShift)
       (ROUND(AVG(?riskScore), 2) AS ?avgRiskScore)
       (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance/wm:label ?riskTolerance ;
            wm:investorId ?investorId .

  OPTIONAL {
    ?cashFlow a wm:CashFlow ;
              wm:cashFlowOfInvestor ?investor ;
              wm:amount ?cashFlowAmountStr .
    BIND(xsd:decimal(?cashFlowAmountStr) AS ?cashFlowAmount)
  }

  OPTIONAL {
    ?scenarioRebalancing a wm:ScenarioRebalancing ;
                         wm:scenarioRebalancingOfInvestor ?investor ;
                         wm:currentAllocationPct ?currentAllocStr ;
                         wm:newAllocationPct ?newAllocStr .
    BIND(xsd:decimal(?currentAllocStr) AS ?currentAlloc)
    BIND(xsd:decimal(?newAllocStr) AS ?newAlloc)
    BIND(?newAlloc - ?currentAlloc AS ?allocationShift)
  }

  OPTIONAL {
    ?portfolioHealth a wm:PortfolioHealth ;
                     wm:healthOfInvestor ?investor ;
                     wm:riskScore ?riskScoreStr .
    BIND(xsd:decimal(?riskScoreStr) AS ?riskScore)
  }

  {
    SELECT ?investor (SUM(?signedAmount) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amountStr ;
                wm:hasCashFlowType/wm:label ?type .
      BIND(xsd:decimal(?amountStr) AS ?amount)
      BIND(IF(?type IN ("SIP", "Lump Sum", "Deposit"), -?amount, ?amount) AS ?signedAmount)
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?cashFlowAmount), 2) AS ?avgCashFlowAmount)
       (ROUND(AVG(?allocationShift), 2) AS ?avgScenarioAllocationShift)
       (ROUND(AVG(?goalProgress), 2) AS ?avgGoalProgress)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                 wm:cashFlowOfInvestor ?investor ;
                 wm:amount ?cfAmountStr .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?cfAmount)) AS ?cashFlowAmount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                 wm:cashFlowOfInvestor ?investor ;
                 wm:amount ?cfAmountStr .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?allocationShift)
    WHERE {
      ?scenarioReb a wm:ScenarioRebalancing ;
                    wm:scenarioRebalancingOfInvestor ?investor ;
                    wm:currentAllocationPct ?currAllocStr ;
                    wm:newAllocationPct ?newAllocStr .
      BIND(xsd:decimal(?currAllocStr) AS ?currAlloc)
      BIND(xsd:decimal(?newAllocStr) AS ?newAlloc)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?progress)) AS ?goalProgress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressStr .
      BIND(xsd:decimal(?progressStr) AS ?progress)
    }
    GROUP BY ?investor
  }
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskToleranceObj .
  ?riskToleranceObj rdfs:label ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?totalHoldingValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?holdingReturn), 2) AS ?avgHoldingReturn)
       (ROUND(AVG(?totalRebalanceAmount), 2) AS ?avgTotalRebalanceAmount)
       (ROUND(AVG(?totalSectorInvestment), 2) AS ?avgTotalSectorInvestment)
       (COUNT(DISTINCT ?investorId) AS ?n_investors)
WHERE {
  {
    SELECT ?investorId ?riskTolerance
           (SUM(COALESCE(?currentValue, 0)) AS ?totalHoldingValue)
    WHERE {
      ?investor wm:investorId ?investorId ;
                wm:hasRiskTolerance/wm:rdfs:label ?riskTolerance .
      OPTIONAL {
        ?holding wm:heldByInvestor ?investor ;
                 wm:currentValue ?currentValue .
      }
    }
    GROUP BY ?investorId ?riskTolerance
  }
  {
    SELECT ?investorId
           (AVG(?returnsPct) AS ?holdingReturn)
    WHERE {
      ?holding wm:heldByInvestor ?investor ;
               wm:returnsPct ?returnsPct ;
               wm:cost ?cost ;
               wm:currentValue ?cv .
      FILTER(?cost > 0 && ?cv >= 0)
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (SUM(COALESCE(?rebalanceAmount, 0)) AS ?totalRebalanceAmount)
    WHERE {
      ?investor wm:investorId ?investorId .
      OPTIONAL {
        ?rebalancing wm:rebalancingActionOfInvestor ?investor ;
                      wm:amount ?rebalanceAmount .
      }
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (SUM(COALESCE(?totalInvestment, 0)) AS ?totalSectorInvestment)
    WHERE {
      ?investor wm:investorId ?investorId .
      OPTIONAL {
        ?sectorAlloc wm:allocationOfInvestor ?investor ;
                      wm:totalInvestment ?totalInvestment .
      }
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?totalHoldingValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?holdingReturn), 2) AS ?avgHoldingReturn)
       (ROUND(AVG(?totalRebalanceAmount), 2) AS ?avgTotalRebalanceAmount)
       (ROUND(AVG(?allocationShift), 2) AS ?avgScenarioAllocationShift)
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?phCurrentValue)) AS ?totalHoldingValue)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?phCurrentValue .
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?phReturnsPct)) AS ?holdingReturn)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:cost ?cost ;
               wm:currentValue ?cv ;
               wm:returnsPct ?phReturnsPct .
      FILTER(xsd:decimal(?cost) > 0 && xsd:decimal(?cv) >= 0)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(ABS(xsd:decimal(?raAmount))) AS ?totalRebalanceAmount)
    WHERE {
      ?rebalancing a wm:RebalancingAction ;
                   wm:rebalancingActionOfInvestor ?investor ;
                   wm:amount ?raAmount .
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?srNewAllocationPct) - xsd:decimal(?srCurrentAllocationPct)) AS ?allocationShift)
    WHERE {
      ?scenario a wm:ScenarioRebalancing ;
                wm:scenarioRebalancingOfInvestor ?investor ;
                wm:newAllocationPct ?srNewAllocationPct ;
                wm:currentAllocationPct ?srCurrentAllocationPct .
    }
    GROUP BY ?investor
  }
  ?investor a wm:Investor ;
            wm:hasRiskTolerance/wm:rdfs:label ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
