PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?cashFlowAmount), 2) AS ?avgCashFlowAmount)
       (ROUND(AVG(?riskScore), 2) AS ?avgRiskScore)
       (ROUND(AVG(?goalProgress), 2) AS ?avgGoalProgress)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskToleranceNode .
  ?riskToleranceNode rdfs:label ?riskTolerance .

  OPTIONAL {
    {
      SELECT ?investor (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
      WHERE {
        ?cashFlow a wm:CashFlow ;
                  wm:cashFlowOfInvestor ?investor ;
                  wm:amount ?cfAmountStr .
        BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
      }
      GROUP BY ?investor
    }
  }

  OPTIONAL {
    {
      SELECT ?investor (AVG(xsd:decimal(?cfAmount)) AS ?cashFlowAmount)
      WHERE {
        ?cashFlow a wm:CashFlow ;
                  wm:cashFlowOfInvestor ?investor ;
                  wm:amount ?cfAmountStr .
        BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
      }
      GROUP BY ?investor
    }
  }

  OPTIONAL {
    ?health a wm:PortfolioHealth ;
            wm:healthOfInvestor ?investor ;
            wm:riskScore ?riskScoreStr .
    BIND(xsd:decimal(?riskScoreStr) AS ?riskScore)
  }

  OPTIONAL {
    {
      SELECT ?investor (AVG(xsd:decimal(?progress)) AS ?goalProgress)
      WHERE {
        ?goal a wm:InvestmentGoal ;
              wm:belongsToInvestor ?investor ;
              wm:progressPct ?progressStr .
        BIND(xsd:decimal(?progressStr) AS ?progress)
      }
      GROUP BY ?investor
    }
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?riskToleranceLabel
       (ROUND(AVG(?totalHoldingValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?avgHoldingReturn), 2) AS ?avgHoldingReturn)
       (ROUND(AVG(?totalRebalanceAmount), 2) AS ?avgTotalRebalanceAmount)
       (ROUND(AVG(?avgGoalProgress), 2) AS ?avgGoalProgress)
       (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskTolerance .
  ?riskTolerance rdfs:label ?riskToleranceLabel .

  {
    SELECT ?investor (SUM(xsd:decimal(?holdingCurrentValue)) AS ?totalHoldingValue)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?holdingCurrentValue .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (AVG(xsd:decimal(?holdingReturn)) AS ?avgHoldingReturn)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:returnsPct ?holdingReturn ;
               wm:cost ?cost ;
               wm:currentValue ?cv .
      FILTER(xsd:decimal(?cost) > 0 && xsd:decimal(?cv) >= 0)
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(ABS(xsd:decimal(?rebalanceAmount))) AS ?totalRebalanceAmount)
    WHERE {
      ?rebal a wm:RebalancingAction ;
             wm:rebalancingActionOfInvestor ?investor ;
             wm:amount ?rebalanceAmount .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (AVG(xsd:decimal(?goalProgress)) AS ?avgGoalProgress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?goalProgress .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskToleranceLabel
ORDER BY ?riskToleranceLabel

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor .
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor .
      ?rebalancing a wm:RebalancingAction ;
                   wm:rebalancingActionOfInvestor ?investor .
    }
    GROUP BY ?investorId
    HAVING (COUNT(DISTINCT ?cashFlow) > 0 && COUNT(DISTINCT ?holding) > 0 && COUNT(DISTINCT ?rebalancing) > 0)
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cfAmount .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?totalHoldingGain)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue .
      ?investor wm:investorId ?investorId .
      FILTER(xsd:decimal(?cost) > 0 && xsd:decimal(?currentValue) >= 0)
      BIND(xsd:decimal(?currentValue) - xsd:decimal(?cost) AS ?gain)
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?rbAmount)) AS ?totalRebalanceAmount)
    WHERE {
      ?rebalancing a wm:RebalancingAction ;
                   wm:rebalancingActionOfInvestor ?investor ;
                   wm:amount ?rbAmount .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  BIND(xsd:decimal(?netCashFlow) + xsd:decimal(?totalHoldingGain) + xsd:decimal(?totalRebalanceAmount) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      FILTER EXISTS { ?investor wm:hasCashFlow ?cf . }
      FILTER EXISTS { ?investor wm:hasHolding ?h . }
      FILTER EXISTS { ?investor wm:hasSectorAllocation ?sa . }
    }
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasCashFlow ?cf .
      ?cf a wm:CashFlow ;
          wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?totalHoldingGain)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasHolding ?h .
      ?h a wm:PortfolioHolding ;
         wm:cost ?cost ;
         wm:currentValue ?currentValue .
      FILTER(xsd:decimal(?cost) > 0)
      BIND((xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?gain)
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?totalInvestment)) AS ?totalSectorInvestment)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasSectorAllocation ?sa .
      ?sa a wm:SectorAllocation ;
          wm:totalInvestment ?totalInvestment .
    }
    GROUP BY ?investorId
  }
  BIND((xsd:decimal(?netCashFlow) + xsd:decimal(?totalHoldingGain) + xsd:decimal(?totalSectorInvestment)) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?riskToleranceLabel
       (ROUND(AVG(?totalHoldingValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?holdingReturn), 2) AS ?avgHoldingReturn)
       (ROUND(AVG(?totalSectorInvestment), 2) AS ?avgTotalSectorInvestment)
       (ROUND(AVG(?scenarioAllocationShift), 2) AS ?avgScenarioAllocationShift)
WHERE {
  {
    SELECT ?investor ?riskToleranceLabel (SUM(xsd:decimal(?currentValue)) AS ?totalHoldingValue)
    WHERE {
      ?investor a wm:Investor ;
                wm:hasRiskTolerance ?riskTolerance .
      ?riskTolerance rdfs:label ?riskToleranceLabel .
      ?holding wm:heldByInvestor ?investor ;
               wm:currentValue ?currentValue .
      FILTER(xsd:decimal(?currentValue) >= 0)
    }
    GROUP BY ?investor ?riskToleranceLabel
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?returnsPct)) AS ?holdingReturn)
    WHERE {
      ?holding wm:heldByInvestor ?investor ;
               wm:returnsPct ?returnsPct ;
               wm:cost ?cost ;
               wm:currentValue ?cv .
      FILTER(xsd:decimal(?cost) > 0 && xsd:decimal(?cv) >= 0)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?totalInvestment)) AS ?totalSectorInvestment)
    WHERE {
      ?sectorAlloc wm:allocationOfInvestor ?investor ;
                   wm:totalInvestment ?totalInvestment .
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?newAllocationPct) - xsd:decimal(?currentAllocationPct)) AS ?scenarioAllocationShift)
    WHERE {
      ?scenarioRebal wm:scenarioRebalancingOfInvestor ?investor ;
                     wm:currentAllocationPct ?currentAllocationPct ;
                     wm:newAllocationPct ?newAllocationPct .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskToleranceLabel
ORDER BY ?riskToleranceLabel

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      FILTER EXISTS { ?investor wm:hasCashFlow ?cf . }
      FILTER EXISTS { ?investor wm:hasRebalancingAction ?ra . }
      FILTER EXISTS { ?investor wm:hasInvestmentGoal ?ig . }
    }
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasCashFlow ?cf .
      ?cf wm:amount ?cfAmountStr .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?raAmount)) AS ?totalRebalanceAmount)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasRebalancingAction ?ra .
      ?ra wm:amount ?raAmountStr .
      BIND(xsd:decimal(?raAmountStr) AS ?raAmount)
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (AVG(xsd:decimal(?shortfall)) AS ?avgGoalShortfall)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasInvestmentGoal ?ig .
      ?ig wm:shortfall ?shortfallStr .
      BIND(xsd:decimal(?shortfallStr) AS ?shortfall)
    }
    GROUP BY ?investorId
  }

  BIND((?netCashFlow + ?totalRebalanceAmount - ?avgGoalShortfall) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * ((?normNetCashFlow + ?normTotalRebalanceAmount + ?normRiskScore) / 3) AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               (SUM(COALESCE(?cashFlowAmount, 0)) AS ?netCashFlow)
        WHERE {
          ?cashFlow wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?cashFlowAmount .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(COALESCE(?rebalanceAmount, 0)) AS ?totalRebalanceAmount)
        WHERE {
          ?rebalancingAction wm:rebalancingActionOfInvestor ?investor ;
                             wm:amount ?rebalanceAmount .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (MAX(COALESCE(?riskScoreValue, 0)) AS ?riskScore)
        WHERE {
          ?portfolioHealth wm:healthOfInvestor ?investor ;
                           wm:riskScore ?riskScoreValue .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      BIND(?netCashFlow AS ?ncf)
      BIND(?totalRebalanceAmount AS ?tra)
      BIND(?riskScore AS ?rs)
      {
        SELECT (MIN(?ncf) AS ?minNcf) (MAX(?ncf) AS ?maxNcf)
               (MIN(?tra) AS ?minTra) (MAX(?tra) AS ?maxTra)
               (MIN(?rs) AS ?minRs) (MAX(?rs) AS ?maxRs)
        WHERE {
          {
            SELECT ?investorId
                   (SUM(COALESCE(?cashFlowAmount, 0)) AS ?ncf)
            WHERE {
              ?cashFlow wm:cashFlowOfInvestor ?investor ;
                        wm:amount ?cashFlowAmount .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId
                   (SUM(COALESCE(?rebalanceAmount, 0)) AS ?tra)
            WHERE {
              ?rebalancingAction wm:rebalancingActionOfInvestor ?investor ;
                                 wm:amount ?rebalanceAmount .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId
                   (MAX(COALESCE(?riskScoreValue, 0)) AS ?rs)
            WHERE {
              ?portfolioHealth wm:healthOfInvestor ?investor ;
                               wm:riskScore ?riskScoreValue .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
        }
      }
      BIND((?ncf - ?minNcf) / (?maxNcf - ?minNcf) AS ?normNetCashFlow)
      BIND((?tra - ?minTra) / (?maxTra - ?minTra) AS ?normTotalRebalanceAmount)
      BIND((?rs - ?minRs) / (?maxRs - ?minRs) AS ?normRiskScore)
    }
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?investorId ?investorName ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
           (SUM(xsd:decimal(?rebalanceAmount)) AS ?totalRebalanceAmount)
           (SUM(xsd:decimal(?sectorInvestment)) AS ?totalSectorInvestment)
    WHERE {
      # Get net cash flow per investor
      {
        SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?cashFlowAmount)
        WHERE {
          ?cashFlow a wm:CashFlow ;
                    wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?cfAmountStr .
          ?investor wm:investorId ?investorId .
          BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
        }
        GROUP BY ?investorId
      }
      # Get total rebalance amount per investor
      {
        SELECT ?investorId (SUM(xsd:decimal(?rbAmount)) AS ?rebalanceAmount)
        WHERE {
          ?rebalancing a wm:RebalancingAction ;
                       wm:rebalancingActionOfInvestor ?investor ;
                       wm:amount ?rbAmountStr .
          ?investor wm:investorId ?investorId .
          BIND(xsd:decimal(?rbAmountStr) AS ?rbAmount)
        }
        GROUP BY ?investorId
      }
      # Get total sector investment per investor
      {
        SELECT ?investorId (SUM(xsd:decimal(?sectorTotal)) AS ?sectorInvestment)
        WHERE {
          ?sectorAlloc a wm:SectorAllocation ;
                        wm:allocationOfInvestor ?investor ;
                        wm:totalInvestment ?sectorTotalStr .
          ?investor wm:investorId ?investorId .
          BIND(xsd:decimal(?sectorTotalStr) AS ?sectorTotal)
        }
        GROUP BY ?investorId
      }
    }
    GROUP BY ?investorId
    HAVING (COUNT(?cashFlowAmount) > 0 && COUNT(?rebalanceAmount) > 0 && COUNT(?sectorInvestment) > 0)
  }

  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .

  BIND((?netCashFlow + ?totalRebalanceAmount + ?totalSectorInvestment) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * ((?normNetCashFlow + ?normTotalSectorInvestment + ?normRiskScore) / 3) AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               (SUM(?cashFlowAmount) AS ?netCashFlow)
        WHERE {
          ?cashFlow wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?cashFlowAmount .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(?totalInvestment) AS ?totalSectorInvestment)
        WHERE {
          ?sectorAlloc wm:allocationOfInvestor ?investor ;
                       wm:totalInvestment ?totalInvestment .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (AVG(?riskScoreVal) AS ?riskScore)
        WHERE {
          ?health wm:healthOfInvestor ?investor ;
                  wm:riskScore ?riskScoreVal .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      BIND((?netCashFlow - ?minNetCashFlow) / (?maxNetCashFlow - ?minNetCashFlow) AS ?normNetCashFlow)
      BIND((?totalSectorInvestment - ?minTotalSectorInvestment) / (?maxTotalSectorInvestment - ?minTotalSectorInvestment) AS ?normTotalSectorInvestment)
      BIND((?riskScore - ?minRiskScore) / (?maxRiskScore - ?minRiskScore) AS ?normRiskScore)
    }
    GROUP BY ?investorId ?netCashFlow ?totalSectorInvestment ?riskScore
             ?minNetCashFlow ?maxNetCashFlow
             ?minTotalSectorInvestment ?maxTotalSectorInvestment
             ?minRiskScore ?maxRiskScore
  }
  {
    SELECT (MIN(?netCashFlow) AS ?minNetCashFlow) (MAX(?netCashFlow) AS ?maxNetCashFlow)
           (MIN(?totalSectorInvestment) AS ?minTotalSectorInvestment) (MAX(?totalSectorInvestment) AS ?maxTotalSectorInvestment)
           (MIN(?riskScore) AS ?minRiskScore) (MAX(?riskScore) AS ?maxRiskScore)
    WHERE {
      {
        SELECT ?investorId (SUM(?cashFlowAmount) AS ?netCashFlow)
        WHERE {
          ?cashFlow wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?cashFlowAmount .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(?totalInvestment) AS ?totalSectorInvestment)
        WHERE {
          ?sectorAlloc wm:allocationOfInvestor ?investor ;
                       wm:totalInvestment ?totalInvestment .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId (AVG(?riskScoreVal) AS ?riskScore)
        WHERE {
          ?health wm:healthOfInvestor ?investor ;
                  wm:riskScore ?riskScoreVal .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
    }
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      FILTER EXISTS { ?investor wm:hasCashFlow ?cf . }
      FILTER EXISTS { ?investor wm:hasSectorAllocation ?sa . }
      FILTER EXISTS { ?investor wm:hasInvestmentGoal ?goal . }
    }
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?investor ;
          wm:amount ?cfAmountStr .
      ?investor wm:investorId ?investorId .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?totalInv)) AS ?totalSectorInvestment)
    WHERE {
      ?sa a wm:SectorAllocation ;
          wm:allocationOfInvestor ?investor ;
          wm:totalInvestment ?totalInvStr .
      ?investor wm:investorId ?investorId .
      BIND(xsd:decimal(?totalInvStr) AS ?totalInv)
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (AVG(xsd:decimal(?shortfall)) AS ?avgGoalShortfall)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:shortfall ?shortfallStr .
      ?investor wm:investorId ?investorId .
      BIND(xsd:decimal(?shortfallStr) AS ?shortfall)
    }
    GROUP BY ?investorId
  }

  BIND((?netCashFlow + ?totalSectorInvestment - ?avgGoalShortfall) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
          (100 * ((?normNetCashFlow + ?normTotalGain + ?normTotalShift) / 3) AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               (SUM(COALESCE(?cashFlowAmount, 0)) AS ?netCashFlow)
        WHERE {
          ?cashFlow a wm:CashFlow ;
                    wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?cashFlowAmountStr .
          ?investor wm:investorId ?investorId .
          BIND(xsd:decimal(?cashFlowAmountStr) AS ?cashFlowAmount)
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(?gain) AS ?totalGain)
        WHERE {
          ?holding a wm:PortfolioHolding ;
                   wm:heldByInvestor ?investor ;
                   wm:cost ?costStr ;
                   wm:currentValue ?currentValueStr .
          ?investor wm:investorId ?investorId .
          FILTER(?costStr != "" && ?currentValueStr != "")
          BIND(xsd:decimal(?costStr) AS ?cost)
          BIND(xsd:decimal(?currentValueStr) AS ?currentValue)
          BIND((?currentValue - ?cost) AS ?gain)
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(?allocationShift) AS ?totalShift)
        WHERE {
          ?scenario a wm:ScenarioRebalancing ;
                    wm:scenarioRebalancingOfInvestor ?investor ;
                    wm:currentAllocationPct ?currentAllocStr ;
                    wm:newAllocationPct ?newAllocStr .
          ?investor wm:investorId ?investorId .
          BIND(xsd:decimal(?currentAllocStr) AS ?currentAlloc)
          BIND(xsd:decimal(?newAllocStr) AS ?newAlloc)
          BIND((?newAlloc - ?currentAlloc) AS ?allocationShift)
        }
        GROUP BY ?investorId
      }
      BIND(?netCashFlow AS ?rawNetCashFlow)
      BIND(?totalGain AS ?rawTotalGain)
      BIND(?totalShift AS ?rawTotalShift)
    }
    GROUP BY ?investorId ?rawNetCashFlow ?rawTotalGain ?rawTotalShift
    HAVING (COUNT(?rawNetCashFlow) > 0 && COUNT(?rawTotalGain) > 0 && COUNT(?rawTotalShift) > 0)
  }
  {
    SELECT (MIN(?rawNetCashFlow) AS ?minNetCashFlow)
           (MAX(?rawNetCashFlow) AS ?maxNetCashFlow)
           (MIN(?rawTotalGain) AS ?minTotalGain)
           (MAX(?rawTotalGain) AS ?maxTotalGain)
           (MIN(?rawTotalShift) AS ?minTotalShift)
           (MAX(?rawTotalShift) AS ?maxTotalShift)
    WHERE {
      {
        SELECT ?investorId
               (SUM(COALESCE(?cashFlowAmount, 0)) AS ?rawNetCashFlow)
        WHERE {
          ?cashFlow a wm:CashFlow ;
                    wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?cashFlowAmountStr .
          ?investor wm:investorId ?investorId .
          BIND(xsd:decimal(?cashFlowAmountStr) AS ?cashFlowAmount)
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(?gain) AS ?rawTotalGain)
        WHERE {
          ?holding a wm:PortfolioHolding ;
                   wm:heldByInvestor ?investor ;
                   wm:cost ?costStr ;
                   wm:currentValue ?currentValueStr .
          ?investor wm:investorId ?investorId .
          FILTER(?costStr != "" && ?currentValueStr != "")
          BIND(xsd:decimal(?costStr) AS ?cost)
          BIND(xsd:decimal(?currentValueStr) AS ?currentValue)
          BIND((?currentValue - ?cost) AS ?gain)
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(?allocationShift) AS ?rawTotalShift)
        WHERE {
          ?scenario a wm:ScenarioRebalancing ;
                    wm:scenarioRebalancingOfInvestor ?investor ;
                    wm:currentAllocationPct ?currentAllocStr ;
                    wm:newAllocationPct ?newAllocStr .
          ?investor wm:investorId ?investorId .
          BIND(xsd:decimal(?currentAllocStr) AS ?currentAlloc)
          BIND(xsd:decimal(?newAllocStr) AS ?newAlloc)
          BIND((?newAlloc - ?currentAlloc) AS ?allocationShift)
        }
        GROUP BY ?investorId
      }
    }
    GROUP BY ?investorId
    HAVING (COUNT(?rawNetCashFlow) > 0 && COUNT(?rawTotalGain) > 0 && COUNT(?rawTotalShift) > 0)
  }
  BIND((?rawNetCashFlow - ?minNetCashFlow) / (?maxNetCashFlow - ?minNetCashFlow) AS ?normNetCashFlow)
  BIND((?rawTotalGain - ?minTotalGain) / (?maxTotalGain - ?minTotalGain) AS ?normTotalGain)
  BIND((?rawTotalShift - ?minTotalShift) / (?maxTotalShift - ?minTotalShift) AS ?normTotalShift)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * ((?normNetCashFlow + ?normAllocationShift + ?normRiskScore) / 3) AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
        WHERE {
          ?cashFlow wm:cashFlowOfInvestor ?investor .
          ?cashFlow wm:amount ?amount .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc)) AS ?totalAllocationShift)
        WHERE {
          ?scenarioReb wm:scenarioRebalancingOfInvestor ?investor .
          ?scenarioReb wm:newAllocationPct ?newAlloc .
          ?scenarioReb wm:currentAllocationPct ?currentAlloc .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (xsd:decimal(?riskScoreVal) AS ?riskScore)
        WHERE {
          ?health wm:healthOfInvestor ?investor .
          ?health wm:riskScore ?riskScoreVal .
          ?investor wm:investorId ?investorId .
        }
      }
      BIND(?netCashFlow AS ?rawNetCashFlow)
      BIND(?totalAllocationShift AS ?rawAllocationShift)
      BIND(?riskScore AS ?rawRiskScore)
      {
        SELECT (MIN(?rawNetCashFlow) AS ?minNetCashFlow)
               (MAX(?rawNetCashFlow) AS ?maxNetCashFlow)
               (MIN(?rawAllocationShift) AS ?minAllocationShift)
               (MAX(?rawAllocationShift) AS ?maxAllocationShift)
               (MIN(?rawRiskScore) AS ?minRiskScore)
               (MAX(?rawRiskScore) AS ?maxRiskScore)
        WHERE {
          {
            SELECT ?investorIdInner (SUM(xsd:decimal(?amountInner)) AS ?rawNetCashFlow)
            WHERE {
              ?cashFlowInner wm:cashFlowOfInvestor ?investorInner .
              ?cashFlowInner wm:amount ?amountInner .
              ?investorInner wm:investorId ?investorIdInner .
            }
            GROUP BY ?investorIdInner
          }
          {
            SELECT ?investorIdInner (SUM(xsd:decimal(?newAllocInner) - xsd:decimal(?currentAllocInner)) AS ?rawAllocationShift)
            WHERE {
              ?scenarioRebInner wm:scenarioRebalancingOfInvestor ?investorInner .
              ?scenarioRebInner wm:newAllocationPct ?newAllocInner .
              ?scenarioRebInner wm:currentAllocationPct ?currentAllocInner .
              ?investorInner wm:investorId ?investorIdInner .
            }
            GROUP BY ?investorIdInner
          }
          {
            SELECT ?investorIdInner (xsd:decimal(?riskScoreValInner) AS ?rawRiskScore)
            WHERE {
              ?healthInner wm:healthOfInvestor ?investorInner .
              ?healthInner wm:riskScore ?riskScoreValInner .
              ?investorInner wm:investorId ?investorIdInner .
            }
          }
        }
      }
      BIND((?rawNetCashFlow - ?minNetCashFlow) / (?maxNetCashFlow - ?minNetCashFlow) AS ?normNetCashFlow)
      BIND((?rawAllocationShift - ?minAllocationShift) / (?maxAllocationShift - ?minAllocationShift) AS ?normAllocationShift)
      BIND((?rawRiskScore - ?minRiskScore) / (?maxRiskScore - ?minRiskScore) AS ?normRiskScore)
    }
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * ((?normNetCashFlow + ?normTotalShift + (1 - ?normAvgShortfall)) / 3) AS ?compositeScore)
    WHERE {
      # Subquery to compute raw components per investor
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
               (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc)) AS ?totalShift)
               (AVG(xsd:decimal(?shortfall)) AS ?avgShortfall)
        WHERE {
          # Get cash flows
          ?cashFlow a wm:CashFlow ;
                    wm:cashFlowOfInvestor/wm:investorId ?investorId ;
                    wm:amount ?cashFlowAmount .
          # Get scenario rebalancing
          ?scenarioRebal a wm:ScenarioRebalancing ;
                         wm:scenarioRebalancingOfInvestor/wm:investorId ?investorId ;
                         wm:newAllocationPct ?newAlloc ;
                         wm:currentAllocationPct ?currentAlloc .
          # Get goal shortfall
          ?goal a wm:InvestmentGoal ;
                wm:belongsToInvestor/wm:investorId ?investorId ;
                wm:shortfall ?shortfall .
        }
        GROUP BY ?investorId
        HAVING (COUNT(DISTINCT ?cashFlow) > 0 && COUNT(DISTINCT ?scenarioRebal) > 0 && COUNT(DISTINCT ?goal) > 0)
      }
      # Subquery to get min and max for normalization
      {
        SELECT (MIN(?netCashFlow) AS ?minNetCashFlow)
               (MAX(?netCashFlow) AS ?maxNetCashFlow)
               (MIN(?totalShift) AS ?minTotalShift)
               (MAX(?totalShift) AS ?maxTotalShift)
               (MIN(?avgShortfall) AS ?minAvgShortfall)
               (MAX(?avgShortfall) AS ?maxAvgShortfall)
        WHERE {
          {
            SELECT ?investorId
                   (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
                   (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc)) AS ?totalShift)
                   (AVG(xsd:decimal(?shortfall)) AS ?avgShortfall)
            WHERE {
              ?cashFlow a wm:CashFlow ;
                        wm:cashFlowOfInvestor/wm:investorId ?investorId ;
                        wm:amount ?cashFlowAmount .
              ?scenarioRebal a wm:ScenarioRebalancing ;
                             wm:scenarioRebalancingOfInvestor/wm:investorId ?investorId ;
                             wm:newAllocationPct ?newAlloc ;
                             wm:currentAllocationPct ?currentAlloc .
              ?goal a wm:InvestmentGoal ;
                    wm:belongsToInvestor/wm:investorId ?investorId ;
                    wm:shortfall ?shortfall .
            }
            GROUP BY ?investorId
            HAVING (COUNT(DISTINCT ?cashFlow) > 0 && COUNT(DISTINCT ?scenarioRebal) > 0 && COUNT(DISTINCT ?goal) > 0)
          }
        }
      }
      # Normalize components
      BIND((?netCashFlow - ?minNetCashFlow) / (?maxNetCashFlow - ?minNetCashFlow) AS ?normNetCashFlow)
      BIND((?totalShift - ?minTotalShift) / (?maxTotalShift - ?minTotalShift) AS ?normTotalShift)
      BIND((?avgShortfall - ?minAvgShortfall) / (?maxAvgShortfall - ?minAvgShortfall) AS ?normAvgShortfall)
    }
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId (100 * AVG(?normalisedComponent) AS ?compositeScore)
    WHERE {
      {
        # Net cash flow per investor
        SELECT ?investorId (SUM(?signedAmount) AS ?netCashFlow)
        WHERE {
          ?cashFlow wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?amountStr ;
                    wm:type ?type .
          ?investor wm:investorId ?investorId .
          BIND(xsd:decimal(?amountStr) AS ?amount)
          # Inflows (SIP, Lump Sum, Deposit) are negative for XIRR, but for net cash flow we treat inflows as positive contributions
          # Assuming positive amount means inflow, negative means outflow
          BIND(IF(?type IN ("SIP", "Lump Sum", "Deposit"), ?amount, -1 * ?amount) AS ?signedAmount)
        }
        GROUP BY ?investorId
      }
      {
        # Total holding gain per investor (only holdings with cost and current value)
        SELECT ?investorId (SUM(?gain) AS ?totalGain)
        WHERE {
          ?holding wm:heldByInvestor ?investor ;
                   wm:cost ?costStr ;
                   wm:currentValue ?currentValueStr .
          ?investor wm:investorId ?investorId .
          FILTER(xsd:decimal(?costStr) > 0)
          BIND(xsd:decimal(?currentValueStr) - xsd:decimal(?costStr) AS ?gain)
        }
        GROUP BY ?investorId
      }
      {
        # Risk score per investor
        SELECT ?investorId (AVG(xsd:decimal(?riskScoreStr)) AS ?riskScore)
        WHERE {
          ?health wm:healthOfInvestor ?investor ;
                  wm:riskScore ?riskScoreStr .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }

      # Ensure investor has all three components
      BIND(?netCashFlow AS ?cashFlowComponent)
      BIND(?totalGain AS ?gainComponent)
      BIND(?riskScore AS ?riskComponent)

      # Min-max normalisation across the filtered set of investors
      {
        SELECT (MIN(?cashFlowComponent) AS ?minCashFlow)
               (MAX(?cashFlowComponent) AS ?maxCashFlow)
               (MIN(?gainComponent) AS ?minGain)
               (MAX(?gainComponent) AS ?maxGain)
               (MIN(?riskComponent) AS ?minRisk)
               (MAX(?riskComponent) AS ?maxRisk)
        WHERE {
          # Subquery to get all investors with all three components
          {
            SELECT ?investorId ?netCashFlow ?totalGain ?riskScore
            WHERE {
              # Net cash flow
              {
                SELECT ?investorId (SUM(?signedAmount) AS ?netCashFlow)
                WHERE {
                  ?cashFlow wm:cashFlowOfInvestor ?investor ;
                            wm:amount ?amountStr ;
                            wm:type ?type .
                  ?investor wm:investorId ?investorId .
                  BIND(xsd:decimal(?amountStr) AS ?amount)
                  BIND(IF(?type IN ("SIP", "Lump Sum", "Deposit"), ?amount, -1 * ?amount) AS ?signedAmount)
                }
                GROUP BY ?investorId
              }
              # Total holding gain
              {
                SELECT ?investorId (SUM(?gain) AS ?totalGain)
                WHERE {
                  ?holding wm:heldByInvestor ?investor ;
                           wm:cost ?costStr ;
                           wm:currentValue ?currentValueStr .
                  ?investor wm:investorId ?investorId .
                  FILTER(xsd:decimal(?costStr) > 0)
                  BIND(xsd:decimal(?currentValueStr) - xsd:decimal(?costStr) AS ?gain)
                }
                GROUP BY ?investorId
              }
              # Risk score
              {
                SELECT ?investorId (AVG(xsd:decimal(?riskScoreStr)) AS ?riskScore)
                WHERE {
                  ?health wm:healthOfInvestor ?investor ;
                          wm:riskScore ?riskScoreStr .
                  ?investor wm:investorId ?investorId .
                }
                GROUP BY ?investorId
              }
            }
          }
          BIND(?netCashFlow AS ?cashFlowComponent)
          BIND(?totalGain AS ?gainComponent)
          BIND(?riskScore AS ?riskComponent)
        }
      }

      # Apply min-max normalisation with protection against division by zero
      BIND(IF(?maxCashFlow - ?minCashFlow != 0, (?cashFlowComponent - ?minCashFlow) / (?maxCashFlow - ?minCashFlow), 0) AS ?normCashFlow)
      BIND(IF(?maxGain - ?minGain != 0, (?gainComponent - ?minGain) / (?maxGain - ?minGain), 0) AS ?normGain)
      BIND(IF(?maxRisk - ?minRisk != 0, (?riskComponent - ?minRisk) / (?maxRisk - ?minRisk), 0) AS ?normRisk)

      # Equal-weighted mean of normalised components
      BIND((?normCashFlow + ?normGain + ?normRisk) / 3 AS ?normalisedComponent)
    }
    GROUP BY ?investorId
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * ((?normNetCashFlow + ?normTotalSectorInvestment + ?normTotalShift) / 3) AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
        WHERE {
          ?cashFlow a wm:CashFlow ;
                    wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?cfAmount .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?saTotal)) AS ?totalSectorInvestment)
        WHERE {
          ?sectorAlloc a wm:SectorAllocation ;
                       wm:allocationOfInvestor ?investor ;
                       wm:totalInvestment ?saTotal .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?totalShift)
        WHERE {
          ?scenarioRebal a wm:ScenarioRebalancing ;
                         wm:scenarioRebalancingOfInvestor ?investor ;
                         wm:newAllocationPct ?newAlloc ;
                         wm:currentAllocationPct ?currAlloc .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }

      # Min-Max Normalization
      {
        SELECT (MIN(?netCashFlow) AS ?minCF)
               (MAX(?netCashFlow) AS ?maxCF)
               (MIN(?totalSectorInvestment) AS ?minSI)
               (MAX(?totalSectorInvestment) AS ?maxSI)
               (MIN(?totalShift) AS ?minShift)
               (MAX(?totalShift) AS ?maxShift)
        WHERE {
          {
            SELECT ?investorId
                   (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
            WHERE {
              ?cashFlow a wm:CashFlow ;
                        wm:cashFlowOfInvestor ?investor ;
                        wm:amount ?cfAmount .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId
                   (SUM(xsd:decimal(?saTotal)) AS ?totalSectorInvestment)
            WHERE {
              ?sectorAlloc a wm:SectorAllocation ;
                           wm:allocationOfInvestor ?investor ;
                           wm:totalInvestment ?saTotal .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId
                   (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?totalShift)
            WHERE {
              ?scenarioRebal a wm:ScenarioRebalancing ;
                             wm:scenarioRebalancingOfInvestor ?investor ;
                             wm:newAllocationPct ?newAlloc ;
                             wm:currentAllocationPct ?currAlloc .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
        }
      }

      BIND((?netCashFlow - ?minCF) / (?maxCF - ?minCF) AS ?normNetCashFlow)
      BIND((?totalSectorInvestment - ?minSI) / (?maxSI - ?minSI) AS ?normTotalSectorInvestment)
      BIND((?totalShift - ?minShift) / (?maxShift - ?minShift) AS ?normTotalShift)
    }
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?transactionRebalanceIndex
WHERE {
  {
    SELECT ?investorId
           (100 * AVG(?normalisedComponent) AS ?transactionRebalanceIndex)
    WHERE {
      {
        # Net cash flow component
        SELECT ?investorId
               (SUM(?cashFlowAmount) AS ?netCashFlow)
        WHERE {
          ?cashFlow wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?cashFlowAmountStr .
          ?investor wm:investorId ?investorId .
          BIND(xsd:decimal(?cashFlowAmountStr) AS ?cashFlowAmount)
        }
        GROUP BY ?investorId
      }
      {
        # Total rebalance amount component
        SELECT ?investorId
               (SUM(?rebalanceAmount) AS ?totalRebalanceAmount)
        WHERE {
          ?rebalancingAction wm:rebalancingActionOfInvestor ?investor ;
                             wm:amount ?rebalanceAmountStr .
          ?investor wm:investorId ?investorId .
          BIND(xsd:decimal(?rebalanceAmountStr) AS ?rebalanceAmount)
        }
        GROUP BY ?investorId
      }
      {
        # Total scenario allocation shift component
        SELECT ?investorId
               (SUM(?allocationShift) AS ?totalScenarioShift)
        WHERE {
          ?scenarioRebalancing wm:scenarioRebalancingOfInvestor ?investor ;
                               wm:newAllocationPct ?newAllocStr ;
                               wm:currentAllocationPct ?currentAllocStr .
          ?investor wm:investorId ?investorId .
          BIND(xsd:decimal(?newAllocStr) - xsd:decimal(?currentAllocStr) AS ?allocationShift)
        }
        GROUP BY ?investorId
      }

      # Min-max normalisation for each component
      {
        SELECT (MIN(?netCashFlow) AS ?minNetCashFlow)
               (MAX(?netCashFlow) AS ?maxNetCashFlow)
               (MIN(?totalRebalanceAmount) AS ?minRebalanceAmount)
               (MAX(?totalRebalanceAmount) AS ?maxRebalanceAmount)
               (MIN(?totalScenarioShift) AS ?minScenarioShift)
               (MAX(?totalScenarioShift) AS ?maxScenarioShift)
        WHERE {
          {
            SELECT ?investorId (SUM(?cashFlowAmount) AS ?netCashFlow)
            WHERE {
              ?cashFlow wm:cashFlowOfInvestor ?investor ;
                        wm:amount ?cashFlowAmountStr .
              ?investor wm:investorId ?investorId .
              BIND(xsd:decimal(?cashFlowAmountStr) AS ?cashFlowAmount)
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId (SUM(?rebalanceAmount) AS ?totalRebalanceAmount)
            WHERE {
              ?rebalancingAction wm:rebalancingActionOfInvestor ?investor ;
                                 wm:amount ?rebalanceAmountStr .
              ?investor wm:investorId ?investorId .
              BIND(xsd:decimal(?rebalanceAmountStr) AS ?rebalanceAmount)
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId (SUM(?allocationShift) AS ?totalScenarioShift)
            WHERE {
              ?scenarioRebalancing wm:scenarioRebalancingOfInvestor ?investor ;
                                   wm:newAllocationPct ?newAllocStr ;
                                   wm:currentAllocationPct ?currentAllocStr .
              ?investor wm:investorId ?investorId .
              BIND(xsd:decimal(?newAllocStr) - xsd:decimal(?currentAllocStr) AS ?allocationShift)
            }
            GROUP BY ?investorId
          }
        }
      }

      # Normalise each component to 0-1
      BIND((?netCashFlow - ?minNetCashFlow) / (?maxNetCashFlow - ?minNetCashFlow) AS ?normNetCashFlow)
      BIND((?totalRebalanceAmount - ?minRebalanceAmount) / (?maxRebalanceAmount - ?minRebalanceAmount) AS ?normRebalanceAmount)
      BIND((?totalScenarioShift - ?minScenarioShift) / (?maxScenarioShift - ?minScenarioShift) AS ?normScenarioShift)

      # Create array of normalised components for averaging
      BIND(?normNetCashFlow AS ?component1)
      BIND(?normRebalanceAmount AS ?component2)
      BIND(?normScenarioShift AS ?component3)
    }
    GROUP BY ?investorId
    HAVING (COUNT(?component1) = 3 && COUNT(?component2) = 3 && COUNT(?component3) = 3)
  }
}
ORDER BY DESC(?transactionRebalanceIndex) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId (100 * AVG(?normalisedComponent) AS ?compositeScore)
    WHERE {
      {
        # Net cash flow per investor
        SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
        WHERE {
          ?cashFlow wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?amount ;
                    wm:hasCashFlowType ?type .
          ?investor wm:investorId ?investorId .
          FILTER(?type IN (wm:CashFlowType_SIP, wm:CashFlowType_LumpSum, wm:CashFlowType_Deposit, wm:CashFlowType_Redemption, wm:CashFlowType_Withdrawal))
        }
        GROUP BY ?investorId
      }
      {
        # Risk score per investor
        SELECT ?investorId (xsd:decimal(?riskScoreVal) AS ?riskScore)
        WHERE {
          ?health wm:healthOfInvestor ?investor ;
                  wm:riskScore ?riskScoreVal .
          ?investor wm:investorId ?investorId .
        }
      }
      {
        # Average goal shortfall per investor
        SELECT ?investorId (AVG(xsd:decimal(?shortfallVal)) AS ?avgShortfall)
        WHERE {
          ?goal wm:belongsToInvestor ?investor ;
                wm:shortfall ?shortfallVal .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }

      # Ensure investor has all three components
      BIND(?netCashFlow AS ?cashFlowComponent)
      BIND(?riskScore AS ?riskComponent)
      BIND(?avgShortfall AS ?shortfallComponent)

      # Min-max normalisation across the filtered set
      {
        SELECT (MIN(?cashFlowComponent) AS ?minCashFlow)
               (MAX(?cashFlowComponent) AS ?maxCashFlow)
               (MIN(?riskComponent) AS ?minRisk)
               (MAX(?riskComponent) AS ?maxRisk)
               (MIN(?shortfallComponent) AS ?minShortfall)
               (MAX(?shortfallComponent) AS ?maxShortfall)
        WHERE {
          # Recompute the components here to get the min/max across the same set
          {
            SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowComponent)
            WHERE {
              ?cashFlow wm:cashFlowOfInvestor ?investor ;
                        wm:amount ?amount ;
                        wm:hasCashFlowType ?type .
              ?investor wm:investorId ?investorId .
              FILTER(?type IN (wm:CashFlowType_SIP, wm:CashFlowType_LumpSum, wm:CashFlowType_Deposit, wm:CashFlowType_Redemption, wm:CashFlowType_Withdrawal))
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId (xsd:decimal(?riskScoreVal) AS ?riskComponent)
            WHERE {
              ?health wm:healthOfInvestor ?investor ;
                      wm:riskScore ?riskScoreVal .
              ?investor wm:investorId ?investorId .
            }
          }
          {
            SELECT ?investorId (AVG(xsd:decimal(?shortfallVal)) AS ?shortfallComponent)
            WHERE {
              ?goal wm:belongsToInvestor ?investor ;
                    wm:shortfall ?shortfallVal .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
        }
      }

      # Apply min-max normalisation
      BIND((?cashFlowComponent - ?minCashFlow) / (?maxCashFlow - ?minCashFlow) AS ?normCashFlow)
      BIND((?riskComponent - ?minRisk) / (?maxRisk - ?minRisk) AS ?normRisk)
      BIND(1 - ((?shortfallComponent - ?minShortfall) / (?maxShortfall - ?minShortfall)) AS ?normShortfall)

      # Combine normalised components
      BIND(?normCashFlow AS ?normalisedComponent)
      BIND(?normRisk AS ?normalisedComponent)
      BIND(?normShortfall AS ?normalisedComponent)
    }
    GROUP BY ?investorId
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?cashFlowAmount), 2) AS ?avgCashFlowAmount)
       (ROUND(AVG(?totalHoldingValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?totalRebalanceAmount), 2) AS ?avgTotalRebalanceAmount)
       (ROUND(AVG(?totalSectorInvestment), 2) AS ?avgTotalSectorInvestment)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance/wm:rdfs:label ?riskTolerance .

  {
    SELECT ?investor (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
                     (AVG(xsd:decimal(?cfAmount)) AS ?cashFlowAmount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cfAmount .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(xsd:decimal(?holdingValue)) AS ?totalHoldingValue)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?holdingValue .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(xsd:decimal(?rebalanceAmount)) AS ?totalRebalanceAmount)
    WHERE {
      ?rebalancing a wm:RebalancingAction ;
                    wm:rebalancingActionOfInvestor ?investor ;
                    wm:amount ?rebalanceAmount .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(xsd:decimal(?sectorTotal)) AS ?totalSectorInvestment)
    WHERE {
      ?sectorAlloc a wm:SectorAllocation ;
                    wm:allocationOfInvestor ?investor ;
                    wm:totalInvestment ?sectorTotal .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?cashFlowAmount), 2) AS ?avgCashFlowAmount)
       (ROUND(AVG(?totalHoldingValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?totalRebalanceAmount), 2) AS ?avgTotalRebalanceAmount)
       (ROUND(AVG(?scenarioAllocationShift), 2) AS ?avgScenarioAllocationShift)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  # Get investor risk tolerance
  ?investor a wm:Investor ;
            wm:hasRiskTolerance/wm:rdfs:label ?riskTolerance ;
            wm:investorId ?investorId .

  # Calculate net cash flow per investor (sum of all cash flow amounts)
  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor/wm:investorId ?investorId ;
                wm:amount ?cfAmountStr .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investorId
  }

  # Calculate average cash flow amount per investor
  {
    SELECT ?investorId (AVG(xsd:decimal(?cfAmount)) AS ?cashFlowAmount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor/wm:investorId ?investorId ;
                wm:amount ?cfAmountStr .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investorId
  }

  # Calculate total holding value per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?holdingValue)) AS ?totalHoldingValue)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor/wm:investorId ?investorId ;
               wm:currentValue ?holdingValueStr .
      BIND(xsd:decimal(?holdingValueStr) AS ?holdingValue)
    }
    GROUP BY ?investorId
  }

  # Calculate total rebalance amount per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?rebalanceAmount)) AS ?totalRebalanceAmount)
    WHERE {
      ?rebalancing a wm:RebalancingAction ;
                   wm:rebalancingActionOfInvestor/wm:investorId ?investorId ;
                   wm:amount ?rebalanceAmountStr .
      BIND(xsd:decimal(?rebalanceAmountStr) AS ?rebalanceAmount)
    }
    GROUP BY ?investorId
  }

  # Calculate scenario allocation shift per investor (new minus current allocation %)
  {
    SELECT ?investorId (AVG(xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc)) AS ?scenarioAllocationShift)
    WHERE {
      ?scenario a wm:ScenarioRebalancing ;
                wm:scenarioRebalancingOfInvestor/wm:investorId ?investorId ;
                wm:newAllocationPct ?newAllocStr ;
                wm:currentAllocationPct ?currentAllocStr .
      BIND(xsd:decimal(?newAllocStr) AS ?newAlloc)
      BIND(xsd:decimal(?currentAllocStr) AS ?currentAlloc)
    }
    GROUP BY ?investorId
  }

  # Join all per-investor calculations
  BIND(?investorId AS ?invId)
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?cashFlowAmount), 2) AS ?avgCashFlowAmount)
       (ROUND(AVG(?totalHoldingValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?totalSectorInvestment), 2) AS ?avgTotalSectorInvestment)
       (ROUND(AVG(?riskScore), 2) AS ?avgRiskScore)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?cashFlowAmountSigned)) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amountStr .
      BIND(xsd:decimal(?amountStr) AS ?cashFlowAmountSigned)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(ABS(xsd:decimal(?amountStr))) AS ?cashFlowAmount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amountStr .
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?currentValueStr)) AS ?totalHoldingValue)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?currentValueStr .
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?totalInvestmentStr)) AS ?totalSectorInvestment)
    WHERE {
      ?sectorAlloc a wm:SectorAllocation ;
                   wm:allocationOfInvestor ?investor ;
                   wm:totalInvestment ?totalInvestmentStr .
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (xsd:decimal(?riskScoreStr) AS ?riskScore)
    WHERE {
      ?health a wm:PortfolioHealth ;
              wm:healthOfInvestor ?investor ;
              wm:riskScore ?riskScoreStr .
    }
  }
  ?investor a wm:Investor ;
            wm:hasRiskTolerance/wm:label ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?cashFlowAmount), 2) AS ?avgCashFlowAmount)
       (ROUND(AVG(?totalHoldingValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?totalSectorInvestment), 2) AS ?avgTotalSectorInvestment)
       (ROUND(AVG(?scenarioAllocationShift), 2) AS ?avgScenarioAllocationShift)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cfAmountStr .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(ABS(xsd:decimal(?cfAmount))) AS ?cashFlowAmount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cfAmountStr .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?holdingValue)) AS ?totalHoldingValue)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?holdingValueStr .
      BIND(xsd:decimal(?holdingValueStr) AS ?holdingValue)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?sectorAllocTotal)) AS ?totalSectorInvestment)
    WHERE {
      ?sectorAlloc a wm:SectorAllocation ;
                   wm:allocationOfInvestor ?investor ;
                   wm:totalInvestment ?sectorAllocStr .
      BIND(xsd:decimal(?sectorAllocStr) AS ?sectorAllocTotal)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc)) AS ?scenarioAllocationShift)
    WHERE {
      ?scenarioRebal a wm:ScenarioRebalancing ;
                     wm:scenarioRebalancingOfInvestor ?investor ;
                     wm:newAllocationPct ?newAllocStr ;
                     wm:currentAllocationPct ?currentAllocStr .
      BIND(xsd:decimal(?newAllocStr) AS ?newAlloc)
      BIND(xsd:decimal(?currentAllocStr) AS ?currentAlloc)
    }
    GROUP BY ?investor
  }
  ?investor a wm:Investor ;
            wm:hasRiskTolerance/wm:rdfs:label ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?cashFlowAmount), 2) AS ?avgCashFlowAmount)
       (ROUND(AVG(?totalHoldingValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?totalRebalanceAmount), 2) AS ?avgTotalRebalanceAmount)
       (ROUND(AVG(?goalProgress), 2) AS ?avgGoalProgress)
       (COUNT(DISTINCT ?investorId) AS ?investorCount)
WHERE {
  {
    # Per-investor net cash flow (inflows negative, outflows positive)
    SELECT ?investorId (SUM(?signedAmount) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amountStr ;
                wm:type ?type .
      ?investor wm:investorId ?investorId .
      BIND(xsd:decimal(?amountStr) AS ?amount)
      BIND(IF(?type = 'SIP' || ?type = 'Lump Sum' || ?type = 'Deposit', -?amount, ?amount) AS ?signedAmount)
    }
    GROUP BY ?investorId
  }
  {
    # Per-investor average cash flow amount (absolute)
    SELECT ?investorId (AVG(?absAmount) AS ?cashFlowAmount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amountStr .
      ?investor wm:investorId ?investorId .
      BIND(ABS(xsd:decimal(?amountStr)) AS ?absAmount)
    }
    GROUP BY ?investorId
  }
  {
    # Per-investor total holding value
    SELECT ?investorId (SUM(?value) AS ?totalHoldingValue)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?valueStr .
      ?investor wm:investorId ?investorId .
      BIND(xsd:decimal(?valueStr) AS ?value)
    }
    GROUP BY ?investorId
  }
  {
    # Per-investor total rebalance amount (absolute)
    SELECT ?investorId (SUM(?rebalanceAmt) AS ?totalRebalanceAmount)
    WHERE {
      ?rebalancing a wm:RebalancingAction ;
                   wm:rebalancingActionOfInvestor ?investor ;
                   wm:amount ?amountStr .
      ?investor wm:investorId ?investorId .
      BIND(ABS(xsd:decimal(?amountStr)) AS ?rebalanceAmt)
    }
    GROUP BY ?investorId
  }
  {
    # Per-investor average goal progress
    SELECT ?investorId (AVG(?progress) AS ?goalProgress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressStr .
      ?investor wm:investorId ?investorId .
      BIND(xsd:decimal(?progressStr) AS ?progress)
    }
    GROUP BY ?investorId
  }
  # Get investor profile with risk tolerance
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasRiskTolerance ?riskToleranceNode .
  ?riskToleranceNode rdfs:label ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?cashFlowAmount), 2) AS ?avgCashFlowAmount)
       (ROUND(AVG(?totalHoldingValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?allocationShift), 2) AS ?avgScenarioAllocationShift)
       (ROUND(AVG(?riskScore), 2) AS ?avgRiskScore)
WHERE {
  {
    SELECT ?investor ?riskTolerance (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
    WHERE {
      ?investor a wm:Investor ;
                 wm:hasRiskTolerance ?riskToleranceObj .
      ?riskToleranceObj rdfs:label ?riskTolerance .
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cfAmountStr .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investor ?riskTolerance
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?cfAmount)) AS ?cashFlowAmount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cfAmountStr .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?holdingValue)) AS ?totalHoldingValue)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?holdingValueStr .
      BIND(xsd:decimal(?holdingValueStr) AS ?holdingValue)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc)) AS ?allocationShift)
    WHERE {
      ?scenarioRebalancing a wm:ScenarioRebalancing ;
                           wm:scenarioRebalancingOfInvestor ?investor ;
                           wm:currentAllocationPct ?currentAllocStr ;
                           wm:newAllocationPct ?newAllocStr .
      BIND(xsd:decimal(?currentAllocStr) AS ?currentAlloc)
      BIND(xsd:decimal(?newAllocStr) AS ?newAlloc)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?riskScoreVal)) AS ?riskScore)
    WHERE {
      ?portfolioHealth a wm:PortfolioHealth ;
                       wm:healthOfInvestor ?investor ;
                       wm:riskScore ?riskScoreStr .
      BIND(xsd:decimal(?riskScoreStr) AS ?riskScoreVal)
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

