PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskToleranceLabel
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?avgCashFlowAmount), 2) AS ?avgCashFlowAmount)
       (ROUND(AVG(?totalRebalanceAmount), 2) AS ?avgTotalRebalanceAmount)
       (ROUND(AVG(?totalSectorInvestment), 2) AS ?avgTotalSectorInvestment)
       (ROUND(AVG(?riskScore), 2) AS ?avgRiskScore)
       (COUNT(DISTINCT ?investorId) AS ?investorCount)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cashFlowAmountStr .
      BIND(xsd:decimal(?cashFlowAmountStr) AS ?cashFlowAmount)
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?cashFlowAmount)) AS ?avgCashFlowAmount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cashFlowAmountStr .
      BIND(xsd:decimal(?cashFlowAmountStr) AS ?cashFlowAmount)
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?rebalanceAmount)) AS ?totalRebalanceAmount)
    WHERE {
      ?rebalancing a wm:RebalancingAction ;
                   wm:rebalancingActionOfInvestor ?investor ;
                   wm:amount ?rebalanceAmountStr .
      BIND(xsd:decimal(?rebalanceAmountStr) AS ?rebalanceAmount)
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?sectorTotalInvestment)) AS ?totalSectorInvestment)
    WHERE {
      ?sectorAlloc a wm:SectorAllocation ;
                   wm:allocationOfInvestor ?investor ;
                   wm:totalInvestment ?sectorTotalInvestmentStr .
      BIND(xsd:decimal(?sectorTotalInvestmentStr) AS ?sectorTotalInvestment)
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (xsd:decimal(?riskScoreVal) AS ?riskScore)
    WHERE {
      ?portfolioHealth a wm:PortfolioHealth ;
                       wm:healthOfInvestor ?investor ;
                       wm:riskScore ?riskScoreVal .
    }
  }

  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasRiskTolerance ?riskTolerance .
  ?riskTolerance rdfs:label ?riskToleranceLabel .
}
GROUP BY ?riskToleranceLabel
ORDER BY ?riskToleranceLabel

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?cashFlowAmount), 2) AS ?avgCashFlowAmount)
       (ROUND(AVG(?totalHoldingValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?totalSectorInvestment), 2) AS ?avgTotalSectorInvestment)
       (ROUND(AVG(?goalProgress), 2) AS ?avgGoalProgress)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?cashFlowAmountSigned)) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amountRaw .
      BIND(xsd:decimal(?amountRaw) AS ?cashFlowAmountSigned)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(ABS(xsd:decimal(?cashFlowAmount))) AS ?cashFlowAmount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cashFlowAmount .
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?currentValue)) AS ?totalHoldingValue)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?currentValue .
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?totalInvestment)) AS ?totalSectorInvestment)
    WHERE {
      ?sectorAlloc a wm:SectorAllocation ;
                   wm:allocationOfInvestor ?investor ;
                   wm:totalInvestment ?totalInvestment .
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?goalProgress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?investor
  }
  ?investor a wm:Investor ;
            wm:hasRiskTolerance/wm:riskTolerance ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
    {
        SELECT ?investorId
               ((SUM(?netCashFlow) + SUM(?totalHoldingGain) + SUM(?totalRebalanceAmount) + SUM(?totalSectorInvestment)) AS ?compositeScore)
        WHERE {
            # Net Cash Flow per Investor
            {
                SELECT ?investorId (SUM(?cashAmount) AS ?netCashFlow)
                WHERE {
                    ?cashFlow a wm:CashFlow ;
                              wm:cashFlowOfInvestor ?investor ;
                              wm:amount ?cashAmount .
                    ?investor wm:investorId ?investorId .
                }
                GROUP BY ?investorId
            }
            # Total Holding Gain per Investor (only holdings with cost and current value)
            {
                SELECT ?investorId (SUM((?currentValue - ?cost)) AS ?totalHoldingGain)
                WHERE {
                    ?holding a wm:PortfolioHolding ;
                             wm:heldByInvestor ?investor ;
                             wm:cost ?cost ;
                             wm:currentValue ?currentValue .
                    ?investor wm:investorId ?investorId .
                    FILTER(?cost > 0)
                }
                GROUP BY ?investorId
            }
            # Total Rebalance Amount per Investor
            {
                SELECT ?investorId (SUM(?rebalanceAmount) AS ?totalRebalanceAmount)
                WHERE {
                    ?rebalancing a wm:RebalancingAction ;
                                 wm:rebalancingActionOfInvestor ?investor ;
                                 wm:amount ?rebalanceAmount .
                    ?investor wm:investorId ?investorId .
                }
                GROUP BY ?investorId
            }
            # Total Sector Investment per Investor
            {
                SELECT ?investorId (SUM(?sectorTotalInvestment) AS ?totalSectorInvestment)
                WHERE {
                    ?sectorAlloc a wm:SectorAllocation ;
                                 wm:allocationOfInvestor ?investor ;
                                 wm:totalInvestment ?sectorTotalInvestment .
                    ?investor wm:investorId ?investorId .
                }
                GROUP BY ?investorId
            }
        }
        GROUP BY ?investorId
        HAVING (COUNT(?netCashFlow) = 1 && COUNT(?totalHoldingGain) = 1 && COUNT(?totalRebalanceAmount) = 1 && COUNT(?totalSectorInvestment) = 1)
    }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
          ((SUM(?cashFlowAmount) + SUM(?holdingGain) + SUM(?rebalanceAmount) - AVG(?goalShortfall)) AS ?compositeScore)
    WHERE {
      # Investors with cash flows
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cashFlowAmount .
      ?investor wm:investorId ?investorId .

      # Investors with holdings (cost and current value recorded)
      ?holding wm:heldByInvestor ?investor ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue .
      BIND((?currentValue - ?cost) AS ?holdingGain)

      # Investors with rebalancing actions
      ?rebalancing wm:rebalancingActionOfInvestor ?investor ;
                   wm:amount ?rebalanceAmount .

      # Investors with investment goals
      ?goal wm:belongsToInvestor ?investor ;
            wm:shortfall ?goalShortfall .
    }
    GROUP BY ?investorId
    HAVING (COUNT(?cashFlow) > 0 && COUNT(?holding) > 0 && COUNT(?rebalancing) > 0 && COUNT(?goal) > 0)
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * ((?normNetCashFlow + ?normTotalGain + ?normTotalRebalance + ?normRiskScore) / 4) AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               (SUM(COALESCE(?cashFlowAmount, 0)) AS ?netCashFlow)
        WHERE {
          ?cashFlow a wm:CashFlow ;
                    wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?cashFlowAmountStr .
          ?investor wm:investorId ?investorId .
          BIND(xsd:decimal(?cashFlowAmountStr) AS ?cashFlowAmount)
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(?holdingGain) AS ?totalGain)
        WHERE {
          ?holding a wm:PortfolioHolding ;
                   wm:heldByInvestor ?investor ;
                   wm:cost ?costStr ;
                   wm:currentValue ?currentValueStr .
          ?investor wm:investorId ?investorId .
          FILTER(xsd:decimal(?costStr) > 0)
          BIND(xsd:decimal(?currentValueStr) - xsd:decimal(?costStr) AS ?holdingGain)
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(ABS(xsd:decimal(?rebalanceAmountStr))) AS ?totalRebalance)
        WHERE {
          ?rebalance a wm:RebalancingAction ;
                     wm:rebalancingActionOfInvestor ?investor ;
                     wm:amount ?rebalanceAmountStr .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (AVG(xsd:decimal(?riskScoreStr)) AS ?riskScore)
        WHERE {
          ?health a wm:PortfolioHealth ;
                  wm:healthOfInvestor ?investor ;
                  wm:riskScore ?riskScoreStr .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      BIND((?netCashFlow - ?minNetCashFlow) / (?maxNetCashFlow - ?minNetCashFlow) AS ?normNetCashFlow)
      BIND((?totalGain - ?minTotalGain) / (?maxTotalGain - ?minTotalGain) AS ?normTotalGain)
      BIND((?totalRebalance - ?minTotalRebalance) / (?maxTotalRebalance - ?minTotalRebalance) AS ?normTotalRebalance)
      BIND((?riskScore - ?minRiskScore) / (?maxRiskScore - ?minRiskScore) AS ?normRiskScore)
      {
        SELECT (MIN(?netCashFlow) AS ?minNetCashFlow)
               (MAX(?netCashFlow) AS ?maxNetCashFlow)
               (MIN(?totalGain) AS ?minTotalGain)
               (MAX(?totalGain) AS ?maxTotalGain)
               (MIN(?totalRebalance) AS ?minTotalRebalance)
               (MAX(?totalRebalance) AS ?maxTotalRebalance)
               (MIN(?riskScore) AS ?minRiskScore)
               (MAX(?riskScore) AS ?maxRiskScore)
        WHERE {
          {
            SELECT ?investorId
                   (SUM(COALESCE(?cashFlowAmount, 0)) AS ?netCashFlow)
            WHERE {
              ?cashFlow a wm:CashFlow ;
                        wm:cashFlowOfInvestor ?investor ;
                        wm:amount ?cashFlowAmountStr .
              ?investor wm:investorId ?investorId .
              BIND(xsd:decimal(?cashFlowAmountStr) AS ?cashFlowAmount)
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId
                   (SUM(?holdingGain) AS ?totalGain)
            WHERE {
              ?holding a wm:PortfolioHolding ;
                       wm:heldByInvestor ?investor ;
                       wm:cost ?costStr ;
                       wm:currentValue ?currentValueStr .
              ?investor wm:investorId ?investorId .
              FILTER(xsd:decimal(?costStr) > 0)
              BIND(xsd:decimal(?currentValueStr) - xsd:decimal(?costStr) AS ?holdingGain)
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId
                   (SUM(ABS(xsd:decimal(?rebalanceAmountStr))) AS ?totalRebalance)
            WHERE {
              ?rebalance a wm:RebalancingAction ;
                         wm:rebalancingActionOfInvestor ?investor ;
                         wm:amount ?rebalanceAmountStr .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId
                   (AVG(xsd:decimal(?riskScoreStr)) AS ?riskScore)
            WHERE {
              ?health a wm:PortfolioHealth ;
                      wm:healthOfInvestor ?investor ;
                      wm:riskScore ?riskScoreStr .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
        }
      }
    }
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * ((?normNetCashFlow + ?normTotalGain + ?normTotalRebalance + ?normTotalShift) / 4) AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
        WHERE {
          ?cashFlow a wm:CashFlow ;
                    wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?cashFlowAmount .
          ?investor wm:investorId ?investorId .
          FILTER(xsd:decimal(?cashFlowAmount) != 0)
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?gain)) AS ?totalGain)
        WHERE {
          ?holding a wm:PortfolioHolding ;
                   wm:heldByInvestor ?investor ;
                   wm:cost ?cost ;
                   wm:currentValue ?currentValue .
          ?investor wm:investorId ?investorId .
          FILTER(xsd:decimal(?cost) > 0 && xsd:decimal(?currentValue) >= 0)
          BIND((xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?gain)
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(ABS(xsd:decimal(?rebalanceAmount))) AS ?totalRebalance)
        WHERE {
          ?rebalancing a wm:RebalancingAction ;
                       wm:rebalancingActionOfInvestor ?investor ;
                       wm:amount ?rebalanceAmount .
          ?investor wm:investorId ?investorId .
          FILTER(xsd:decimal(?rebalanceAmount) != 0)
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(ABS(xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc))) AS ?totalShift)
        WHERE {
          ?scenario a wm:ScenarioRebalancing ;
                    wm:scenarioRebalancingOfInvestor ?investor ;
                    wm:currentAllocationPct ?currentAlloc ;
                    wm:newAllocationPct ?newAlloc .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      BIND(?netCashFlow AS ?rawNetCashFlow)
      BIND(?totalGain AS ?rawTotalGain)
      BIND(?totalRebalance AS ?rawTotalRebalance)
      BIND(?totalShift AS ?rawTotalShift)
    }
    GROUP BY ?investorId ?rawNetCashFlow ?rawTotalGain ?rawTotalRebalance ?rawTotalShift
    HAVING (COUNT(DISTINCT ?rawNetCashFlow) = 1 &&
            COUNT(DISTINCT ?rawTotalGain) = 1 &&
            COUNT(DISTINCT ?rawTotalRebalance) = 1 &&
            COUNT(DISTINCT ?rawTotalShift) = 1)
  }
  {
    SELECT (MIN(?rawNetCashFlow) AS ?minNetCashFlow)
           (MAX(?rawNetCashFlow) AS ?maxNetCashFlow)
           (MIN(?rawTotalGain) AS ?minTotalGain)
           (MAX(?rawTotalGain) AS ?maxTotalGain)
           (MIN(?rawTotalRebalance) AS ?minTotalRebalance)
           (MAX(?rawTotalRebalance) AS ?maxTotalRebalance)
           (MIN(?rawTotalShift) AS ?minTotalShift)
           (MAX(?rawTotalShift) AS ?maxTotalShift)
    WHERE {
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?cashFlowAmount)) AS ?rawNetCashFlow)
        WHERE {
          ?cashFlow a wm:CashFlow ;
                    wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?cashFlowAmount .
          ?investor wm:investorId ?investorId .
          FILTER(xsd:decimal(?cashFlowAmount) != 0)
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?gain)) AS ?rawTotalGain)
        WHERE {
          ?holding a wm:PortfolioHolding ;
                   wm:heldByInvestor ?investor ;
                   wm:cost ?cost ;
                   wm:currentValue ?currentValue .
          ?investor wm:investorId ?investorId .
          FILTER(xsd:decimal(?cost) > 0 && xsd:decimal(?currentValue) >= 0)
          BIND((xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?gain)
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(ABS(xsd:decimal(?rebalanceAmount))) AS ?rawTotalRebalance)
        WHERE {
          ?rebalancing a wm:RebalancingAction ;
                       wm:rebalancingActionOfInvestor ?investor ;
                       wm:amount ?rebalanceAmount .
          ?investor wm:investorId ?investorId .
          FILTER(xsd:decimal(?rebalanceAmount) != 0)
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(ABS(xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc))) AS ?rawTotalShift)
        WHERE {
          ?scenario a wm:ScenarioRebalancing ;
                    wm:scenarioRebalancingOfInvestor ?investor ;
                    wm:currentAllocationPct ?currentAlloc ;
                    wm:newAllocationPct ?newAlloc .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
    }
    GROUP BY ?investorId
    HAVING (COUNT(DISTINCT ?rawNetCashFlow) = 1 &&
            COUNT(DISTINCT ?rawTotalGain) = 1 &&
            COUNT(DISTINCT ?rawTotalRebalance) = 1 &&
            COUNT(DISTINCT ?rawTotalShift) = 1)
  }
  BIND((?rawNetCashFlow - ?minNetCashFlow) / (?maxNetCashFlow - ?minNetCashFlow) AS ?normNetCashFlow)
  BIND((?rawTotalGain - ?minTotalGain) / (?maxTotalGain - ?minTotalGain) AS ?normTotalGain)
  BIND((?rawTotalRebalance - ?minTotalRebalance) / (?maxTotalRebalance - ?minTotalRebalance) AS ?normTotalRebalance)
  BIND((?rawTotalShift - ?minTotalShift) / (?maxTotalShift - ?minTotalShift) AS ?normTotalShift)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           ((SUM(?cashFlowAmount) + SUM(?holdingGain) + SUM(?sectorInvestment) - AVG(?goalShortfall)) AS ?compositeScore)
    WHERE {
      # Investors with every component recorded
      ?investor wm:investorId ?investorId ;
                wm:hasCashFlow ?cashFlow ;
                wm:hasHolding ?holding ;
                wm:hasSectorAllocation ?sectorAllocation ;
                wm:hasInvestmentGoal ?goal .

      # Net cash flow
      ?cashFlow wm:amount ?cashFlowAmount .

      # Total holding gain (only holdings with recorded cost and current value)
      ?holding wm:cost ?cost ;
               wm:currentValue ?currentValue .
      FILTER(?cost != "" && ?currentValue != "")
      BIND((?currentValue - ?cost) AS ?holdingGain)

      # Total sector investment
      ?sectorAllocation wm:totalInvestment ?sectorInvestment .

      # Average goal shortfall
      ?goal wm:shortfall ?goalShortfall .
    }
    GROUP BY ?investorId
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?cashFlowAmount), 2) AS ?avgCashFlowAmount)
       (ROUND(AVG(?totalHoldingValue), 2) AS ?avgTotalHoldingValue)
       (ROUND(AVG(?riskScore), 2) AS ?avgRiskScore)
       (ROUND(AVG(?goalProgress), 2) AS ?avgGoalProgress)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)

WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cfAmountStr .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?cfAmount)) AS ?cashFlowAmount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cfAmountStr .
      BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?holdingValue)) AS ?totalHoldingValue)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?valueStr .
      BIND(xsd:decimal(?valueStr) AS ?holdingValue)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?riskScoreVal)) AS ?riskScore)
    WHERE {
      ?health a wm:PortfolioHealth ;
              wm:healthOfInvestor ?investor ;
              wm:riskScore ?riskScoreStr .
      BIND(xsd:decimal(?riskScoreStr) AS ?riskScoreVal)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?progressVal)) AS ?goalProgress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressStr .
      BIND(xsd:decimal(?progressStr) AS ?progressVal)
    }
    GROUP BY ?investor
  }

  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskToleranceObj .
  ?riskToleranceObj rdfs:label ?riskTolerance .
}

GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance
       (ROUND(AVG(?netCashFlow), 2) AS ?avgNetCashFlow)
       (ROUND(AVG(?avgCashFlowAmount), 2) AS ?avgCashFlowAmount)
       (ROUND(AVG(?totalRebalanceAmount), 2) AS ?avgTotalRebalanceAmount)
       (ROUND(AVG(?totalSectorInvestment), 2) AS ?avgTotalSectorInvestment)
       (ROUND(AVG(?avgGoalProgress), 2) AS ?avgGoalProgress)
       (COUNT(DISTINCT ?investor) AS ?nInvestors)
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cashFlowAmountStr .
      BIND(xsd:decimal(?cashFlowAmountStr) AS ?cashFlowAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?cashFlowAmount)) AS ?avgCashFlowAmount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cashFlowAmountStr .
      BIND(xsd:decimal(?cashFlowAmountStr) AS ?cashFlowAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?rebalanceAmount)) AS ?totalRebalanceAmount)
    WHERE {
      ?rebalancing a wm:RebalancingAction ;
                   wm:rebalancingActionOfInvestor ?investor ;
                   wm:amount ?rebalanceAmountStr .
      BIND(xsd:decimal(?rebalanceAmountStr) AS ?rebalanceAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?sectorTotalInvestment)) AS ?totalSectorInvestment)
    WHERE {
      ?sectorAlloc a wm:SectorAllocation ;
                   wm:allocationOfInvestor ?investor ;
                   wm:totalInvestment ?sectorTotalInvestmentStr .
      BIND(xsd:decimal(?sectorTotalInvestmentStr) AS ?sectorTotalInvestment)
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?goalProgress)) AS ?avgGoalProgress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?goalProgressStr .
      BIND(xsd:decimal(?goalProgressStr) AS ?goalProgress)
    }
    GROUP BY ?investor
  }
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskToleranceObj .
  ?riskToleranceObj rdfs:label ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * ((?normNetCashFlow + ?normTotalGain + ?normTotalSectorInvestment + ?normRiskScore) / 4) AS ?compositeScore)
    WHERE {
      # Net cash flow per investor (inflows negative, outflows positive)
      {
        SELECT ?investorId (SUM(?adjAmount) AS ?netCashFlow)
        WHERE {
          ?cashFlow a wm:CashFlow ;
                    wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?amountStr ;
                    wm:type ?type .
          ?investor wm:investorId ?investorId .
          BIND(xsd:decimal(?amountStr) AS ?amount)
          BIND(IF(?type IN ("SIP", "Lump Sum", "Deposit"), -?amount, ?amount) AS ?adjAmount)
        }
        GROUP BY ?investorId
      }

      # Total holding gain per investor (only holdings with cost and current value)
      {
        SELECT ?investorId (SUM(?gain) AS ?totalGain)
        WHERE {
          ?holding a wm:PortfolioHolding ;
                   wm:heldByInvestor ?investor ;
                   wm:cost ?costStr ;
                   wm:currentValue ?valueStr .
          ?investor wm:investorId ?investorId .
          BIND(xsd:decimal(?costStr) AS ?cost)
          BIND(xsd:decimal(?valueStr) AS ?value)
          FILTER(?cost > 0)
          BIND(?value - ?cost AS ?gain)
        }
        GROUP BY ?investorId
      }

      # Total sector investment per investor
      {
        SELECT ?investorId (SUM(?totalInvestment) AS ?totalSectorInvestment)
        WHERE {
          ?sectorAlloc a wm:SectorAllocation ;
                        wm:allocationOfInvestor ?investor ;
                        wm:totalInvestment ?totalInvestmentStr .
          ?investor wm:investorId ?investorId .
          BIND(xsd:decimal(?totalInvestmentStr) AS ?totalInvestment)
        }
        GROUP BY ?investorId
      }

      # Risk score per investor
      {
        SELECT ?investorId (AVG(?riskScore) AS ?riskScore)
        WHERE {
          ?health a wm:PortfolioHealth ;
                  wm:healthOfInvestor ?investor ;
                  wm:riskScore ?riskScoreStr .
          ?investor wm:investorId ?investorId .
          BIND(xsd:decimal(?riskScoreStr) AS ?riskScore)
        }
        GROUP BY ?investorId
      }

      # Min-max normalization for each component
      BIND((?netCashFlow - ?minNetCashFlow) / (?maxNetCashFlow - ?minNetCashFlow) AS ?normNetCashFlow)
      BIND((?totalGain - ?minTotalGain) / (?maxTotalGain - ?minTotalGain) AS ?normTotalGain)
      BIND((?totalSectorInvestment - ?minTotalSectorInvestment) / (?maxTotalSectorInvestment - ?minTotalSectorInvestment) AS ?normTotalSectorInvestment)
      BIND((?riskScore - ?minRiskScore) / (?maxRiskScore - ?minRiskScore) AS ?normRiskScore)

      # Get min and max values for normalization
      {
        SELECT (MIN(?netCashFlow) AS ?minNetCashFlow)
               (MAX(?netCashFlow) AS ?maxNetCashFlow)
               (MIN(?totalGain) AS ?minTotalGain)
               (MAX(?totalGain) AS ?maxTotalGain)
               (MIN(?totalSectorInvestment) AS ?minTotalSectorInvestment)
               (MAX(?totalSectorInvestment) AS ?maxTotalSectorInvestment)
               (MIN(?riskScore) AS ?minRiskScore)
               (MAX(?riskScore) AS ?maxRiskScore)
        WHERE {
          # Net cash flow
          {
            SELECT ?investorId (SUM(?adjAmount) AS ?netCashFlow)
            WHERE {
              ?cashFlow a wm:CashFlow ;
                        wm:cashFlowOfInvestor ?investor ;
                        wm:amount ?amountStr ;
                        wm:type ?type .
              ?investor wm:investorId ?investorId .
              BIND(xsd:decimal(?amountStr) AS ?amount)
              BIND(IF(?type IN ("SIP", "Lump Sum", "Deposit"), -?amount, ?amount) AS ?adjAmount)
            }
            GROUP BY ?investorId
          }

          # Total holding gain
          {
            SELECT ?investorId (SUM(?gain) AS ?totalGain)
            WHERE {
              ?holding a wm:PortfolioHolding ;
                       wm:heldByInvestor ?investor ;
                       wm:cost ?costStr ;
                       wm:currentValue ?valueStr .
              ?investor wm:investorId ?investorId .
              BIND(xsd:decimal(?costStr) AS ?cost)
              BIND(xsd:decimal(?valueStr) AS ?value)
              FILTER(?cost > 0)
              BIND(?value - ?cost AS ?gain)
            }
            GROUP BY ?investorId
          }

          # Total sector investment
          {
            SELECT ?investorId (SUM(?totalInvestment) AS ?totalSectorInvestment)
            WHERE {
              ?sectorAlloc a wm:SectorAllocation ;
                            wm:allocationOfInvestor ?investor ;
                            wm:totalInvestment ?totalInvestmentStr .
              ?investor wm:investorId ?investorId .
              BIND(xsd:decimal(?totalInvestmentStr) AS ?totalInvestment)
            }
            GROUP BY ?investorId
          }

          # Risk score
          {
            SELECT ?investorId (AVG(?riskScore) AS ?riskScore)
            WHERE {
              ?health a wm:PortfolioHealth ;
                      wm:healthOfInvestor ?investor ;
                      wm:riskScore ?riskScoreStr .
              ?investor wm:investorId ?investorId .
              BIND(xsd:decimal(?riskScoreStr) AS ?riskScore)
            }
            GROUP BY ?investorId
          }
        }
      }
    }
    GROUP BY ?investorId ?compositeScore ?normNetCashFlow ?normTotalGain ?normTotalSectorInvestment ?normRiskScore
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * AVG(?normalisedComponent) AS ?compositeScore)
    WHERE {
      {
        # Net cash flow per investor
        SELECT ?investorId
               (SUM(?signedAmount) AS ?netCashFlow)
        WHERE {
          ?cashFlow a wm:CashFlow ;
                    wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?amountStr ;
                    wm:type ?type .
          ?investor wm:investorId ?investorId .
          BIND(xsd:decimal(?amountStr) AS ?amount)
          BIND(IF(?type = "SIP" || ?type = "Lump Sum" || ?type = "Deposit",
                  -?amount, ?amount) AS ?signedAmount)
        }
        GROUP BY ?investorId
      }
      {
        # Total holding gain per investor (only holdings with cost and current value)
        SELECT ?investorId
               (SUM(?gain) AS ?totalHoldingGain)
        WHERE {
          ?holding a wm:PortfolioHolding ;
                   wm:heldByInvestor ?investor ;
                   wm:cost ?costStr ;
                   wm:currentValue ?valueStr .
          ?investor wm:investorId ?investorId .
          BIND(xsd:decimal(?costStr) AS ?cost)
          BIND(xsd:decimal(?valueStr) AS ?value)
          FILTER(?cost > 0)
          BIND(?value - ?cost AS ?gain)
        }
        GROUP BY ?investorId
      }
      {
        # Total sector investment per investor
        SELECT ?investorId
               (SUM(?totalInvestment) AS ?totalSectorInvestment)
        WHERE {
          ?sectorAlloc a wm:SectorAllocation ;
                       wm:allocationOfInvestor ?investor ;
                       wm:totalInvestment ?invStr .
          ?investor wm:investorId ?investorId .
          BIND(xsd:decimal(?invStr) AS ?totalInvestment)
        }
        GROUP BY ?investorId
      }
      {
        # Total scenario allocation shift per investor
        SELECT ?investorId
               (SUM(?shift) AS ?totalScenarioShift)
        WHERE {
          ?scenarioRebal a wm:ScenarioRebalancing ;
                         wm:scenarioRebalancingOfInvestor ?investor ;
                         wm:newAllocationPct ?newStr ;
                         wm:currentAllocationPct ?currentStr .
          ?investor wm:investorId ?investorId .
          BIND(xsd:decimal(?newStr) AS ?new)
          BIND(xsd:decimal(?currentStr) AS ?current)
          BIND(?new - ?current AS ?shift)
        }
        GROUP BY ?investorId
      }

      # Ensure investor has all 4 components
      FILTER(BOUND(?netCashFlow) && BOUND(?totalHoldingGain) &&
             BOUND(?totalSectorInvestment) && BOUND(?totalScenarioShift))

      # Min-max normalisation per component across the filtered set
      {
        SELECT (MIN(?netCashFlow) AS ?minNetCashFlow)
               (MAX(?netCashFlow) AS ?maxNetCashFlow)
               (MIN(?totalHoldingGain) AS ?minGain)
               (MAX(?totalHoldingGain) AS ?maxGain)
               (MIN(?totalSectorInvestment) AS ?minSectorInv)
               (MAX(?totalSectorInvestment) AS ?maxSectorInv)
               (MIN(?totalScenarioShift) AS ?minShift)
               (MAX(?totalScenarioShift) AS ?maxShift)
        WHERE {
          {
            SELECT ?investorId
                   (SUM(?signedAmount) AS ?netCashFlow)
            WHERE {
              ?cashFlow a wm:CashFlow ;
                        wm:cashFlowOfInvestor ?investor ;
                        wm:amount ?amountStr ;
                        wm:type ?type .
              ?investor wm:investorId ?investorId .
              BIND(xsd:decimal(?amountStr) AS ?amount)
              BIND(IF(?type = "SIP" || ?type = "Lump Sum" || ?type = "Deposit",
                      -?amount, ?amount) AS ?signedAmount)
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId
                   (SUM(?gain) AS ?totalHoldingGain)
            WHERE {
              ?holding a wm:PortfolioHolding ;
                       wm:heldByInvestor ?investor ;
                       wm:cost ?costStr ;
                       wm:currentValue ?valueStr .
              ?investor wm:investorId ?investorId .
              BIND(xsd:decimal(?costStr) AS ?cost)
              BIND(xsd:decimal(?valueStr) AS ?value)
              FILTER(?cost > 0)
              BIND(?value - ?cost AS ?gain)
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId
                   (SUM(?totalInvestment) AS ?totalSectorInvestment)
            WHERE {
              ?sectorAlloc a wm:SectorAllocation ;
                           wm:allocationOfInvestor ?investor ;
                           wm:totalInvestment ?invStr .
              ?investor wm:investorId ?investorId .
              BIND(xsd:decimal(?invStr) AS ?totalInvestment)
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId
                   (SUM(?shift) AS ?totalScenarioShift)
            WHERE {
              ?scenarioRebal a wm:ScenarioRebalancing ;
                             wm:scenarioRebalancingOfInvestor ?investor ;
                             wm:newAllocationPct ?newStr ;
                             wm:currentAllocationPct ?currentStr .
              ?investor wm:investorId ?investorId .
              BIND(xsd:decimal(?newStr) AS ?new)
              BIND(xsd:decimal(?currentStr) AS ?current)
              BIND(?new - ?current AS ?shift)
            }
            GROUP BY ?investorId
          }
          FILTER(BOUND(?netCashFlow) && BOUND(?totalHoldingGain) &&
                 BOUND(?totalSectorInvestment) && BOUND(?totalScenarioShift))
        }
      }

      # Normalise each component
      BIND((?netCashFlow - ?minNetCashFlow) /
           (?maxNetCashFlow - ?minNetCashFlow) AS ?normNetCashFlow)
      BIND((?totalHoldingGain - ?minGain) /
           (?maxGain - ?minGain) AS ?normGain)
      BIND((?totalSectorInvestment - ?minSectorInv) /
           (?maxSectorInv - ?minSectorInv) AS ?normSectorInv)
      BIND((?totalScenarioShift - ?minShift) /
           (?maxShift - ?minShift) AS ?normShift)

      # Equal-weighted mean of normalised components
      BIND((?normNetCashFlow + ?normGain + ?normSectorInv + ?normShift) / 4 AS ?normalisedComponent)
    }
    GROUP BY ?investorId
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?investorName ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
           (SUM(xsd:decimal(?rebalanceAmount)) AS ?totalRebalanceAmount)
           (SUM(xsd:decimal(?sectorTotalInvestment)) AS ?totalSectorInvestment)
           (AVG(xsd:decimal(?goalShortfall)) AS ?avgGoalShortfall)
    WHERE {
      # Cash flows for the investor
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cashFlowAmount .
      ?investor wm:investorId ?investorId .

      # Rebalancing actions for the investor
      ?rebalancing a wm:RebalancingAction ;
                   wm:rebalancingActionOfInvestor ?investor ;
                   wm:amount ?rebalanceAmount .

      # Sector allocations for the investor
      ?sectorAlloc a wm:SectorAllocation ;
                   wm:allocationOfInvestor ?investor ;
                   wm:totalInvestment ?sectorTotalInvestment .

      # Investment goals for the investor
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:shortfall ?goalShortfall .
    }
    GROUP BY ?investorId
    HAVING (COUNT(DISTINCT ?cashFlow) > 0 &&
            COUNT(DISTINCT ?rebalancing) > 0 &&
            COUNT(DISTINCT ?sectorAlloc) > 0 &&
            COUNT(DISTINCT ?goal) > 0)
  }
  BIND ((?netCashFlow + ?totalRebalanceAmount + ?totalSectorInvestment - ?avgGoalShortfall) AS ?compositeScore)
  ?investor wm:investorId ?investorId ;
            wm:investorName ?investorName .
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * AVG(?normComponent) AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
        WHERE {
          ?cashFlow a wm:CashFlow ;
                    wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?cashFlowAmount .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(ABS(xsd:decimal(?rebalAmount))) AS ?totalRebalanceAmount)
        WHERE {
          ?rebal a wm:RebalancingAction ;
                 wm:rebalancingActionOfInvestor ?investor ;
                 wm:amount ?rebalAmount .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?sectorTotalInvestment)) AS ?totalSectorInvestment)
        WHERE {
          ?sectorAlloc a wm:SectorAllocation ;
                       wm:allocationOfInvestor ?investor ;
                       wm:totalInvestment ?sectorTotalInvestment .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(ABS(xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc))) AS ?totalScenarioAllocationShift)
        WHERE {
          ?scenarioRebal a wm:ScenarioRebalancing ;
                         wm:scenarioRebalancingOfInvestor ?investor ;
                         wm:currentAllocationPct ?currentAlloc ;
                         wm:newAllocationPct ?newAlloc .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }

      BIND(?netCashFlow AS ?rawCashFlow)
      BIND(?totalRebalanceAmount AS ?rawRebalance)
      BIND(?totalSectorInvestment AS ?rawSectorInvestment)
      BIND(?totalScenarioAllocationShift AS ?rawScenarioShift)

      {
        SELECT (MIN(?rawCashFlow) AS ?minCashFlow)
               (MAX(?rawCashFlow) AS ?maxCashFlow)
               (MIN(?rawRebalance) AS ?minRebalance)
               (MAX(?rawRebalance) AS ?maxRebalance)
               (MIN(?rawSectorInvestment) AS ?minSectorInvestment)
               (MAX(?rawSectorInvestment) AS ?maxSectorInvestment)
               (MIN(?rawScenarioShift) AS ?minScenarioShift)
               (MAX(?rawScenarioShift) AS ?maxScenarioShift)
        WHERE {
          {
            SELECT ?investorId
                   (SUM(xsd:decimal(?cashFlowAmount)) AS ?rawCashFlow)
                   (SUM(ABS(xsd:decimal(?rebalAmount))) AS ?rawRebalance)
                   (SUM(xsd:decimal(?sectorTotalInvestment)) AS ?rawSectorInvestment)
                   (SUM(ABS(xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc))) AS ?rawScenarioShift)
            WHERE {
              ?investor wm:investorId ?investorId .
              OPTIONAL {
                ?cashFlow a wm:CashFlow ;
                          wm:cashFlowOfInvestor ?investor ;
                          wm:amount ?cashFlowAmount .
              }
              OPTIONAL {
                ?rebal a wm:RebalancingAction ;
                       wm:rebalancingActionOfInvestor ?investor ;
                       wm:amount ?rebalAmount .
              }
              OPTIONAL {
                ?sectorAlloc a wm:SectorAllocation ;
                             wm:allocationOfInvestor ?investor ;
                             wm:totalInvestment ?sectorTotalInvestment .
              }
              OPTIONAL {
                ?scenarioRebal a wm:ScenarioRebalancing ;
                               wm:scenarioRebalancingOfInvestor ?investor ;
                               wm:currentAllocationPct ?currentAlloc ;
                               wm:newAllocationPct ?newAlloc .
              }
            }
            GROUP BY ?investorId
            HAVING (
              BOUND(?cashFlowAmount) &&
              BOUND(?rebalAmount) &&
              BOUND(?sectorTotalInvestment) &&
              BOUND(?currentAlloc) && BOUND(?newAlloc)
            )
          }
        }
      }

      FILTER(BOUND(?rawCashFlow) && BOUND(?rawRebalance) && BOUND(?rawSectorInvestment) && BOUND(?rawScenarioShift))

      BIND((?rawCashFlow - ?minCashFlow) / (?maxCashFlow - ?minCashFlow) AS ?normCashFlow)
      BIND((?rawRebalance - ?minRebalance) / (?maxRebalance - ?minRebalance) AS ?normRebalance)
      BIND((?rawSectorInvestment - ?minSectorInvestment) / (?maxSectorInvestment - ?minSectorInvestment) AS ?normSectorInvestment)
      BIND((?rawScenarioShift - ?minScenarioShift) / (?maxScenarioShift - ?minScenarioShift) AS ?normScenarioShift)

      BIND((?normCashFlow + ?normRebalance + ?normSectorInvestment + ?normScenarioShift) / 4 AS ?normComponent)
    }
    GROUP BY ?investorId
    ORDER BY DESC(?compositeScore) ?investorId
    LIMIT 10
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * (AVG(?normNetCashFlow + ?normTotalGain + ?normRiskScore + ?normShortfallPenalty)) AS ?compositeScore)
    WHERE {
      # Net Cash Flow per Investor
      {
        SELECT ?investorId (SUM(?adjAmount) AS ?netCashFlow)
        WHERE {
          ?cashFlow a wm:CashFlow ;
                    wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?amountStr ;
                    wm:type ?type .
          ?investor wm:investorId ?investorId .
          BIND(xsd:decimal(?amountStr) AS ?amount)
          BIND(IF(?type = "SIP" || ?type = "Lump Sum" || ?type = "Deposit", -1 * ?amount, ?amount) AS ?adjAmount)
        }
        GROUP BY ?investorId
      }
      # Total Holding Gain per Investor
      {
        SELECT ?investorId (SUM(?gain) AS ?totalGain)
        WHERE {
          ?holding a wm:PortfolioHolding ;
                   wm:heldByInvestor ?investor ;
                   wm:cost ?costStr ;
                   wm:currentValue ?valueStr .
          ?investor wm:investorId ?investorId .
          FILTER(xsd:decimal(?costStr) > 0)
          BIND(xsd:decimal(?valueStr) - xsd:decimal(?costStr) AS ?gain)
        }
        GROUP BY ?investorId
      }
      # Risk Score per Investor
      {
        SELECT ?investorId (AVG(xsd:decimal(?scoreStr)) AS ?riskScore)
        WHERE {
          ?health a wm:PortfolioHealth ;
                  wm:healthOfInvestor ?investor ;
                  wm:riskScore ?scoreStr .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      # Average Goal Shortfall per Investor
      {
        SELECT ?investorId (AVG(xsd:decimal(?shortfallStr)) AS ?avgShortfall)
        WHERE {
          ?goal a wm:InvestmentGoal ;
                wm:belongsToInvestor ?investor ;
                wm:shortfall ?shortfallStr .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      # Ensure investor has all 4 components
      FILTER(BOUND(?netCashFlow) && BOUND(?totalGain) && BOUND(?riskScore) && BOUND(?avgShortfall))
      # Min-Max Normalization across the filtered set
      {
        SELECT (MIN(?netCashFlow) AS ?minNetCashFlow)
               (MAX(?netCashFlow) AS ?maxNetCashFlow)
               (MIN(?totalGain) AS ?minTotalGain)
               (MAX(?totalGain) AS ?maxTotalGain)
               (MIN(?riskScore) AS ?minRiskScore)
               (MAX(?riskScore) AS ?maxRiskScore)
               (MIN(?avgShortfall) AS ?minAvgShortfall)
               (MAX(?avgShortfall) AS ?maxAvgShortfall)
        WHERE {
          # Net Cash Flow per Investor
          {
            SELECT ?investorId (SUM(?adjAmount) AS ?netCashFlow)
            WHERE {
              ?cashFlow a wm:CashFlow ;
                        wm:cashFlowOfInvestor ?investor ;
                        wm:amount ?amountStr ;
                        wm:type ?type .
              ?investor wm:investorId ?investorId .
              BIND(xsd:decimal(?amountStr) AS ?amount)
              BIND(IF(?type = "SIP" || ?type = "Lump Sum" || ?type = "Deposit", -1 * ?amount, ?amount) AS ?adjAmount)
            }
            GROUP BY ?investorId
          }
          # Total Holding Gain per Investor
          {
            SELECT ?investorId (SUM(?gain) AS ?totalGain)
            WHERE {
              ?holding a wm:PortfolioHolding ;
                       wm:heldByInvestor ?investor ;
                       wm:cost ?costStr ;
                       wm:currentValue ?valueStr .
              ?investor wm:investorId ?investorId .
              FILTER(xsd:decimal(?costStr) > 0)
              BIND(xsd:decimal(?valueStr) - xsd:decimal(?costStr) AS ?gain)
            }
            GROUP BY ?investorId
          }
          # Risk Score per Investor
          {
            SELECT ?investorId (AVG(xsd:decimal(?scoreStr)) AS ?riskScore)
            WHERE {
              ?health a wm:PortfolioHealth ;
                      wm:healthOfInvestor ?investor ;
                      wm:riskScore ?scoreStr .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
          # Average Goal Shortfall per Investor
          {
            SELECT ?investorId (AVG(xsd:decimal(?shortfallStr)) AS ?avgShortfall)
            WHERE {
              ?goal a wm:InvestmentGoal ;
                    wm:belongsToInvestor ?investor ;
                    wm:shortfall ?shortfallStr .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
          FILTER(BOUND(?netCashFlow) && BOUND(?totalGain) && BOUND(?riskScore) && BOUND(?avgShortfall))
        }
      }
      BIND((?netCashFlow - ?minNetCashFlow) / (?maxNetCashFlow - ?minNetCashFlow) AS ?normNetCashFlow)
      BIND((?totalGain - ?minTotalGain) / (?maxTotalGain - ?minTotalGain) AS ?normTotalGain)
      BIND((?riskScore - ?minRiskScore) / (?maxRiskScore - ?minRiskScore) AS ?normRiskScore)
      BIND(1 - ((?avgShortfall - ?minAvgShortfall) / (?maxAvgShortfall - ?minAvgShortfall)) AS ?normShortfallPenalty)
    }
    GROUP BY ?investorId
    ORDER BY DESC(?compositeScore) ?investorId
    LIMIT 10
  }
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * AVG(?normalisedComponent) AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               (SUM(ABS(xsd:decimal(?amount))) AS ?totalRebalanceAmount)
        WHERE {
          ?ra a wm:RebalancingAction ;
              wm:investorId ?investorId ;
              wm:amount ?amount .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
        WHERE {
          ?cf a wm:CashFlow ;
              wm:investorId ?investorId ;
              wm:amount ?amount .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?newAllocationPct) - xsd:decimal(?currentAllocationPct)) AS ?totalScenarioShift)
        WHERE {
          ?sr a wm:ScenarioRebalancing ;
              wm:investorId ?investorId ;
              wm:newAllocationPct ?newAllocationPct ;
              wm:currentAllocationPct ?currentAllocationPct .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (xsd:decimal(?riskScore) AS ?riskScore)
        WHERE {
          ?ph a wm:PortfolioHealth ;
              wm:investorId ?investorId ;
              wm:riskScore ?riskScore .
        }
      }
      # Min-Max Normalisation for each component
      {
        SELECT (MIN(?totalRebalanceAmount) AS ?minRebalance)
               (MAX(?totalRebalanceAmount) AS ?maxRebalance)
               (MIN(?netCashFlow) AS ?minCashFlow)
               (MAX(?netCashFlow) AS ?maxCashFlow)
               (MIN(?totalScenarioShift) AS ?minShift)
               (MAX(?totalScenarioShift) AS ?maxShift)
               (MIN(?riskScore) AS ?minRisk)
               (MAX(?riskScore) AS ?maxRisk)
        WHERE {
          {
            SELECT ?investorId
                   (SUM(ABS(xsd:decimal(?amount))) AS ?totalRebalanceAmount)
            WHERE {
              ?ra a wm:RebalancingAction ;
                  wm:investorId ?investorId ;
                  wm:amount ?amount .
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId
                   (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
            WHERE {
              ?cf a wm:CashFlow ;
                  wm:investorId ?investorId ;
                  wm:amount ?amount .
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId
                   (SUM(xsd:decimal(?newAllocationPct) - xsd:decimal(?currentAllocationPct)) AS ?totalScenarioShift)
            WHERE {
              ?sr a wm:ScenarioRebalancing ;
                  wm:investorId ?investorId ;
                  wm:newAllocationPct ?newAllocationPct ;
                  wm:currentAllocationPct ?currentAllocationPct .
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId
                   (xsd:decimal(?riskScore) AS ?riskScore)
            WHERE {
              ?ph a wm:PortfolioHealth ;
                  wm:investorId ?investorId ;
                  wm:riskScore ?riskScore .
            }
          }
        }
        GROUP BY ?investorId
      }
      BIND((?totalRebalanceAmount - ?minRebalance) / (?maxRebalance - ?minRebalance) AS ?normRebalance)
      BIND((?netCashFlow - ?minCashFlow) / (?maxCashFlow - ?minCashFlow) AS ?normCashFlow)
      BIND((?totalScenarioShift - ?minShift) / (?maxShift - ?minShift) AS ?normShift)
      BIND((?riskScore - ?minRisk) / (?maxRisk - ?minRisk) AS ?normRisk)
      BIND((?normRebalance + ?normCashFlow + ?normShift + ?normRisk) / 4 AS ?normalisedComponent)
    }
    GROUP BY ?investorId
    HAVING (COUNT(?normalisedComponent) = 4)
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?riskTolerance
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:riskTolerance ?riskTolerance .
  FILTER (?riskTolerance NOT IN ("Aggressive", "Conservative", "Moderate"))
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * AVG(?normalisedComponent) AS ?compositeScore)
    WHERE {
      # Subquery to compute the four components per investor
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
               (SUM(xsd:decimal(?holdingGain)) AS ?totalHoldingGain)
               (SUM(xsd:decimal(?allocationShift)) AS ?totalAllocationShift)
               (AVG(xsd:decimal(?goalShortfall)) AS ?avgGoalShortfall)
        WHERE {
          # Net Cash Flow component
          {
            SELECT ?investorId
                   (SUM(xsd:decimal(?amount)) AS ?cashFlowAmount)
            WHERE {
              ?cashFlow a wm:CashFlow ;
                        wm:cashFlowOfInvestor ?investor ;
                        wm:amount ?amount .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
          # Total Holding Gain component (only holdings with cost and current value)
          {
            SELECT ?investorId
                   (SUM(xsd:decimal(?gain)) AS ?holdingGain)
            WHERE {
              ?holding a wm:PortfolioHolding ;
                       wm:heldByInvestor ?investor ;
                       wm:cost ?cost ;
                       wm:currentValue ?currentValue .
              ?investor wm:investorId ?investorId .
              FILTER(xsd:decimal(?cost) > 0 && xsd:decimal(?currentValue) >= 0)
              BIND(xsd:decimal(?currentValue) - xsd:decimal(?cost) AS ?gain)
            }
            GROUP BY ?investorId
          }
          # Total Scenario Allocation Shift component
          {
            SELECT ?investorId
                   (SUM(xsd:decimal(?shift)) AS ?allocationShift)
            WHERE {
              ?scenario a wm:ScenarioRebalancing ;
                        wm:scenarioRebalancingOfInvestor ?investor ;
                        wm:currentAllocationPct ?currentAlloc ;
                        wm:newAllocationPct ?newAlloc .
              ?investor wm:investorId ?investorId .
              BIND(xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc) AS ?shift)
            }
            GROUP BY ?investorId
          }
          # Average Goal Shortfall component
          {
            SELECT ?investorId
                   (AVG(xsd:decimal(?shortfall)) AS ?goalShortfall)
            WHERE {
              ?goal a wm:InvestmentGoal ;
                    wm:belongsToInvestor ?investor ;
                    wm:shortfall ?shortfall .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
        }
        GROUP BY ?investorId
        HAVING (COUNT(DISTINCT ?component) = 4)  # Ensure all 4 components exist
      }
      # Min-max normalisation per component across the filtered investors
      {
        SELECT (MIN(?netCashFlow) AS ?minNetCashFlow)
               (MAX(?netCashFlow) AS ?maxNetCashFlow)
               (MIN(?totalHoldingGain) AS ?minTotalHoldingGain)
               (MAX(?totalHoldingGain) AS ?maxTotalHoldingGain)
               (MIN(?totalAllocationShift) AS ?minTotalAllocationShift)
               (MAX(?totalAllocationShift) AS ?maxTotalAllocationShift)
               (MIN(?avgGoalShortfall) AS ?minAvgGoalShortfall)
               (MAX(?avgGoalShortfall) AS ?maxAvgGoalShortfall)
        WHERE {
          # Recompute the components to get the min/max across the cohort
          {
            SELECT ?investorId
                   (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
                   (SUM(xsd:decimal(?holdingGain)) AS ?totalHoldingGain)
                   (SUM(xsd:decimal(?allocationShift)) AS ?totalAllocationShift)
                   (AVG(xsd:decimal(?goalShortfall)) AS ?avgGoalShortfall)
            WHERE {
              # Net Cash Flow
              {
                SELECT ?investorId
                       (SUM(xsd:decimal(?amount)) AS ?cashFlowAmount)
                WHERE {
                  ?cashFlow a wm:CashFlow ;
                            wm:cashFlowOfInvestor ?investor ;
                            wm:amount ?amount .
                  ?investor wm:investorId ?investorId .
                }
                GROUP BY ?investorId
              }
              # Total Holding Gain
              {
                SELECT ?investorId
                       (SUM(xsd:decimal(?gain)) AS ?holdingGain)
                WHERE {
                  ?holding a wm:PortfolioHolding ;
                           wm:heldByInvestor ?investor ;
                           wm:cost ?cost ;
                           wm:currentValue ?currentValue .
                  ?investor wm:investorId ?investorId .
                  FILTER(xsd:decimal(?cost) > 0 && xsd:decimal(?currentValue) >= 0)
                  BIND(xsd:decimal(?currentValue) - xsd:decimal(?cost) AS ?gain)
                }
                GROUP BY ?investorId
              }
              # Total Scenario Allocation Shift
              {
                SELECT ?investorId
                       (SUM(xsd:decimal(?shift)) AS ?allocationShift)
                WHERE {
                  ?scenario a wm:ScenarioRebalancing ;
                            wm:scenarioRebalancingOfInvestor ?investor ;
                            wm:currentAllocationPct ?currentAlloc ;
                            wm:newAllocationPct ?newAlloc .
                  ?investor wm:investorId ?investorId .
                  BIND(xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc) AS ?shift)
                }
                GROUP BY ?investorId
              }
              # Average Goal Shortfall
              {
                SELECT ?investorId
                       (AVG(xsd:decimal(?shortfall)) AS ?goalShortfall)
                WHERE {
                  ?goal a wm:InvestmentGoal ;
                        wm:belongsToInvestor ?investor ;
                        wm:shortfall ?shortfall .
                  ?investor wm:investorId ?investorId .
                }
                GROUP BY ?investorId
              }
            }
            GROUP BY ?investorId
            HAVING (COUNT(DISTINCT ?component) = 4)
          }
        }
      }
      # Normalise each component and combine
      BIND((?netCashFlow - ?minNetCashFlow) / (?maxNetCashFlow - ?minNetCashFlow) AS ?normNetCashFlow)
      BIND((?totalHoldingGain - ?minTotalHoldingGain) / (?maxTotalHoldingGain - ?minTotalHoldingGain) AS ?normTotalHoldingGain)
      BIND((?totalAllocationShift - ?minTotalAllocationShift) / (?maxTotalAllocationShift - ?minTotalAllocationShift) AS ?normTotalAllocationShift)
      BIND(1 - ((?avgGoalShortfall - ?minAvgGoalShortfall) / (?maxAvgGoalShortfall - ?minAvgGoalShortfall)) AS ?normAvgGoalShortfall)
      BIND((?normNetCashFlow + ?normTotalHoldingGain + ?normTotalAllocationShift + ?normAvgGoalShortfall) / 4 AS ?normalisedComponent)
    }
    GROUP BY ?investorId
    ORDER BY DESC(?compositeScore) ?investorId
    LIMIT 10
  }
}

