PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * ((?normNetCashFlow + ?normTotalGain + ?normTotalShift + ?normRiskScore) / 4) AS ?compositeScore)
    WHERE {
      # Subquery to compute raw components per investor
      {
        SELECT ?investorId
               (SUM(?cashFlowAmount) AS ?netCashFlow)
               (SUM(?holdingGain) AS ?totalGain)
               (SUM(?allocationShift) AS ?totalShift)
               (MAX(?riskScoreValue) AS ?riskScore)
        WHERE {
          # Net cash flow: sum of cash flow amounts
          {
            SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowAmount)
            WHERE {
              ?cashFlow a wm:CashFlow ;
                        wm:cashFlowOfInvestor ?investor ;
                        wm:amount ?amount .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
          # Total holding gain: sum of (currentValue - cost) for holdings with cost > 0
          {
            SELECT ?investorId (SUM(xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?holdingGain)
            WHERE {
              ?holding a wm:PortfolioHolding ;
                       wm:heldByInvestor ?investor ;
                       wm:cost ?cost ;
                       wm:currentValue ?currentValue .
              ?investor wm:investorId ?investorId .
              FILTER(xsd:decimal(?cost) > 0)
            }
            GROUP BY ?investorId
          }
          # Total scenario allocation shift: sum of (newAllocationPct - currentAllocationPct)
          {
            SELECT ?investorId (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc)) AS ?allocationShift)
            WHERE {
              ?scenario a wm:ScenarioRebalancing ;
                        wm:scenarioRebalancingOfInvestor ?investor ;
                        wm:newAllocationPct ?newAlloc ;
                        wm:currentAllocationPct ?currentAlloc .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
          # Risk score
          {
            SELECT ?investorId (MAX(xsd:decimal(?riskScore)) AS ?riskScoreValue)
            WHERE {
              ?health a wm:PortfolioHealth ;
                      wm:healthOfInvestor ?investor ;
                      wm:riskScore ?riskScore .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
        }
        GROUP BY ?investorId
        HAVING (
          COUNT(DISTINCT ?cashFlowAmount) = 1 &&
          COUNT(DISTINCT ?holdingGain) = 1 &&
          COUNT(DISTINCT ?allocationShift) = 1 &&
          COUNT(DISTINCT ?riskScoreValue) = 1
        )
      }
      # Min-max normalization subqueries
      {
        SELECT (MIN(?netCashFlow) AS ?minNetCashFlow) (MAX(?netCashFlow) AS ?maxNetCashFlow)
               (MIN(?totalGain) AS ?minTotalGain) (MAX(?totalGain) AS ?maxTotalGain)
               (MIN(?totalShift) AS ?minTotalShift) (MAX(?totalShift) AS ?maxTotalShift)
               (MIN(?riskScore) AS ?minRiskScore) (MAX(?riskScore) AS ?maxRiskScore)
        WHERE {
          # Recompute raw components for all investors (same logic as above)
          {
            SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
            WHERE {
              ?cashFlow a wm:CashFlow ;
                        wm:cashFlowOfInvestor ?investor ;
                        wm:amount ?amount .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId (SUM(xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?totalGain)
            WHERE {
              ?holding a wm:PortfolioHolding ;
                       wm:heldByInvestor ?investor ;
                       wm:cost ?cost ;
                       wm:currentValue ?currentValue .
              ?investor wm:investorId ?investorId .
              FILTER(xsd:decimal(?cost) > 0)
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc)) AS ?totalShift)
            WHERE {
              ?scenario a wm:ScenarioRebalancing ;
                        wm:scenarioRebalancingOfInvestor ?investor ;
                        wm:newAllocationPct ?newAlloc ;
                        wm:currentAllocationPct ?currentAlloc .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId (MAX(xsd:decimal(?riskScore)) AS ?riskScore)
            WHERE {
              ?health a wm:PortfolioHealth ;
                      wm:healthOfInvestor ?investor ;
                      wm:riskScore ?riskScore .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
        }
        GROUP BY ?investorId
        HAVING (
          COUNT(DISTINCT ?netCashFlow) = 1 &&
          COUNT(DISTINCT ?totalGain) = 1 &&
          COUNT(DISTINCT ?totalShift) = 1 &&
          COUNT(DISTINCT ?riskScore) = 1
        )
      }
      # Compute normalized components
      BIND((?netCashFlow - ?minNetCashFlow) / (?maxNetCashFlow - ?minNetCashFlow) AS ?normNetCashFlow)
      BIND((?totalGain - ?minTotalGain) / (?maxTotalGain - ?minTotalGain) AS ?normTotalGain)
      BIND((?totalShift - ?minTotalShift) / (?maxTotalShift - ?minTotalShift) AS ?normTotalShift)
      BIND((?riskScore - ?minRiskScore) / (?maxRiskScore - ?minRiskScore) AS ?normRiskScore)
    }
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

