            wm:hasRiskTolerance ?riskToleranceNode .
  ?riskToleranceNode rdfs:label ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * AVG(?normalisedComponent) AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
        WHERE {
          ?cashFlow wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?cashFlowAmount ;
                    wm:investorId ?investorId .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(ABS(xsd:decimal(?rebalanceAmount))) AS ?totalRebalanceAmount)
        WHERE {
          ?rebalancing wm:rebalancingActionOfInvestor ?investor ;
                       wm:amount ?rebalanceAmount ;
                       wm:investorId ?investorId .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?sectorTotalInvestment)) AS ?totalSectorInvestment)
        WHERE {
          ?sectorAlloc wm:allocationOfInvestor ?investor ;
                       wm:totalInvestment ?sectorTotalInvestment ;
                       wm:investorId ?investorId .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (AVG(xsd:decimal(?riskScoreValue)) AS ?riskScore)
        WHERE {
          ?health wm:healthOfInvestor ?investor ;
                  wm:riskScore ?riskScoreValue ;
                  wm:investorId ?investorId .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }

      BIND(xsd:decimal(?netCashFlow) AS ?cf)
      BIND(xsd:decimal(?totalRebalanceAmount) AS ?ra)
      BIND(xsd:decimal(?totalSectorInvestment) AS ?si)
      BIND(xsd:decimal(?riskScore) AS ?rs)

      {
        SELECT (MIN(?cf) AS ?minCF) (MAX(?cf) AS ?maxCF)
               (MIN(?ra) AS ?minRA) (MAX(?ra) AS ?maxRA)
               (MIN(?si) AS ?minSI) (MAX(?si) AS ?maxSI)
               (MIN(?rs) AS ?minRS) (MAX(?rs) AS ?maxRS)
        WHERE {
          {
            SELECT ?investorId (SUM(xsd:decimal(?cashFlowAmount)) AS ?cf)
            WHERE {
              ?cashFlow wm:cashFlowOfInvestor ?investor ;
                        wm:amount ?cashFlowAmount ;
                        wm:investorId ?investorId .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId (SUM(ABS(xsd:decimal(?rebalanceAmount))) AS ?ra)
            WHERE {
              ?rebalancing wm:rebalancingActionOfInvestor ?investor ;
                           wm:amount ?rebalanceAmount ;
                           wm:investorId ?investorId .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId (SUM(xsd:decimal(?sectorTotalInvestment)) AS ?si)
            WHERE {
              ?sectorAlloc wm:allocationOfInvestor ?investor ;
                           wm:totalInvestment ?sectorTotalInvestment ;
                           wm:investorId ?investorId .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId (AVG(xsd:decimal(?riskScoreValue)) AS ?rs)
            WHERE {
              ?health wm:healthOfInvestor ?investor ;
                      wm:riskScore ?riskScoreValue ;
                      wm:investorId ?investorId .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
        }
      }

      FILTER(BOUND(?cf) && BOUND(?ra) && BOUND(?si) && BOUND(?rs))

      BIND((?cf - ?minCF) / (?maxCF - ?minCF) AS ?normCF)
      BIND((?ra - ?minRA) / (?maxRA - ?minRA) AS ?normRA)
      BIND((?si - ?minSI) / (?maxSI - ?minSI) AS ?normSI)
      BIND((?rs - ?minRS) / (?maxRS - ?minRS) AS ?normRS)

      BIND((?normCF + ?normRA + ?normSI + ?normRS) / 4 AS ?normalisedComponent)
    }
    GROUP BY ?investorId
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

