PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
          (100 * ((?normNetCashFlow + ?normTotalRebalanceAmount + ?normTotalScenarioShift + (1 - ?normAvgGoalShortfall)) / 4) AS ?compositeScore)
    WHERE {
      # Subquery to compute all four components per investor
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
               (SUM(xsd:decimal(?rebalanceAmount)) AS ?totalRebalanceAmount)
               (SUM(xsd:decimal(?scenarioShift)) AS ?totalScenarioShift)
               (AVG(xsd:decimal(?goalShortfall)) AS ?avgGoalShortfall)
        WHERE {
          # Get investor IDs that have all four components
          ?investor a wm:Investor ;
                    wm:investorId ?investorId .

          # Net cash flow: sum of cash flow amounts (inflows negative, outflows positive per spec)
          ?cashFlow wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?cashFlowAmount .

          # Total rebalance amount: sum of rebalancing action amounts
          ?rebalancing wm:rebalancingActionOfInvestor ?investor ;
                       wm:amount ?rebalanceAmount .

          # Total scenario allocation shift: sum of (newAllocationPct - currentAllocationPct)
          ?scenario wm:scenarioRebalancingOfInvestor ?investor ;
                    wm:newAllocationPct ?newAlloc ;
                    wm:currentAllocationPct ?currentAlloc .
          BIND (xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc) AS ?scenarioShift)

          # Average goal shortfall
          ?goal wm:belongsToInvestor ?investor ;
                wm:shortfall ?goalShortfall .
        }
        GROUP BY ?investorId
        HAVING (COUNT(DISTINCT ?cashFlow) > 0 
                AND COUNT(DISTINCT ?rebalancing) > 0 
                AND COUNT(DISTINCT ?scenario) > 0 
                AND COUNT(DISTINCT ?goal) > 0)
      }

      # Compute min and max across investors for each component
      {
        SELECT (MIN(?netCashFlow) AS ?minNetCashFlow)
               (MAX(?netCashFlow) AS ?maxNetCashFlow)
               (MIN(?totalRebalanceAmount) AS ?minTotalRebalanceAmount)
               (MAX(?totalRebalanceAmount) AS ?maxTotalRebalanceAmount)
               (MIN(?totalScenarioShift) AS ?minTotalScenarioShift)
               (MAX(?totalScenarioShift) AS ?maxTotalScenarioShift)
               (MIN(?avgGoalShortfall) AS ?minAvgGoalShortfall)
               (MAX(?avgGoalShortfall) AS ?maxAvgGoalShortfall)
        WHERE {
          {
            SELECT ?investorId
                   (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
                   (SUM(xsd:decimal(?rebalanceAmount)) AS ?totalRebalanceAmount)
                   (SUM(xsd:decimal(?scenarioShift)) AS ?totalScenarioShift)
                   (AVG(xsd:decimal(?goalShortfall)) AS ?avgGoalShortfall)
            WHERE {
              ?investor a wm:Investor ;
                        wm:investorId ?investorId .

              ?cashFlow wm:cashFlowOfInvestor ?investor ;
                        wm:amount ?cashFlowAmount .

              ?rebalancing wm:rebalancingActionOfInvestor ?investor ;
                           wm:amount ?rebalanceAmount .

              ?scenario wm:scenarioRebalancingOfInvestor ?investor ;
                        wm:newAllocationPct ?newAlloc ;
                        wm:currentAllocationPct ?currentAlloc .
              BIND (xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc) AS ?scenarioShift)

              ?goal wm:belongsToInvestor ?investor ;
                    wm:shortfall ?goalShortfall .
            }
            GROUP BY ?investorId
            HAVING (COUNT(DISTINCT ?cashFlow) > 0 
                    AND COUNT(DISTINCT ?rebalancing) > 0 
                    AND COUNT(DISTINCT ?scenario) > 0 
                    AND COUNT(DISTINCT ?goal) > 0)
          }
        }
      }

      # Min-max normalization for each component
      BIND ((?netCashFlow - ?minNetCashFlow) / (?maxNetCashFlow - ?minNetCashFlow) AS ?normNetCashFlow)
      BIND ((?totalRebalanceAmount - ?minTotalRebalanceAmount) / (?maxTotalRebalanceAmount - ?minTotalRebalanceAmount) AS ?normTotalRebalanceAmount)
      BIND ((?totalScenarioShift - ?minTotalScenarioShift) / (?maxTotalScenarioShift - ?minTotalScenarioShift) AS ?normTotalScenarioShift)
      BIND ((?avgGoalShortfall - ?minAvgGoalShortfall) / (?maxAvgGoalShortfall - ?minAvgGoalShortfall) AS ?normAvgGoalShortfall)
    }
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?investorName ?segment ?riskTolerance
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:segment ?segment ;
            wm:riskTolerance ?riskTolerance .
  FILTER NOT EXISTS { ?investor wm:timeHorizon ?anyTimeHorizon . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * ((?normNetCashFlow + ?normTotalRebalance + ?normRiskScore + (1 - ?normAvgShortfall)) / 4) AS ?compositeScore)
    WHERE {
      # Subquery to compute raw components per investor
      {
        SELECT ?investorId
               (SUM(IF(?type IN ("Redemption", "Withdrawal"), ?amount, -?amount)) AS ?netCashFlow)
               (SUM(ABS(?rebalanceAmount)) AS ?totalRebalance)
               (AVG(?riskScore) AS ?avgRiskScore)
               (AVG(?shortfall) AS ?avgShortfall)
        WHERE {
          ?investor a wm:Investor ;
                    wm:investorId ?investorId .

          # Cash flows
          OPTIONAL {
            ?cashFlow wm:cashFlowOfInvestor ?investor ;
                      wm:type ?type ;
                      wm:amount ?amount .
          }

          # Rebalancing actions
          OPTIONAL {
            ?rebalancing wm:rebalancingActionOfInvestor ?investor ;
                         wm:amount ?rebalanceAmount .
          }

          # Risk score
          OPTIONAL {
            ?health wm:healthOfInvestor ?investor ;
                    wm:riskScore ?riskScore .
          }

          # Goal shortfall
          OPTIONAL {
            ?goal wm:belongsToInvestor ?investor ;
                  wm:shortfall ?shortfall .
          }
        }
        GROUP BY ?investorId
        HAVING (COUNT(?type) > 0 && COUNT(?rebalanceAmount) > 0 && COUNT(?riskScore) > 0 && COUNT(?shortfall) > 0)
      }

      # Min-max normalization across the filtered set
      {
        SELECT (MIN(?netCashFlow) AS ?minNetCashFlow)
               (MAX(?netCashFlow) AS ?maxNetCashFlow)
               (MIN(?totalRebalance) AS ?minTotalRebalance)
               (MAX(?totalRebalance) AS ?maxTotalRebalance)
               (MIN(?avgRiskScore) AS ?minRiskScore)
               (MAX(?avgRiskScore) AS ?maxRiskScore)
               (MIN(?avgShortfall) AS ?minShortfall)
               (MAX(?avgShortfall) AS ?maxShortfall)
        WHERE {
          {
            SELECT ?investorId
                   (SUM(IF(?type IN ("Redemption", "Withdrawal"), ?amount, -?amount)) AS ?netCashFlow)
                   (SUM(ABS(?rebalanceAmount)) AS ?totalRebalance)
                   (AVG(?riskScore) AS ?avgRiskScore)
                   (AVG(?shortfall) AS ?avgShortfall)
            WHERE {
              ?investor a wm:Investor ;
                        wm:investorId ?investorId .

              OPTIONAL {
                ?cashFlow wm:cashFlowOfInvestor ?investor ;
                          wm:type ?type ;
                          wm:amount ?amount .
              }

              OPTIONAL {
                ?rebalancing wm:rebalancingActionOfInvestor ?investor ;
                             wm:amount ?rebalanceAmount .
              }

              OPTIONAL {
                ?health wm:healthOfInvestor ?investor ;
                        wm:riskScore ?riskScore .
              }

              OPTIONAL {
                ?goal wm:belongsToInvestor ?investor ;
                      wm:shortfall ?shortfall .
              }
            }
            GROUP BY ?investorId
            HAVING (COUNT(?type) > 0 && COUNT(?rebalanceAmount) > 0 && COUNT(?riskScore) > 0 && COUNT(?shortfall) > 0)
          }
        }
      }

      BIND((?netCashFlow - ?minNetCashFlow) / (?maxNetCashFlow - ?minNetCashFlow) AS ?normNetCashFlow)
      BIND((?totalRebalance - ?minTotalRebalance) / (?maxTotalRebalance - ?minTotalRebalance) AS ?normTotalRebalance)
      BIND((?avgRiskScore - ?minRiskScore) / (?maxRiskScore - ?minRiskScore) AS ?normRiskScore)
      BIND((?avgShortfall - ?minShortfall) / (?maxShortfall - ?minShortfall) AS ?normAvgShortfall)
    }
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

