PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * AVG(?normalisedComponent) AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               (SUM(ABS(xsd:decimal(?amount))) AS ?netCashFlow)
        WHERE {
          ?cashFlow a wm:CashFlow ;
                    wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?amount .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?totalInvestment)) AS ?totalSectorInvestment)
        WHERE {
          ?sectorAlloc a wm:SectorAllocation ;
                       wm:allocationOfInvestor ?investor ;
                       wm:totalInvestment ?totalInvestment .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc)) AS ?totalScenarioShift)
        WHERE {
          ?scenarioRebal a wm:ScenarioRebalancing ;
                         wm:scenarioRebalancingOfInvestor ?investor ;
                         wm:newAllocationPct ?newAlloc ;
                         wm:currentAllocationPct ?currentAlloc .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
        WHERE {
          ?portfolioHealth a wm:PortfolioHealth ;
                           wm:healthOfInvestor ?investor ;
                           wm:riskScore ?riskScore .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      BIND(xsd:decimal(?netCashFlow) AS ?cf)
      BIND(xsd:decimal(?totalSectorInvestment) AS ?si)
      BIND(xsd:decimal(?totalScenarioShift) AS ?ss)
      BIND(xsd:decimal(?avgRiskScore) AS ?rs)
    }
    GROUP BY ?investorId ?cf ?si ?ss ?rs
    HAVING (COUNT(DISTINCT ?component) = 4)
  }
  {
    SELECT (MIN(?cf) AS ?minCF) (MAX(?cf) AS ?maxCF)
           (MIN(?si) AS ?minSI) (MAX(?si) AS ?maxSI)
           (MIN(?ss) AS ?minSS) (MAX(?ss) AS ?maxSS)
           (MIN(?rs) AS ?minRS) (MAX(?rs) AS ?maxRS)
    WHERE {
      {
        SELECT ?investorId
               (SUM(ABS(xsd:decimal(?amount))) AS ?netCashFlow)
        WHERE {
          ?cashFlow a wm:CashFlow ;
                    wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?amount .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?totalInvestment)) AS ?totalSectorInvestment)
        WHERE {
          ?sectorAlloc a wm:SectorAllocation ;
                       wm:allocationOfInvestor ?investor ;
                       wm:totalInvestment ?totalInvestment .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc)) AS ?totalScenarioShift)
        WHERE {
          ?scenarioRebal a wm:ScenarioRebalancing ;
                         wm:scenarioRebalancingOfInvestor ?investor ;
                         wm:newAllocationPct ?newAlloc ;
                         wm:currentAllocationPct ?currentAlloc .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
        WHERE {
          ?portfolioHealth a wm:PortfolioHealth ;
                           wm:healthOfInvestor ?investor ;
                           wm:riskScore ?riskScore .
          ?investor wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      BIND(xsd:decimal(?netCashFlow) AS ?cf)
      BIND(xsd:decimal(?totalSectorInvestment) AS ?si)
      BIND(xsd:decimal(?totalScenarioShift) AS ?ss)
      BIND(xsd:decimal(?avgRiskScore) AS ?rs)
    }
    GROUP BY ?investorId
    HAVING (COUNT(DISTINCT ?component) = 4)
  }
  BIND((?cf - ?minCF) / (?maxCF - ?minCF) AS ?normCF)
  BIND((?si - ?minSI) / (?maxSI - ?minSI) AS ?normSI)
  BIND((?ss - ?minSS) / (?maxSS - ?minSS) AS ?normSS)
  BIND((?rs - ?minRS) / (?maxRS - ?minRS) AS ?normRS)
  BIND((?normCF + ?normSI + ?normSS + ?normRS) / 4 AS ?normalisedComponent)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

