PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?segment (AVG(xsd:decimal(?sharpeRatio)) AS ?avgSharpeRatio)
WHERE {
  ?investor a wm:Investor ;
            wm:hasSegment/wm:label ?segment ;
            wm:hasPortfolioHealth/wm:riskScore ?riskScoreStr .
  ?goal a wm:InvestmentGoal ;
        wm:belongsToInvestor ?investor ;
        wm:avgSharpeRatio ?sharpeRatioStr .
  BIND(xsd:decimal(?riskScoreStr) AS ?riskScore)
  BIND(xsd:decimal(?sharpeRatioStr) AS ?sharpeRatio)
  FILTER(?riskScore > 50)
}
GROUP BY ?segment
ORDER BY ?segment

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?segment (ROUND(AVG(?returnsPct), 2) AS ?avgAnnualReturn)
WHERE {
  ?investor a wm:Investor ;
            wm:segment ?segment ;
            wm:hasPortfolioHealth ?health .
  ?health a wm:PortfolioHealth ;
          wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 50)
  ?investor wm:hasHolding ?holding .
  ?holding a wm:PortfolioHolding ;
           wm:returnsPct ?returnsPct .
}
GROUP BY ?segment
ORDER BY ?segment

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investor ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasRiskTolerance ?riskToleranceObj .
  ?riskToleranceObj rdfs:label "Moderate" .

  ?investor wm:hasPortfolioHealth ?health .
  ?health wm:riskScore ?riskScoreStr .
  BIND(xsd:decimal(?riskScoreStr) AS ?riskScore)
  FILTER(?riskScore > 50)

  ?investor wm:hasInvestmentGoal ?goal .
  ?goal wm:progressPct ?progressPctStr .
  BIND(xsd:decimal(?progressPctStr) AS ?progressPct)

  {
    SELECT ?investor (AVG(?progressPct) AS ?avgProgress)
    WHERE {
      ?investor wm:hasInvestmentGoal ?goal .
      ?goal wm:progressPct ?progressPctStr .
      BIND(xsd:decimal(?progressPctStr) AS ?progressPct)
    }
    GROUP BY ?investor
  }
  FILTER(?avgProgress < 30)
}
GROUP BY ?investor ?investorId ?investorName ?riskScore ?avgProgress

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?investorName ?riskScore ?techAllocation
WHERE {
  ?investor a wm:Investor ;
