            wm:riskTolerance "Moderate" ;
            wm:hasPortfolioHealth ?health .

  ?health wm:riskScore ?riskScore .

  ?investor wm:hasSectorAllocation ?allocation .
  ?allocation wm:sector "Technology" ;
              wm:allocationPct ?techAllocation .

  FILTER (?riskScore > 75)
  FILTER (?techAllocation > 15)
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
