  ?investor a wm:Investor ;
            wm:hasPortfolioHealth ?health .
  ?health wm:goalMatchPct ?goalMatchPct .
  FILTER (xsd:decimal(?goalMatchPct) > 50)
  {
    SELECT ?investor (AVG(xsd:decimal(?progress)) AS ?avgProgress)
    WHERE {
      ?investor a wm:Investor ;
                wm:hasInvestmentGoal ?goal .
      ?goal wm:progressPct ?progress .
    }
    GROUP BY ?investor
  }
}
ORDER BY ?avgProgress
LIMIT 10

