  }
  FILTER (xsd:decimal(?avgProgress) < 30)

  {
    SELECT ?investor (AVG(xsd:decimal(?returnsPct)) AS ?avgReturn)
    WHERE {
      ?investor wm:hasHolding ?holding .
      ?holding wm:returnsPct ?returnsPct ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue .
      FILTER (xsd:decimal(?cost) > 0 && xsd:decimal(?currentValue) > 0)
    }
    GROUP BY ?investor
  }
  FILTER (xsd:decimal(?avgReturn) > 50)
}

