PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?avgGoalProgress ?avgHoldingDividends
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avgGoalProgress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPct .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
    HAVING (AVG(xsd:decimal(?progressPct)) > 50)
  }
  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?dividends)) AS ?avgHoldingDividends)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:dividends ?dividends .
      ?investor wm:investorId ?investorId .
      FILTER(xsd:decimal(?dividends) > 0)
    }
    GROUP BY ?investorId
  }
}
ORDER BY ASC(?avgGoalProgress)
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?timeHorizonLabel (ROUND(AVG(?returnsPct), 2) AS ?avgHoldingReturn)
WHERE {
  {
    SELECT ?investorId ?timeHorizonLabel
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasTimeHorizon/wm:label ?timeHorizonLabel .
      {
        SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avgProgress)
        WHERE {
          ?goal a wm:InvestmentGoal ;
                wm:belongsToInvestor ?investor ;
                wm:progressPct ?progressPct .
        }
        GROUP BY ?investorId
        HAVING (AVG(xsd:decimal(?progressPct)) > 30)
      }
      ?health a wm:PortfolioHealth ;
              wm:healthOfInvestor ?investor ;
              wm:riskScore ?riskScore .
      FILTER (xsd:decimal(?riskScore) > 50)
    }
  }
  ?holding a wm:PortfolioHolding ;
           wm:heldByInvestor ?investor ;
           wm:cost ?cost ;
           wm:currentValue ?currentValue ;
           wm:returnsPct ?returnsPct .
  FILTER (xsd:decimal(?cost) > 0 && xsd:decimal(?currentValue) >= 0)
}
GROUP BY ?timeHorizonLabel
ORDER BY ?timeHorizonLabel

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance (AVG(xsd:decimal(?dividends)) AS ?avgHoldingDividend)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance/wm:label ?riskTolerance ;
            wm:hasPortfolioHealth/wm:goalMatchPct ?goalMatchPct ;
            wm:hasInvestmentGoal/wm:avgSharpeRatio ?sharpeRatio ;
            wm:hasHolding/wm:dividends ?dividends .
  FILTER (xsd:decimal(?sharpeRatio) > 0.0 && xsd:decimal(?goalMatchPct) > 50)
}
GROUP BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?avgGoalProgress ?avgHoldingDividends
WHERE {
  {
    SELECT ?investorId (AVG(?progressPct) AS ?avgGoalProgress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPct .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
    HAVING (AVG(?progressPct) > 50)
  }
  {
    SELECT ?investorId (AVG(STRDT(?dividends, xsd:decimal)) AS ?avgHoldingDividends)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:dividends ?dividends .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
}
ORDER BY DESC(?avgGoalProgress)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT DISTINCT ?investor ?investorId
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:riskTolerance "Conservative" ;
            wm:hasPortfolioHealth ?health .
  ?health wm:riskScore ?riskScore .

  {
    SELECT ?investor (AVG(?progressPct) AS ?avgProgress)
    WHERE {
      ?investor wm:hasInvestmentGoal ?goal .
      ?goal wm:progressPct ?progressPct .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (AVG(?returnsPct) AS ?avgReturn)
    WHERE {
      ?investor wm:hasHolding ?holding .
      ?holding wm:returnsPct ?returnsPct ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue .
      FILTER (?cost > 0 && ?currentValue >= 0)
    }
    GROUP BY ?investor
  }

  FILTER (?avgProgress < 30 && ?avgReturn > 50 && ?riskScore > 50)
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
