  FILTER (?type IN ("Redemption", "Withdrawal", "Deposit", "SIP", "Lump Sum"))
}
GROUP BY ?investorId
HAVING (SUM(
  IF(?type IN ("Redemption", "Withdrawal"), xsd:decimal(?amount), -xsd:decimal(?amount))
