PREFIX wm: <https://wealth.example.org/ontology/>
SELECT DISTINCT ?investor ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:riskTolerance "Conservative" .

  {
    SELECT ?investor (AVG(?progressPct) AS ?avgProgress)
    WHERE {
