  ?investor a wm:Investor ;
            wm:investorName ?investorName ;
            wm:hasRiskTolerance ?riskTolerance .
  ?riskTolerance rdfs:label "Moderate" .

  {
    SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount ;
                wm:date ?date .
      FILTER (STRSTARTS(?date, "2025"))
    }
    GROUP BY ?investor
    HAVING (?netCashFlow < 0)
  }
}

