SELECT (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
WHERE {
  ?investor a wm:Investor ;
            wm:segment "Large Cap" ;
            wm:investorId ?investorId .
  ?cashFlow a wm:CashFlow ;
            wm:cashFlowOfInvestor ?investor ;
            wm:date ?dateStr ;
            wm:amount ?amount .
  BIND(xsd:date(?dateStr) AS ?date)
  FILTER(YEAR(?date) = 2025)
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?investorName ?totalNetCashFlow
WHERE {
  ?investor wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasRiskTolerance ?riskTolerance .
  ?riskTolerance rdfs:label "Aggressive" .

  ?cashFlow wm:cashFlowOfInvestor ?investor ;
            wm:amount ?amountStr ;
            wm:type ?typeStr .

  BIND(xsd:decimal(?amountStr) AS ?amount)

  BIND(IF(?typeStr IN ("SIP", "Lump Sum", "Deposit"), -?amount, ?amount) AS ?signedAmount)

  {
    SELECT ?investor (SUM(?signedAmount) AS ?totalNetCashFlow)
    WHERE {
      ?investor wm:investorId ?invId ;
                wm:hasRiskTolerance ?rt .
      ?rt rdfs:label "Aggressive" .

      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amountStr ;
                wm:type ?typeStr .

      BIND(xsd:decimal(?amountStr) AS ?amount)
      BIND(IF(?typeStr IN ("SIP", "Lump Sum", "Deposit"), -?amount, ?amount) AS ?signedAmount)
    }
    GROUP BY ?investor
  }
}
ORDER BY DESC(?totalNetCashFlow)
LIMIT 10

