PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?investorName ?totalNetCashFlow
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasRiskTolerance/wm:rdfs:label "Moderate" ;
            wm:hasCashFlow ?cashFlow .

  ?cashFlow wm:amount ?amountStr .
  BIND(xsd:decimal(?amountStr) AS ?amount)

  {
    SELECT ?investor (SUM(?adjAmount) AS ?totalNetCashFlow)
    WHERE {
      ?investor wm:hasCashFlow ?cf .
      ?cf wm:amount ?amtStr .
      BIND(xsd:decimal(?amtStr) AS ?amt)
      BIND(IF(?cf wm:hasCashFlowType/wm:rdfs:label "Redemption" ||
               ?cf wm:hasCashFlowType/wm:rdfs:label "Withdrawal", ?amt, -?amt) AS ?adjAmount)
    }
    GROUP BY ?investor
  }
}
ORDER BY DESC(?totalNetCashFlow)
LIMIT 10

