PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasRiskTolerance/wm:rdfs:label "Aggressive" ;
            wm:hasInvestmentGoal ?goal .

  ?goal wm:shortfall ?shortfall .
  FILTER(xsd:decimal(?shortfall) > 0) .

  ?investor wm:hasCashFlow ?cashFlow .
  ?cashFlow wm:date ?date ;
            wm:amount ?amount .
  FILTER(STRSTARTS(?date, "2025")) .

  {
    SELECT ?investor (SUM(xsd:decimal(?flowAmount)) AS ?netFlow2025)
    WHERE {
      ?investor wm:hasCashFlow ?flow .
      ?flow wm:date ?flowDate ;
            wm:amount ?flowAmount .
      FILTER(STRSTARTS(?flowDate, "2025"))
    }
    GROUP BY ?investor
    HAVING(?netFlow2025 < 0)
  }
}

